/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210311-3","meetingId":"r03-c-budget","date":"2021年3月11日","dateIso":"2021-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を190件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"私からは、３０７ページ、交通安全啓発費、それから３０９ページ、自転車走行環境整備工事、それから３２９ページ、（仮称）旗の台六丁目公園整備、３３３ページ、私道整備事業について質問します。区は、近隣住民との意見交換をされているようですが、参加メンバーの選出方法と人数、それからワークショップを何回行って、これまでどのような意見が出てきたかを教えていただければと思います。","respondent":"高梨公園課長","answer":"旗の台六丁目公園のワークショップについてですが、２５名の地域の方々に集まっていただいてワークショップを開催しています。本年度、４回のワークショップを開催しています。令和２年９月から本年１月にかけて４回開催いたしました。","voiceIndex":4,"id":"exchange-001"},{"speaker":"湯澤委員","kind":"確認","question":"ワークショップでもたくさんの意見があったとご説明いただきましたけれども、今回予定したワークショップ、４回のうち２回はリアル開催でありましたけれども、残りは書面開催ということであります。今後、住民との話し合いがされないまま着工となるのか、確認させてください。","respondent":"高梨公園課長","answer":"来年度、そういった意見を参考にしながら設計作業を進めていきたいというふうに考えております。設計作業が終わり工事の段階になる前に、最終的な公園計画案を、ワークショップの参加者のみならず、周辺の方々にお知らせする機会をつくりたい、このように考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問","question":"この公園設計の件で私が近隣住民と話していて強く感じたのは、トイレの設置の問題でありました。課長ももちろんご存じだと思いますけれども、意見が２つに分かれておりました。このトイレの設置問題に関しては、改めて近隣住民、特に隣接住民に対しては、具体的な想定を提示した上で意見を取りまとめるべきだと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"やはりそういった周辺の方々のご理解が得られないと、設置は難しいのかなといったような考えでございまして、現時点ではトイレは設置しない方向での計画案ということでお示しをさせていただいているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問・要望","question":"全ての近隣住民の納得を得るというのは大変難しいことだと思いますけれども、今後も近隣住民の声に耳を傾けて、地元の方に親しまれるような公園づくりに努めていただきたいと思います。そこで質問ですけれども、自転車通行帯には青い帯状の自転車レーン、それからナビライン、ナビマークとありますが、これらはどう違うのか。区民からの要望でも設置は可能なのか。","respondent":"溝口道路課長","answer":"私からは、自転車走行区間についての質問にお答えをします。車道等に入っていますマークといいますか、表示されているものですが、自転車ナビマークと自転車ナビラインという２種類のものを推奨して、今、整備を進めているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問","question":"自転車の走行する場所は、年齢によっても定められていますが、歩道を走る方がやっぱり多いと思います。特に朝はみんなが急いでおりますので、ほんの少しずつ無理をするような運転で、また、大型トラックが運搬までの時間潰しなどでナビラインの上に長時間停車している場合などもあります。このような状況を区はどう捉えて、改善に努める具体的な取組みなどがあれば教えていただければと思います。","respondent":"川口交通安全担当課長","answer":"ナビライン等に止まっている車については、それぞれ品川区内のほうでも、例えば区役所通りなどの放置駐車の重点地区等がありますので、そちらのほうで警察と連携した駐車をさせない措置の広報・啓発をやっているところです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問","question":"マナーを向上させるというのは本当に難しい問題だと考えています。東京都でも、現在、フードデリバリー自転車への番号制などを検討している動きがあるようです。通勤・通学の時間帯は、警察との連携などをして、自転車レーン内に駐停車禁止など、マナーと併せて自転車の安全を確保するべきだと思いますが、品川区のお考えをいま一度教えていただければと思います。","respondent":"川口交通安全担当課長","answer":"引き続き、そのような各種自転車の安全利用に向けた対策を行っていくとともに、また、今、委員からのご質問にありましたいわゆる宅配の自転車等の対策についても、警察と連携して、その安全利用に対する広報・啓発なりを進めてまいりたいと考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後に、私道整備事業についてです。私道は複数の個人が所有しているため、なかなか道路の補修にお金をかけようとすることがなく、経年劣化でガタガタになりがちだと思います。そのまま放っておくと転倒などの危険もあるので、ぜひこの事業を活用していただきたいと思うのですが、最近のこの事業の執行率について、どういった推移かを教えていただければと思います。","respondent":"長尾建築課長","answer":"私道整備事業の直近での利用実績の推移ですが、昨年度、令和元年度の時点では、約７割程度の執行率でした。それ以前につきましては、非常に申請される方が多く、９割以上の利用実績となっておりましたが、最近はちょっと減少傾向にあります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"湯澤委員","kind":"質問・要望","question":"執行率が下がっているということなのですけれども、理由は何かということが分かっていれば教えていただきたいと思います。ただ、区内には各地に多くの私道がありますので、執行率の低下に関係なく、町並みや、防災、安心安全の観点からも、今後も予算は維持していくべきと考えますけれども、区のご見解を最後にお聞かせいただければと思います。","respondent":"長尾建築課長","answer":"今後につきましては、このまま減少傾向をたどるとは考えておりませんので、来年度予算につきましても、現状、これまで要求しておりました予算と同額のものを要求して出しています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"冒頭に、今日は３・１１東日本大震災より１０年という大きな節目を迎えます。最初に、３２１ページ、立会川・勝島地区まちづくり検討経費、３２７ページ、公園・児童遊園維持管理費、３４５ページ、備蓄物資購入から取り上げてまいります。これまで区議会公明党がしながわ花海道の回遊性、また、防災の視点、地域の声を踏まえて、人道橋の設置を求めてまいりました。期待をしております。","respondent":"鈴木都市計画課長","answer":"立会川・勝島地区の人道橋のご質問ですが、基本的にこちらの検討は、令和元年度より検討を進めてまいりまして、今のところ、都市再生整備計画という計画を策定し、国の補助を受けながら事業を進めていきたいというところで、予定としますと。","voiceIndex":21,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"勝島地区は高齢化率が約４％でしたでしょうか。非常に若い方が多い地域でありまして、なかなかまちづくりビジョンに関わる、そこに声が届かないような方たちも多くいらっしゃいますので、お声を聞いていただく中に、そういうＰＴＡの方々、若い方々のお声もしっかりと聞いていただきたいと思っているのですが、その点はいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"当然ながら、ビジョン策定の段階でも広くアンケートをとって、そうした若い方の声もいただきながらつくってきたわけですが、今回、この都市再生整備計画を進める中で、いろいろと手法は考えていきながら。","voiceIndex":23,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。これまでの款別の質疑の中で、予算化はされないけれども、地域と連携をとって行っていくと確認をしています。八潮の周辺は、オリンピックの会場があったり、また、国道３５７号線の上下線の開通で非常に湾岸地域の利便性が向上しております。これらの声をこのまちづくり検討の中でしっかりと伺っていただきながら、八潮のまちづくりを進めていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"来年度、今まで検討を進めてきたところをベースにして、年度替え当初から、ワークショップという形で地域の方々のお声を聞きながら、最終的にはガイドラインの取りまとめを目指していきたいです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問","question":"公園・児童遊園維持管理費についてお伺いいたします。当初予算案で示されているこの公園の改修に関して、どこの公園なのか、まずお知らせください。","respondent":"高梨公園課長","answer":"それと、東八ツ山公園では擁壁が傷んでおりますので、その改修工事。それと、庁舎の前にありますしながわ中央公園、こちらの水系設備の設備修繕工事を計上しています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ここの公園は、区内小学校の子どもたちとワークショップを行って２０１１年にリニューアルをされた非常に人気のある公園であります。砂場の整備です。ぜひこの改修もお願いしたいと思います。何か地面にここは止めてはいけないと、バギーの絵を描くとか、何かそういう意識啓発をして、バギーの方もしっかりと通れるような、そういう対策を併せてしていただきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"２点目の入り口における自転車やバイク等の駐輪、またバギーが入れないといったようなことにつきましては、かねてから公園利用者以外の駐輪が問題になっているところですので、今までも啓発に力を入れてきたところですが、引き続き、常駐の管理人がいる公園ですので。","voiceIndex":29,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、備蓄物資購入のところで関連をしてお伺いいたします。公明党女性委員会は、３月１日から８日の女性の健康週間に関連いたしまして、３月２日に、「＃みんなの生理」の谷口共同代表に講師をしていただいて、この生理をめぐる課題を伺い、３月４日の参議院の予算委員会で、佐々木さやか参議院議員が、オンラインでのアンケートの結果、生理用品を買うのに苦労している人が５人に１人いる。","respondent":"平原防災体制整備担当課長","answer":"こちらですが、令和元年度に入替えを行いまして、次回の入替えのタイミングといたしましては、令和６年度となっている関係で、有効活用には令和５年度を予定しております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"この災害備蓄をこういうことで使うのはどうかと思うのですけれども、本当に緊急事態、異常なコロナでありましたので、入替えのタイミングではないということは承知した上で申し上げますが、全部とは言いません、ぜひ、何か少し活用できないのかということを期待して要望させていただきたいと思いますけれども、いま一度ご答弁をお願いいたします。","respondent":"平原防災体制整備担当課長","answer":"現在備蓄しております生理用品の活用というようなお話ですけれども、委員ご指摘のとおり、こちらの生理用品につきましては災害時の活用ということで、市中から物がなくなった際に、避難者に向けてご活用いただくというもので備蓄しておりますが、コロナ禍において。","voiceIndex":33,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"前向きなご答弁をいただきました。生理用品がないということは、本当に女性にとってはつらいことであります。アルバイト代も平均２万４,０００円減ったというようなアンケート調査もありまして、学生にとっては、生理用品を買うということが本当に困難な状況が現実にありますので、早急なご対応をしていただきまして、具体的に取組みをお進めいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、３４１ページ、防災訓練経費、３４３ページ、防災情報配信経費、消防団運営補助金、３４５ページ、帰宅困難者対策経費について、順不同にお聞きいたします。どんどん周知をしていただきたいと思います。停電によりテレビがつかない。新しいものになると予算計上されておりますが、どのようなものに変わって、また、この防災ラジオというのはどういう意味があるのかのご説明をお願いいたします。","respondent":"平原防災体制整備担当課長","answer":"新しい防災ラジオについてのお尋ねですけれども、今回検討しています防災ラジオは、防災行政無線のデジタル化に伴いまして、現行の機種が自動起動しなくなるということに伴って、新たな自動起動型のラジオとして導入するものです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"松澤委員","kind":"意見","question":"機能にはあまり変わりがないということと、あと、防災行政無線の補完というところ、よく分かりました。では、聞こえにくいと言われていますこの防災行政無線、これをどうしていくのかなど、検討がされているのかをお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"防災行政無線の聞こえにくさのお尋ねですけれども、現在、防災行政無線の発信電波のデジタル化移行を５か年計画で進めているところです。","voiceIndex":39,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"２０局増設されて１５５局ですね。いろいろとお金がかかったり難しい問題だと思いますが、聞き取りにくいなどとよく電話が入る地域、先ほど役所の方も行かれていると言いますけれども、ある程度どこら辺が聞き取りづらいかなどの把握をしているところはあるのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"聞き取りにくいところの地域というようなお話ですけれども、聞き取りにくいといったご意見をいただきまして係員が現地調査を行うものといたしましては、年間で十数件ほどありますが、現在のところは、特に地域によっての偏りはございません。","voiceIndex":41,"id":"exchange-019"},{"speaker":"松澤委員","kind":"意見","question":"ある程度、地域がもし分かっていたら、そこにこの防災ラジオ、これは約１万円ぐらいします。これを無料で配布したり、また、高いので、助成制度を使って安くしてあげるとか、そういった対応をしていただければ、こういう聞き取りにくいと言われている課題であったり、情報弱者と言われている高齢者の助けになると考えますが、ご見解をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"それに当たりましては、どのような普及方法が効率的か、助成方法等も含めながら検討してまいりたいというふうに考えてあります。","voiceIndex":43,"id":"exchange-020"},{"speaker":"松澤委員","kind":"意見","question":"しっかりとした周知とともに、品川区に広がることを願います。すみません、防災訓練に戻します。訓練だけで全てを対応できないが、訓練しないと対応ができない。そのような言葉があるように、訓練はやらないと、いざというときに対応ができません。昨年度、区内一斉防災訓練では、開催する地区、しなかった地区とばらつきが見えましたが、防災訓練の必要性について、ご見解をお聞かせください。","respondent":"大森災害対策担当課長","answer":"その中では、防災訓練の実施につきまして、防災区民組織の役割であるということで示しています。したがいまして、区といたしましても、その自助、共助、これらの育成のためには、防災訓練については不可欠なもの、このように認識しております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"松澤委員","kind":"確認","question":"ポイントが２つ。１つ目が、コロナ禍において１か所に集まるのが難しい状況を踏まえ、オンラインで避難方法や避難所、避難経路の確認ができるということです。２つ目が、いつ始まるか分からないということです。所要時間は５分。それは親子で参加することも可能なはずではないでしょうか。このようなオンラインでの防災訓練、今後、必ず必要になると思いますが、ご見解をお聞かせください。","respondent":"大森災害対策担当課長","answer":"こちら、令和３年度につきましては、一部のコースをオンライン講座として実施する予定です。ご紹介等のありましたＬＩＮＥにつきましても、現在、防災行政無線への連携など、防災業務への活用を進めているところです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"でも、本来はそういうわけではないですよね。このシェイクアウト訓練というのは、１分間で簡単にできる訓練とされており、ＹｏｕＴｕｂｅでも配信されております。こういうものは簡単にできて、自分で考えて行動できる、臨機応変に対応する能力が身につくと思いますので、こういった訓練もどんどん行政より発信していただいて、防災に対する意識を高めていただきたいと思いますが、ご見解をお聞かせください。","respondent":"大森災害対策担当課長","answer":"この訓練については、単独でも、その他の訓練に組み合わせても実施が可能ですので、区で作成しております「しながわ防災訓練ガイド」、これらなどの活用を図りながら、区民への周知に努めてまいりたいと考えております。","voiceIndex":49,"id":"exchange-023"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひそういったいろいろな防災訓練のやり方を検討していただきたいと考えています。さて、先ほど、オンライン防災訓練の話をしましたけれども、課長答弁の中で、防災課では新しい防災タブレットを各町会・自治会長へ配付したと聞いております。普段使いに特化したものに変わっているとお聞きしますが、前回の反省を活かし、どのように変わっていったのでしょうか。教えてください。","respondent":"平原防災体制整備担当課長","answer":"現時点では、まだ使用方法などにつきましてのご説明をしている段階ですので、具体的な情報の発信であるとか、受信、共有、こういったものについては、まだまだ検討という段階です。","voiceIndex":51,"id":"exchange-024","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"提案","question":"まだまだこれからの検討になることが分かりました。今後の活用の視点としまして、先ほどご提案しましたけれども、タブレットを使った新しい防災訓練、こういうようなものをやはりぜひ町会・自治会で考えると、そういったものを周知して考えていただきたいと考えています。次に、消防団運営補助金についてお聞きします。品川区から出ているこの補助金が、どのように使われているものなのかを教えてください。","respondent":"大森災害対策担当課長","answer":"消防団運営補助金に関するお尋ねです。消防団の施設や資機材の整備につきましては、原則として東京都が実施しているものですが、区は、これらに加えまして、地域の実情に応じて、各消防団、分団が必要とする資機材整備などの補助を行っているところです。","voiceIndex":53,"id":"exchange-025","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問・要望","question":"東京都でやっていただいている補助金の足りない部分を品川区で補っていただいているというご答弁でした。そういうフォローが私は正に自治体の務めだと感じております。荏原地区は倒壊家屋の危険性が多くあります。エンジンカッターであるとか、エアージャッキなど、地域により違いがありますので、欲しいものをよく聞いていただいて、今後も続けていただきたいと願っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"３１９ページ、コミュニティバス、３２５ページ、大崎駅周辺地区再開発事業、大崎西口駅前地区について伺います。コミュニティバスは要望です。大井ルートと大崎ルートは全く違うルートなわけですから、他のルートの試行運転についても、４年を待たずに前倒し実施するよう要望したいと思います。伺います。土地所有者、借地権者、借家権者など、それぞれ伺います。再開発準備組合の組合員数は何人でしょうか。","respondent":"多並都市開発課長","answer":"当該地区につきましては、大崎駅の西口の駅前、約１.４ｈａの区域を対象に、平成２６年に準備組合が設立され、現在、組合の中で検討されているところです。土地所有者および借地権者が重複する方もいらっしゃるために、合わせて、現在１５名となっています。","voiceIndex":57,"id":"exchange-027"},{"speaker":"安藤委員","kind":"確認","question":"これ、準備組合の資料によれば、地区内にはマンションの区分所有者も加えると権利者は２６０名。借家権者は２００名と思っていたのですが、１５０名いるということです。しかし、準備組合員数は、各マンションから１名ずつということになって、計１３名にとどまっているということです。伺います。この文書について区は確認したのでしょうか。どのような内容だと認識しているのか伺います。","respondent":"多並都市開発課長","answer":"先ほどの組合の委員数、組合の中での話というお話をさせていただきましたけれども、数が少ないということですが、まずは最初に説明しますと、総会だとかそういう場では代表の方がいらっしゃっていますけれども、それ以外の説明会だとか検討いただくような場においては。","voiceIndex":59,"id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"準備組合に参加しているのは１３名なのです。マンションから１人しかというのは、ちょっと私は、これは非常に問題だと思っているのですけれども。確認したいのですが、再開発準備組合にニュー大崎マンションから参加している１名の方は、マンション管理組合の代表の方だと区は認識されているのでしょうか。その方の意見が、ニュー大崎マンションの代表の意見だと捉えているのでしょうか。伺います。","respondent":"多並都市開発課長","answer":"ただ、先ほど申しましたが、準備組合は、今後のまちをどういう再開発をしていきたいかということを皆さんで考えていただく場なので、そういう場合には必ず皆さんにお声かけして集まっていただいてご説明して、その場でいろいろとご意見をいただきながら進めているです。","voiceIndex":61,"id":"exchange-029"},{"speaker":"安藤委員","kind":"確認","question":"この文書の内容を全然精査していないですよね。準備組合からは代表者だと聞いていると、聞いているだけで区は確認していないということなのでしょうか。先ほど紹介した手続きは行われていませんということと、そもそもマンションの管理組合と市街地再開発準備組合に参加する立場にないではないかというところの指摘については、区としては、どのように考えているのかをしっかりとお答えください。","respondent":"多並都市開発課長","answer":"その後の再開発を進めるための組合の設立の場合は、法令に従って、権利者の方々、共有者の方一人ひとりに同意いただきながら進めるものでございまして、その際には、しっかりと確認しながら進める、そういうふうな段取りで進めると認識しています。","voiceIndex":63,"id":"exchange-030"},{"speaker":"安藤委員","kind":"確認","question":"準備組合ですが、このニュー大崎マンションの代表だというふうに認めているということで、そこだけ確認させてください。","respondent":"多並都市開発課長","answer":"代表者として出席しているということで準備組合から聞いているところです。","voiceIndex":65,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"もうしていきましょう。ですから、あそこをどうかスムーズに行けるようにしていただきたいと思うのですけれども、いかがでしょうか。それと、区民住宅、３３９ページ、この間はファミーユ下神明とファミーユ西五反田についてをお伺いしましたが、今回、区民住宅は全部で何戸あって、何戸入っていて、その差です、入っているのと、満室になったとき、その差は年間幾らになるのかを教えてください。","respondent":"稲田土木管理課長、川口交通安全担当課長、溝口道路課長、森住宅課長、佐藤木密整備推進課長、多並都市開発課長、長尾建築課長","answer":"こちらのところにつきましては、区といたしまして、第１１次品川区交通安全計画。１６３号線の整備の関係で、区役所前の交差点のところにつきましては、今現在、拡幅の整備を行っているところで、来年度につきましては電線共同溝。この使用料を合わせますと、年間１億３,０００万円余という形になる予定です。区としましては、周知が非常に重要だというふうに考えておりますので、この３月下旬に新しいパンフレットにつきまして。","voiceIndex":68,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"区民住宅なのですけれども、年間１億３,０００万円、物凄く大きい金額だと思うのですが、改めて、財政的には、この金額はどういうふうに考えているのか。財政課長、答弁をお願いします。","respondent":"品川財政課長","answer":"約１億円近くということで、非常に大きな金額というふうに考えております。様々な事業に投入できる金額ではないかというふうに考えております。","voiceIndex":76,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、３１９ページのまちづくりマスタープランをお伺いしたいのですけれども、家の整理をしていたら、『大井町Ｗａｌｋｅｒ』という雑誌が出てきたのです。そこで座談会と書いてあって、鈴木都市計画課長に似ている方が出ているのですけれども、これ、改めて鈴木都市計画課長ですか。","respondent":"鈴木都市計画課長","answer":"私です。","voiceIndex":80,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"この文書、座談会で凄くいいことをおっしゃっていて、まちづくりに関しては、駅を中心に同心円状にしていかないといけないみたいなことが書かれているのですけれども、それで、今度新しいまちづくりマスタープランを作る中で、私は、本会議でもお伺いしましたけれども、西大井駅、この駅に物凄く期待しているのですけれども、ここを同心円状として、西大井駅の開発をどういうふうに考えていくか。","respondent":"鈴木都市計画課長","answer":"こうした地域の強みを活かして、しっかりとマスタープランの中では様々な状況の変化だとかも検証しながら、西大井駅のより身近な生活拠点としての機能をさらに高めていく、魅力を高めていくという位置づけを、しっかりと整理検討していきたいです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"３２６ページ、公園管理費、３１９ページ、コミュニティバス、３３９ページ、居住支援事業、３４３ページ、避難行動要支援者経費、防災体制整備費、３０７ページ、駅周辺等放置自転車対策事業について伺います。その際に、発災時の停電での駐輪場対応について質問をし、後日、大森駅の地下駐輪場については、すぐにロックがかかり、自転車を取り出す際には、ちょっと時間がかかってしまうと伺いました。","respondent":"川口交通安全担当課長","answer":"ただ、大森駅の地下の機械式の駐車場の機械は大型ですので、例えば、発災時等において、そのような機器がもし停電した場合は、やはり専門の職員等において、安全をしっかりと確認した後に動かさなければならないというところですので、そういう対応については、各事業者等に。","voiceIndex":85,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"そこについても見解を伺います。続いて、公園・児童遊園について伺います。今後、公園計画を持つべきと考えますが、区の見解を伺います。新しい公園に喜ぶ声は、近隣だけでなく、区内各地の子どもや、子どもに関わる団体、保護者から届き、要望も多数ありました。これからの公園新設・改修では、ごく近隣だけへの説明にとどまらない区民が意見交換できる機会を求めたいのですが、いかがでしょうか。","respondent":"川口交通安全担当課長、高梨公園課長","answer":"停電が５分以上継続した場合は、駐輪ラックが自動に解除されまして、そこで精算もせずに自転車は取り出せるというふうになっているところです。その辺と併せて、周知につきましても何らか検討させていただければと考えています。今後は、整備する公園の規模に応じまして、意見を聞く範囲であるとか、周知方法については検討してまいりたいと思います。","voiceIndex":87,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"公園への意見を求める際には、周知の範囲はなるべく広めにとっていただいて、多くの方の意見を聞いていただきたいと思います。子どもや保護者等から意見を聞き、子ども期の体験を奪わないような選定をしてほしいと強く要望します。居住支援事業について伺います。そして協議会の進捗、評価、次回日程を伺います。窓口にたどり着けない人への周知が必要だと生活者ネットワークは考えますが、見解を伺います。","respondent":"高梨公園課長、森住宅課長","answer":"公園の計画についてですが、こちらも、それぞれの公園に応じてその地域のご要望であったり、状況等が異なるところがありますが、大きな公園の整備の方向性といったところでは、今。そのうち品川区に活動拠点を置いている法人としては特にないのですけれども、品川区も含めて活動範囲にしている団体は１５団体ありまして、複数の要配慮者に対応可能な団体が１０団体というふうになってあります。","voiceIndex":90,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"リーフレット等を活用されているということで、分かりました。区としても、このニーズ調査、ニーズ把握が必ず必要だと考えますが、改めて見解を伺います。そして、コミュニティバスについて伺います。そうではないという区の姿勢を確認したいという趣旨で質問をします。障害者には成人もいますし、子育てとは必ずしもニーズが重ならないと考えますが、なぜ一緒にまとめられてしまったのかを伺います。","respondent":"森住宅課長、鈴木都市計画課長","answer":"居住支援協議会につきまして、法人との連携というお話ですが、この３月８日から昨日までの間で、居住支援セミナーということで、賃貸住宅オーナーや不動産事業者の皆様向けに、こういった時期ですので、Ｚｏｏｍで配信をしまして。総合的に全ての方が利用しやすいコミュニティバスという考えのもと、検討を行っているという視点では間違いのないところです。","voiceIndex":93,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"居住支援事業についてです。チラシ配り等を行っていただきたいと強く要望いたします。少々遠回りになっても、福祉施設を経由して補完してほしいと強く要望いたします。見解を伺います。見解を伺います。続けます。品川区強靭化地域計画作成経費と、災害廃棄物処理計画作成経費について伺います。委託事業者はどのような専門性を持った事業者なのかを伺います。区の弱点などが見えてきたらお知らせください。","respondent":"鈴木都市計画課長、中島防災課長","answer":"試行の中での見直しですが、まずは大井ルートを４年間かけてしっかりと検証、改善を加えながら検討を進めていきたいです。強靱化の脆弱性のチェックシートにつきましては、今後、作成の中でしっかりと検討をしてまいりたいと思います。","voiceIndex":96,"id":"exchange-040"},{"speaker":"木村委員","kind":"質問","question":"３０７ページの下から７行目、駅周辺等放置自転車対策事業から、放置防止指導啓発、２,８７４万円余からの質問をいたします。この事業は、平成１３年頃からとお聞きしておりましたけれども、聞くところでは、国では昭和５５年頃、それに伴い品川区では昭和５６年に条例ができたともお聞きしました。現在のこの放置自転車対策の枠組みについてお聞かせください。","respondent":"川口交通安全担当課長","answer":"放置自転車対策についてのお尋ねです。現在、区では、条例に基づきまして、いわゆる放置自転車対策の柱です、まず自転車等駐車場の整備と、また併せまして、自転車利用者に対する啓発・指導、そしてまた、放置自転車等の撤去・保管業務ということで、これを柱に推進をしています。","voiceIndex":100,"id":"exchange-041"},{"speaker":"木村委員","kind":"質問","question":"放置自転車対策には、３つ目の柱があるということをお聞きいたしました。この３つの柱とは、もう一度どのようなことなのかをお聞かせください。","respondent":"川口交通安全担当課長","answer":"１点目の自転車等駐車場の設置ですけれども、こちらは、現在、区内におきましては、それぞれ区営で２６か所の自転車駐車場を整備しています。自転車利用者の方に自転車を放置していただかないようにするために、駅周辺等に自転車駐車場等の設置を行っているところです。","voiceIndex":102,"id":"exchange-042"},{"speaker":"木村委員","kind":"質問","question":"次にまいります。次に、３２７ページの公園・児童遊園維持管理費の中、公園施設ＬＥＤ化工事と、防犯カメラ保守・管理についてお聞きいたします。伺います。令和３年度に計上されている公園施設ＬＥＤ化工事は、公園施設の中、どの施設のＬＥＤ化を行うものでしょうか。今年度、予算書にも同じ項目が計上されていますけれども、今年度までどのようにＬＥＤ化を進めてきたのかをお聞かせください。","respondent":"高梨公園課長","answer":"今年度は、しながわ区民公園と天王洲公園のＣ面のナイター照明のＬＥＤ化工事を行ってあります。令和３年度についてですが、公園の管理事務所の照明のＬＥＤ化を行う予定となっています。","voiceIndex":104,"id":"exchange-043"},{"speaker":"木村委員","kind":"質問","question":"多くのメリットがあり、消費電力が少ないことから、ＣＯ２の削減など、地球環境保全にも寄与するＬＥＤ照明の設置を、今後もぜひ積極的に進めていってほしいと考えております。この後、残りの施設のＬＥＤ化について、どのように進めていくつもりでしょうか。伺います。","respondent":"高梨公園課長","answer":"今後のＬＥＤ化の進め方についてですが、しばらくは公園運動施設のＬＥＤ化と、管理事務所等のＬＥＤ化を進めていく計画です。並行して、公園便所の照明のＬＥＤ化にも取り組んでいく予定としています。","voiceIndex":106,"id":"exchange-044"},{"speaker":"木村委員","kind":"質問・要望","question":"分かりました。引き続き積極的に取り組んでいただくことを求めております。次に、防犯カメラ保守・管理についてお伺いいたします。そのような防犯カメラが公園に設置されることは、区民の安心に大いにつながっているものと認識しています。お聞きいたします。区が管理している公園・児童遊園における防犯カメラの設置状況はどのようになっているのでしょうか。台数も分かればお聞かせいただきたいと思います。","respondent":"高梨公園課長","answer":"防犯カメラの設置の状況ですが、令和元年度までに、非常に小さな広場型の公園等を除くほぼ全ての公園に防犯カメラの設置は完了しています。台数についてですが、本年２月末現在で２４４か所、３９６台のカメラを設置しています。","voiceIndex":108,"id":"exchange-045","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"ほぼ全ての公園に防犯カメラが設置されているということで、区民は非常に安心をしていることと思います。一方で、録画されている画像、データは、個人の顔が特定されるなど、データの取扱いは慎重にすべきと思います。防犯効果と、多くの安心をもたらす防犯カメラですが、数多く設置されている防犯カメラのデータについて、どのように処理されているのでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"公園に設置されている防犯カメラで録画されているデータについてですが、カメラの中に約１週間分の録画の保存ができることになってあります。データについては、逐次古いものから上書きされていくというような方式になっております。","voiceIndex":110,"id":"exchange-046"},{"speaker":"木村委員","kind":"質問","question":"区内には２６９の区立公園がありますけれども、いずれはこの全ての公園に設置をするということでしょうか。それとも、ある程度の広さが必要なのか。その規模を教えてください。","respondent":"高梨公園課長","answer":"今後改修する公園の規模であるとか、また交換する遊具の状況等に応じて、内容については積極的に反映をしていきたいと考えておりますが、なかなか全ての公園といったところは難しいかなというふうに考えてあります。","voiceIndex":114,"id":"exchange-047"},{"speaker":"木村委員","kind":"質問・要望","question":"どちらにしても子どもたちの夢を育む空間、夢とともに成長していくわけですから、大事にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"私からは、３０７ページ、区民交通傷害保険加入促進費、時間があれば、３４１ページ、防災関係組織経費について伺います。品川区では、令和元年度から区民の交通傷害保険事業が始まり、建設委員会の議事録を拝見したところ、令和元年度で１,３３３人の区民が加入されたと。初年度から半額になっているわけですけれども、加入促進費の中身と、予算が半減している理由について説明をお願いいたします。","respondent":"川口交通安全担当課長","answer":"区民交通傷害保険への加入に関するお尋ねです。こちらにつきましては、令和３年度ですけれども、おおむね３,０００人の加入の促進を求めて概算で求めたところです。主にこちらの費用負担につきましては、当然、加入促進のための費用、啓発費等に充てているところです。","voiceIndex":118,"id":"exchange-049"},{"speaker":"松本委員","kind":"意見","question":"品川区のウェブサイトにアップロードされております区民交通傷害保険のパンフレットなどを拝見したところ、７つのコースが用意されているかと思います。７つのコースから１つを選ぶというふうになっています。把握されているようでしたら、大まかで結構ですので、令和２年度は、どういうふうな割合になっているのかをご教示いただければと思います。","respondent":"川口交通安全担当課長","answer":"加入状況の主な内訳ですけれども、やはり委員からお話のあったＡＪコース、これは要するに加害者になった場合の補償ですけれども、こちらが一番多くて、令和２年度実績ですと、加入者数２,７４９人のうち２,０５０人、７４.６％がＡＪコースにご加入いただいているところです。","voiceIndex":120,"id":"exchange-050"},{"speaker":"松本委員","kind":"質問","question":"先ほど、コースが分かれているという話をさせていただいたのですけれども、この区民交通傷害保険のうち、被害を受けた場合のみを対象としているＡ、Ｂ、Ｃコースだけに加入して、保険はいろいろなところで付帯されているので、いろいろなところで入る可能性はあるのですけれども、ほかに自転車の損害賠償保険に加入していない場合には、Ａ、Ｂ、Ｃコースだけに入ってしまうと。","respondent":"川口交通安全担当課長","answer":"Ａ、Ｂ、Ｃコースについてのご質問ですけれども、確かにＡ、Ｂ、Ｃコースに加入した場合は、今、委員ご指摘のとおり、自転車の加害の義務を果たすことはできないのですが、ただ、自転車の利用によって生じた他人の生命または身体に損害を補償することができる保険は。","voiceIndex":122,"id":"exchange-051"},{"speaker":"松本委員","kind":"質問","question":"そうすると、区民からすると、パンフレットとかホームページを見たときに、東京都が何か保険の義務化をしたというところまでは知っている方が多いと思うのですが、ただ一方で、加害者になったというところまで認識がなくて、区の提供している保険だから、一番安いコースに入れば義務を果たせるのかなみたいに思ってしまう方も恐らくいらっしゃると思うのですが、今。","respondent":"川口交通安全担当課長","answer":"この区民交通傷害保険の自転車運転中の賠償保険の部分につきまして、来年度募集する受付のパンフレット等につきましても、赤い枠を設けて、こちらのコースで補償しますということで記載をさせていただいて、分かりやすく。","voiceIndex":124,"id":"exchange-052"},{"speaker":"松本委員","kind":"質問","question":"ご存じだと思いますけれども、賠償額がこの自転車のものは、昔は低いと思われていたのですけれども、最近１億円弱の賠償が命じられたものとかも出てきていて、１億円はやっぱり保険に入ってないと普通の人はもう払えない額だと思います。最後に、この区民の保険に限らず、今、区民がこの賠償保険にどのくらい入られているのかというのは、何か世論調査等は行われているのでしょうか。お願いします。","respondent":"川口交通安全担当課長","answer":"現在、区で把握しているのは区民交通傷害保険の加入状況なのですけれども、全体は２,７４９人の方に、今、加入いただいているところで、さらにそのほかにも、大体東京都ですと４６％というところで把握しております。","voiceIndex":126,"id":"exchange-053"},{"speaker":"芹澤委員","kind":"提案","question":"同じく３４３ページの新しい防災ラジオ導入。併せて、提案として、恐らく訓練として使っていらっしゃるのかと思いますが、やはり平時にどうやって使うのかということを検討していただきたいと思っていまして、例えば目黒川であったりとか、立会川であったりとかという橋の点検に、今、ドローンが活用され始めているかと思いますが、そういった活用の検討についてお聞かせください。","respondent":"中島防災課長、溝口道路課長","answer":"ドローンに関するお尋ねですが、ドローンにつきましては、委員ご指摘のとおり、災害時の初動期における情報収集を主な目的として、現在、職員が３名、操縦をできるように体制を整えております。加えて２名の養成をしています。そういった技術の進捗というか、画像だけではなくて、その画像をどう解析して改修につなげていくか、そういったところが一番大事になってくるところですので、技術の進展、そういったことも踏まえながら、今後。","voiceIndex":129,"id":"exchange-054"},{"speaker":"芹澤委員","kind":"質問・要望","question":"このドローンの整備については、以前から会派の中でも要望させていただいて、非常に前向きに様々検討していただいているので、大変ありがたいなと思っています。新しい防災ラジオ導入についても伺っていきます。そうすると、それぞれ区民が持っている防災ラジオが使えなくなるというわけではなくて、引き続きこれは使えるという認識でよろしいのでしょうか。そこについてご見解を聞かせください。","respondent":"中島防災課長","answer":"今回、令和元年度に区内一斉防災訓練で配布させていただきました小型のラジオについても、今後も使うことができるということでございまして、こちらについては、今回、試行的に訓練の中で配らせていただきまして、ラジオの配布などについては、今後。","voiceIndex":132,"id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問","question":"今のＦＭしながわですけれども、スマートフォンで聞けるというふうに伺っています。しながわ防災ハンドブックには周波数が載っているのですけれども、スマートフォンで聞けますというようなＰＲというのが、見落としていなければないように思うのです。ぜひこれはＱＲコードとか、今すぐではないですけれども、次の改訂のときに載せていただければと思います。ご見解をお聞かせください。","respondent":"中島防災課長","answer":"委員ご指摘のとおり、ラジオにつきましては、災害時、情報収集をする上で非常に有用な手段だと考えておりますので、引き続き啓発は努めてまいりたいと思います。","voiceIndex":134,"id":"exchange-056"},{"speaker":"芹澤委員","kind":"提案","question":"提案の１つ目として、以前、石田秀男委員からもお話があったかと思いますが、例えば屋形船を使って運送していくというようなご検討をされてはいかがかなと思っていまして、これから品川駅前が再開発をされて、北品川まで直通になるというふうに理解していますので、そこから例えば屋形船をプランの１つとして一緒にして、屋形船に乗ってきて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、３３９ページ、区営住宅管理費、３４３ページ、防災ラジオ、３４７ページ、弔慰金・見舞金経費からお伺いをします。喜びの声も伺っています。区営住宅においても、これはぜひご検討いただきたい。申請があった場合、お求めがあった場合には、これは区の負担で、公費負担で、従前からご自身のものでつけている方についてはお願いしたいと思いますが、いかがでしょうか。","respondent":"森住宅課長","answer":"現在お住まいの方については、ご自身で、取替え、修繕等を行っていただくということで現在考えておりますけれども、区営住宅の中では区で設置してほしい、修繕してほしいという声が特にまだ届いていませんけれども、都の状況を注視したり、あるいは。","voiceIndex":139,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"午前中も幾つかの質問がありました。その後、何度も要望し、決定的だったのは、東日本大震災が発災した直後の平成２３年の決算特別委員会の中で、公明党の浅野区議が総括質疑で示しました。これを決算特別委員会で浅野区議が示して、これは絶対に必要ですということで導入を強く求めたところ、品川区で初めて導入していただけるという検討をしていただきました。来年度の仕組みをお伺いしたい。","respondent":"平原防災体制整備担当課長","answer":"今後につきましては、大変申し訳ございません、まだ検討段階ではありますけれども、同様の考え方をもちまして、何らかの割引、同等の割引ということを前提に考えてあります。","voiceIndex":141,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その代わり、チェックができないので、その代替案というものを今お考えになっているということも伺ってはいるのですけれども、ぜひそういったことも含めて、もしかすると、今までよりは、ＦＭ電波ですから、ＦＭ電波といってもこれもデジタル、防災無線のデジタルではないけれども、デジタルのＦＭ電波が今飛んでいるということなので、聞きやすくなるのかなということで、ぜひ期待をしたいところと思います。","respondent":"中島防災課長","answer":"宿泊につきましても、委員ご指摘のとおり、ソレイユ戸越を設けているところでございまして、ホテル代などに関しましても、見舞金の中でご対応いただければというふうに考えているところです。","voiceIndex":143,"id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど毛布の話もありましたけれども、それもケース・バイ・ケースですが、やはり火災発生から１日経ってからというようなことも聞いております。ですから、そこのところは、ぜひ、おせっかい、人情の品川区としてご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-061"},{"speaker":"横山委員","kind":"質問","question":"私からは、３１９ページ、地域交通検討経費について、３２７ページ、公園・児童遊園整備費について、また時間があれば、３０９ページ、道路橋梁費についてをお伺いいたします。１点目に、地域交通検討経費についてお伺いいたします。コミュニティバスの見直し検討の基準について、まずはご説明をお願いいたします。","respondent":"鈴木都市計画課長","answer":"コミュニティバスの試行運行開始後の評価といいますか、そうしたところのお尋ねだと思うのですが、基本的には、様々検討してまいりましたが、試行期間、収支率５０％に行くか行かないかで、廃止も含めた検討を行うというふうな判断基準で今考えてあります。","voiceIndex":149,"id":"exchange-062"},{"speaker":"横山委員","kind":"確認","question":"前入間市議会議員の山本秀和さんより、市民の欲しいと乗るは違うため、乗る人が少なければ一定期間で廃止も含めて見直し基準を事前に決めておくことが大切だというお話を伺いました。試行運行後なのですけれども、本格導入する際にも、こうした見直し検討の基準ですとか、ガイドラインを事前に定めていただくということがとても重要かと思うのですが、今後の方向性を確認させてください。","respondent":"鈴木都市計画課長","answer":"先ほど、試行期間の評価基準についてご説明しましたが、これは当然、試行期間、本格導入後、走り出してからそうした評価基準を考えるのではなくて、事前に区としてもしっかりと設定をして考えていきたいというところで、本格導入に移行した後も、先ほどご説明した収支率は。","voiceIndex":151,"id":"exchange-063"},{"speaker":"横山委員","kind":"提案","question":"コミュニティバスの広告収入について、こちらは民間のノウハウを活かした提案をいただくということだと思うのですけれども、ほかの自治体では、車内窓上、車内出入口チラシ設置、車内放送、車内液晶画面、車体広告などの事例があるかと思いますが、区としては、どのような内容を想定しておられますでしょうか。","respondent":"鈴木都市計画課長","answer":"そうしたバス専門のノウハウを、その提案の中にもしっかりとご提示いただいて検討していきたいですが、いろいろと委員のほうからも例示いただきましたが、車の内外の公告ですとか、あるいは車内の放送ですとか、車体のラッピングですとか、あるいは。","voiceIndex":153,"id":"exchange-064"},{"speaker":"横山委員","kind":"質問・要望","question":"区では、人気声優の野沢雅子さんの声による防犯広報プロジェクトを実施しておりますが、私、こちらはすばらしいなというふうに思っておりまして、こうした人気声優による車内アナウンスなど、情報発信やＰＲ活動の工夫をお願いしたいというふうに要望いたしますが、いかがでしょうか。現在の実施状況なども含めて、区のお考えを聞かせください。","respondent":"鈴木都市計画課長","answer":"安全教室は、やはりしっかりと子どもたちにバスの乗り方を学んでいただいて、それはひいては、その利用率、利用のほうにもつながっていくというところも考えてありますので、バスを知ってもらって乗ってもらうという観点からも、これもまた。","voiceIndex":155,"id":"exchange-065"},{"speaker":"横山委員","kind":"提案","question":"これから様々プロポーザルを進めていく中でも、民間のノウハウなどの提案もあるかと思いますので、ぜひ品川区の魅力を高めていただけるように、民間の方と協力して進めていただけたらと考えています。２点目に、公園・児童遊園整備費についてお伺いいたします。","respondent":"高梨公園課長","answer":"やはり近隣の保育園・幼稚園からは、幼稚園のお迎えの後、遊んだりというようなことも考えられるので、幼児用の遊具がほしいといったようなご意見がありますので、現在は、幼児用の遊具を設置するといったところで考えているところです。","voiceIndex":157,"id":"exchange-066"},{"speaker":"横山委員","kind":"質問・要望","question":"地域のご意見は様々なものがあるかと思います。渋谷区の北谷公園では、今年４月１日にブルーボトルコーヒーが園内で開業するとの新聞記事を読みました。現在のＰａｒｋ－ＰＦＩの制度についてご説明をお願いいたします。Ｐａｒｋ－ＰＦＩを活用した公園整備を検討していただきたいというふうに思っておりますが、現在の検討状況を教えてください。","respondent":"高梨公園課長","answer":"渋谷区や新宿区のような先進事例がありますので、まずはそういった事例をしっかりと見ながら内部検討を進めていきたい、このように考えているところです。","voiceIndex":159,"id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"例えば、大規模公園の管理運営事業者を募集する際に、小規模公園と大規模公園の維持管理をセットで募集要項に含めるなど、区内にある公園の全体としての底上げをご検討いただきたいというふうに要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-068"},{"speaker":"せお委員","kind":"質問・要望","question":"今回の西霧ヶ谷公園などの改修は、近隣住民の声といいますか、遊具だけですので、利用者である子どもたちや保護者の声というのは聞かれましたでしょうか。今回は安全基準に合わせるための取替えと理解していますが、以前より小さい遊具になっているので、そうなるのであれば、ほかのスペースも利用して何かを設置するなど、公園全体の特性に合わせた改修をすべきと考えますが、見解を伺います。","respondent":"高梨公園課長","answer":"今後につきましては、少しの改良で遊具がもう少し大きなものがといったような状況もあろうかと思いますので、周辺の状況等をよく見ながら検討してまいりたいと思います。","voiceIndex":163,"id":"exchange-069"},{"speaker":"せお委員","kind":"質問・要望","question":"利用者の声をできるだけ反映して、遊具は子どもたちの楽しめるものにしていただきたいと思います。次に、しながわ区民公園改修工事についてお聞きします。そこでお聞きしたいのが、初めの中央ゾーンに取りかかる前からの、最初のしながわ区民公園全体を改修する際のコンセプトを教えてください。南側だけ、北側だけのコンセプトがあれば教えてください。","respondent":"高梨公園課長","answer":"広域避難場所という指定がありますので、一番大きなコンセプトといたしましては、広域避難場所としての防災性能の向上といったところで、中央ゾーン、南側ゾーンも、６ｍの幅を持った園路をしっかりと回し。","voiceIndex":165,"id":"exchange-070"},{"speaker":"せお委員","kind":"質問","question":"コンセプトについて、例えばですけれども、家族連れも、高齢者も、障害がある人も、スポーツを楽しみたい人も、自然、動物に触れたい人も、インクルージョンして、誰もが１日中楽しめる公園だったりとか、水族館を前面に出して水族館のある公園と銘打って、スポーツ施設が主ではある北側ゾーンも、水族館とリンクさせて改修するなど、いろいろと考えられると思いますけれども。","respondent":"高梨公園課長","answer":"今後の水族館の検討状況等につきましては、まだ現在、どういった形で、どこでといったところの詳細が決まっていない段階ですので、また、水族館のその後のことが決まり次第、公園については必要な対応をとっていきたい、このように考えているところです。","voiceIndex":167,"id":"exchange-071"},{"speaker":"せお委員","kind":"質問・要望","question":"コンセプトや方向性はすごく大事だと思っていて、品川区の色を出せるので、すごく大切にしてほしいなと思うところです。今はそれぞれのゾーンが、私にはばらばらに見えて、ですから、今からでも間に合う部分のコンセプトなどを、いま一度議論していただきたいなと、そこは要望します。ですから、飲食ができる場所もとても大切かと思います。","respondent":"高梨公園課長","answer":"一方で、隣接店舗との関係等もありますので、周辺状況等をよく鑑みながら、そちらについては検討を進めていきたいと考えております。","voiceIndex":169,"id":"exchange-072"},{"speaker":"せお委員","kind":"質問","question":"最後に、旗の台六丁目公園整備についてお聞きします。こちらは様々質問がありましたが、かぶらないようにお聞きします。ワークショップなのですが、４回行ったということですが、それでワークショップ自体は終了でしょうか。参加者は２５名ということでしたが、どのような方々、世代とか、性別とか、お話しできる範囲でお願いします。","respondent":"高梨公園課長","answer":"旗の台六丁目公園整備のワークショップにつきましては、今年度４回で終了ということで考えてあります。今年度いただいた意見をもとに、来年度、設計作業で様々な意見を反映していきたい、そのように考えているところです。","voiceIndex":171,"id":"exchange-073"},{"speaker":"せお委員","kind":"質問","question":"書面開催したということでしたが、書面開催ではワークショップの利点が丸きり消えてしまいます。コロナ禍はリモート開催すべきで、一方的にお知らせするのではなくて、議論していいものを生み出してほしいのですけれども、リモートを何らかの理由でできない方というのは、使い方をお教えしたり、機器を貸出しするなど、区がサポートして開催するべきと考えますが、見解をお聞かせください。２点お願いします。","respondent":"高梨公園課長","answer":"その中で特に若い世代の方々に積極的に参加していただけるような工夫については、今後、検討をしてまいりたいと考えています。ワークショップにつきまして、全４回のうちの第３回と第４回は、地域からのご要望もあって書面開催という形にさせていただきました。","voiceIndex":173,"id":"exchange-074"},{"speaker":"せお委員","kind":"質問・要望","question":"ワークショップですが、東京都に、子どもたちのアイデアのときのワークショップを好事例と捉えていただいているようですので、公園整備でワークショップを行っている自治体も少ないようですし、すばらしい取組みですので、今後も継続して、さらには発展させて、誰もが利用できる公園を整備していただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-075"},{"speaker":"おくの委員","kind":"提案","question":"区は、大井ルートの試行運行を他の２つのルートに先立って実施するために、事業者選定プロポーザルで提示する運行条件を発表し、運賃については、１００円や１５０円などの提案も可能としながら、２２０円を基本だとしました。これはなぜなのでしょうか。１００円を基本としていただきたいのですけれども、いかがでしょうか。１００円にしていただきたいのですが、いかがでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"コミュニティバスの運賃についてですが、ご紹介いただきましたように、プロポーザルの前提条件として、今、２２０円というところで考えているわけですが、基本的には、１００円、１５０円、２２０円、それぞれについて収支を検討しています。","voiceIndex":177,"id":"exchange-076"},{"speaker":"おくの委員","kind":"質問","question":"収支率ということでしたけれども、他方、コミュニティバスを導入しているのが、今、２３区中１８区あります。これら１１の区で１００円ということができて、なぜ品川にできないのか。１００円にできるのではないでしょうか。もう一度、お伺いいたします。","respondent":"鈴木都市計画課長","answer":"今、他区の状況をご紹介いただきましたが、２２０円で設定している区も６区あるというところの中で、１００円の実施で行っている区のその判断評価基準、評価基準を設定しているかどうかについても情報収集として整理しております。","voiceIndex":179,"id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ、ほかの１００円に設定しているところ、収支率、どういうことなのか、調査願いたいと思います。学んでいただきたいと思います。考慮しきれていない要素がたくさんあるのだと思うのです。そういう視点から見た上で料金設定も考えていかなければいけないのだと思います。そういう意味で、収支率５０％以上という判断基準は、私は必要ないと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区のコミュニティバスの考え方ですが、基本的には区内の充実した鉄道、あるいは民間のバス、こうした誰もが身近に利用していただける地域公共交通は基本方針の中でもお示ししていますが、その充実した公共交通手段をコミュニティバスは補完していくというのが大きな役割です。","voiceIndex":181,"id":"exchange-078"},{"speaker":"おくの委員","kind":"質問・要望","question":"再開発に支出される補助金５０億円、１００億円といった額から見れば、本当にスズメの涙ほどの額なのです。ですから、社会福祉に支出される額としては、ごくごく少額だと思います。そういう意味で、収支率５０％以上という判断基準は撤廃して、１００円にするということを強く要望いたします。それから、シルバーパスは使えるように考えられているのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"シルバーパスについては、事業主体の東京都とこれから確認、協議をしっかりとしていきたいです。","voiceIndex":183,"id":"exchange-079"},{"speaker":"くにば委員","kind":"質問","question":"本日は、３４３ページ、防災体験ＶＲ運用費、時間がありましたら、３４５ページ、民間アプリを活用した緊急情報伝達経費についてお伺いします。防災体験ＶＲ運用費です。この防災体験ＶＲの導入から、現在、来年度の運用までを一貫してお聞きします。導入された際、平成３０年度の約９３０万円の予算に対して、決算で約１,１００万円になりました。この１,１００万円の契約内容、内訳等をお知らせください。","respondent":"中島防災課長","answer":"その経費といたしまして７３８万円です。ＶＲを見るためのパソコン類、あと、ゴーグルの機器類、それのレンタルといたしまして３６３万５,２８０円というふうになっていまして、およそ１,１００万円という内訳となっております。","voiceIndex":186,"id":"exchange-080"},{"speaker":"くにば委員","kind":"質問・要望","question":"併せまして、まず、運用開始後の経費についてもお伺いします。この９３万円の内訳を教えていただきたいのと、令和２年度は、ＰＣ版が７６万５,６００円、これが３台、スマートフォン版が８万５,８００円、こちらが６台となっています。ＰＣ版の台数、こちらは４台から３台に減りましたけれども、それを減らした経緯と、単価が下がった理由もお聞かせください。","respondent":"中島防災課長","answer":"平成３０年度と令和元年度のところの細かい内訳が、今、手元にないところですが、まず、ＰＣ版とスマートフォン版の台数に関しましては、当初４台で運用開始をさせていただいたところですが、令和２年度、今年度は。","voiceIndex":188,"id":"exchange-081"},{"speaker":"くにば委員","kind":"質問","question":"すみません、内訳を伺いたいです。ＰＣ版が７６万５,６００円、このうち幾らが実際のレンタル、ノートパソコン、ヘッドセットのゴーグル、あとはリモコンもありました。その内訳をお聞かせください。","respondent":"中島防災課長","answer":"そのほかにスマートフォン版の機器類が約９万円でございまして、それが６台分で約５３万円となっています。最後に、スマートフォン版のソフトウェアの賃借料が約２万円の６台分で１２万円というふうになっております。","voiceIndex":190,"id":"exchange-082"},{"speaker":"くにば委員","kind":"質問","question":"平成３０年度に作ったソフトウェアのオリジナルコンテンツ、これはその後、コンテンツが追加されたり、バージョンアップしたりしているのでしょうか。お聞かせください。","respondent":"中島防災課長","answer":"平成３０年度に作りましたオリジナルコンテンツにつきましては、特に変更、バージョンアップ等はしておりませんで、その運用当初のものを使っているところです。","voiceIndex":192,"id":"exchange-083"},{"speaker":"くにば委員","kind":"意見","question":"続きまして、令和３年度予算約２９４万円のうち、ソフトレンタル代を除いたパソコンと周辺機器一式のレンタルで、令和２年度までに、今までにかかった金額、令和３年度を含めて、先ほどおっしゃっていましたけれども、ハードウェアのレンタル代が３台でパソコン周辺機器、レンタル代だけで年間１２０万円です。令和２年度までにかかったハードウェアのレンタル代だけで幾らかかったのかをお聞かせください。","respondent":"中島防災課長","answer":"基本的にそれほど年間で変わりないので、ＰＣ版の１２０万円のスマートフォンに関する経費が約５０万円だといたしまして、年間１７０万円の過去３年分ですので、おおむね５００万円ぐらいだというふうに考えております。","voiceIndex":194,"id":"exchange-084"},{"speaker":"くにば委員","kind":"質問","question":"今までもろもろお伺いしました。これが約３万２,０００円。これは、２０万円以下で買えます。１５万円から２０万円で買えるものを、毎年、一番最初の契約どおりに、特に契約の更新とか見直しをせずにそのまま４０万円で買い続けてしまっているので、ここに関しては、ソフトウェアと契約を分離して、切り離して購入したほうが安くなると思うのですけれども、ご見解をお聞かせください。","respondent":"中島防災課長","answer":"金額の中には、故障対応でありますとか、コンテンツのインストール、またそういう不具合の対応、それぞれもろもろも含まれておりますので、そういうところを総合的に判断して、この金額として妥当だと考えているところです。","voiceIndex":196,"id":"exchange-085"},{"speaker":"くにば委員","kind":"質問・要望","question":"加えて、こちらの実際の機器に関しても、先方が実際に用意したもの、これがもう現行の金額では１５万円ぐらいのものをずっと４０万円かけて、年間１２０万円かけてリースをし続けているというのは、これは契約を必ず見直すべきだと思います。見直したほうがいいというよりは、見直すべきだというふうに考えますので、時間がないので、そちらに関しては要望という形でお伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-086"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３４５ページ、災害時応急物資確保費、避難所管理費について、また、３３７ページ、空き家等対策事業についてお伺いいたします。今日で東日本大震災から１０年目を迎えました。現在、区が想定しています区民避難所の収容人数は１２万人と聞いておりますが、この１２万人、どのような基準に基づいて１２万人と想定されているのかをお答え願います。","respondent":"中島防災課長","answer":"こちらにつきましては、平成２４年度に東京都が被害を想定した際に、東京湾北部地震で建物被害やライフラインなどの被害によりまして、住居に住めなくなった方を避難者数として約１８万５,０００人想定しておりまして、そのうちの６５％を避難所生活者ということで。","voiceIndex":200,"id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"地域によっては想定されます避難民の数と、また、避難所の規模がなかなかマッチしていないのではないかという地域の声を聞いております。もちろんこれ、数字全てが避難されるわけではないと思いますが、それでも、一見すると、避難所の規模を見ますと、不均衡を感じますが、その辺りはどのように調整をされているのか、基準があれば教えてください。","respondent":"中島防災課長","answer":"今回の伊藤学園につきましては、ほかの避難所の補完避難所という形になっているところでもございまして、単体というよりも総合的に考える必要がありますので、そういうところから慎重な対応が必要なのかというふうに考えているところです。","voiceIndex":202,"id":"exchange-088"},{"speaker":"小芝委員","kind":"質問","question":"今、課長の答弁で、伊藤学園が大井三丁目の方々からすれば、補完避難所としての役割を担うというような答弁をいただいたと思うのですけれども、この避難所の対象エリアを、小学校や義務教育学校の前期課程の通学区域と同様に再編成するだとか、もしくは、避難所に指定されていない民間施設のフリースペースを提供していただき。","respondent":"中島防災課長","answer":"避難所につきまして、通学区域に関して完全に一致しているとか、そういうところの調整は、過去の経緯等もありますので、なかなか難しいところもありますが、ほかのフリースペースというか、避難所の拡大につきましては、正にコロナの感染症対策の関係で、ホテルの利活用とか。","voiceIndex":204,"id":"exchange-089"},{"speaker":"小芝委員","kind":"意見","question":"地域の町会や自治会は、避難所の備蓄に相当な不安を抱えている方々もいらっしゃいます。町会・自治会で予算を編成する上で、備蓄品の確保を避難所との関係でどのくらい用意しておけばいいのかを把握したいという声が現に上がっております。恐らく、都、政府からの援助が届くまでの間と考えますが、都からの援助、政府からの援助は、震災発生時から一体いつを想定しているのかをお答え願います。","respondent":"平原防災体制整備担当課長","answer":"さらに４日目以降につきましては、政府がプッシュ型支援ということで、被害の状況等々に応じて、政府が分量を算定いたしまして、地域内輸送拠点まで区の要望を待たずに送ってくるというような流れとなっております。","voiceIndex":206,"id":"exchange-090","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"今、課長からの答弁ですと、初日は区の備蓄で対応されるですが、そうなりますと、避難所運営の主体が町会・自治会であるというふうに認識はしておりますが、それとともに現場で対応される品川区の職員の方もいらっしゃると聞いております。１つの区民避難所に大体何名くらいの職員が対応されて、どのような役割を担うのかを教えていただければと思います。","respondent":"中島防災課長","answer":"避難所に参集する職員についてですが、基本的に時間外に参集するという、緊急的に参集するという想定のもとで、各避難所に８名から１０名の職員を割り当てているところです。そのうち係長級以上の職員が２名、また、男女の配分などもしっかりと考えて割当てをしています。","voiceIndex":208,"id":"exchange-091","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"ここまでは避難所運営をお聞きしましたが、次に質問するのは、地域におけます消火訓練、これも共助の１つであると認識しています。ぜひそれをお願いしたいというふうに言われているのですが、その辺はどのようにお考えでしょうか。","respondent":"中島防災課長","answer":"消火栓の場所にということが理想ですが、我々も置き場所というのは、やはりそういう形で利便性が高いところで考えているところですけれども、なかなか実際の置く場所は具体的なところですので、そこは引き続き検討してまいりたいと思います。","voiceIndex":210,"id":"exchange-092"},{"speaker":"小芝委員","kind":"質問","question":"ぜひ今後、検討して取り組んでいただければと思いまして、次の質問に移ります。空き家ですが、今年の１月１７日に民放で放映されました「ＴＶタックル」で、品川区の空き家問題が扱われておりました。空き家であっても管理する相続人がいれば問題は生じないのですが、そういう方がいない場面で、近隣から品川区にどういった相談が現状多いのか、主な相談内容を教えていただければと思います。","respondent":"森住宅課長","answer":"空き家に対する相談の内容ですけれども、委員ご紹介いただきました枝が伸びて自分の敷地まで来ているというところが、統計をとっているわけではございませんけれども、かなりの割合だというふうに認識をしております。","voiceIndex":212,"id":"exchange-093"},{"speaker":"小芝委員","kind":"質問","question":"品川区では、相続人の調査をするにあたって、あらかじめ相続人調査委託費用を計上していて、それは司法書士にお願いしているですが、相続人が判明しました場合は、課題解決に至るため、一般的にはどのような取組みがなされているのでしょうか。","respondent":"森住宅課長","answer":"それがなされなければ、再度送って、何度も通知をしながら、それぞれの相続人に管理を促しているという形です。","voiceIndex":214,"id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"行政から所有者に問題の解決を促したとしても、なかなか解決に至らず、やっぱり手をこまねいている状況であることも推察いたします。近隣住民からすれば、落ち度がない中で、当たり前の生活空間を脅かされる事態になれば、それこそ裁判で判断してもらう選択肢も想定されるわけです。近隣住民が相続人を相手に例えば裁判を起こすような場合、品川区でどういったサポートがなされるのかを教えてもらえますか。","respondent":"森住宅課長","answer":"最悪そういった事態になれば、区のほうでは、裁判所の求めに応じて、それぞれこれまでの対応記録等を提出しながら協力していくということになろうかと思います。","voiceIndex":216,"id":"exchange-095"},{"speaker":"小芝委員","kind":"質問","question":"例えば、実際に近隣の方が弁護士に支払う裁判費用などの経費の一部を補助するなど、側面でサポートすることもできるのではないかと考えますが、その辺りはいかがお考えでしょうか。","respondent":"森住宅課長","answer":"空き家の適正管理につきましては、相続人の方にそれぞれしっかりと法令に基づいた措置を取りながら、最悪は行政代執行ということもありますので、そういった対応を取りながら、空き家の解決に向けて進んでいきたいというふうに考えております。","voiceIndex":218,"id":"exchange-096"},{"speaker":"小芝委員","kind":"意見","question":"空き家問題は品川区だけの問題ではないので、地域の垣根を越えまして、他区の先進事例を取り入れたり、また、東京都、国と連携を引き続きとっていただき、取り組んでいただきますようお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"私からは、最初に３３３ページの公園総務費でいいのか、公園の使い方についてです。それから、同じく３３３ページですけれども、私道整備事業、それから３１１ページの無電柱化推進事業、この３点についてお伺いしたいと思います。ゲートボールをやられる団体とかが使っているかと思います。こういった使用申請によって使うことになっている公園は、区内にどれぐらいあるかを教えてください。","respondent":"高梨公園課長","answer":"今ご案内いただきましたとおり、広場や運動施設、無料開放されている運動施設を有する公園等において、利用者同士のバッティングがないように、おおむね１５名程度以上の団体で使用する際には、公園課のほうに公園使用の申請をしてくださいということで、ホームページをはじめ。","voiceIndex":222,"id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"広くいろいろ、場合によっては使っていけるのだというお話でした。こういったときに使用申請で使うと許可されたところは占有するというイメージなのか、やっぱりそこはちょっと整理が必要ではないかというふうに思うのですけれども、その辺の使い方についての区の考え方、どう整理されているかを教えてください。","respondent":"高梨公園課長","answer":"今後またこういったトラブルが多くならないように、窓口での案内や、また、必要に応じてホームページ等の広報でお知らせをしてまいりたい、そのように考えているところです。","voiceIndex":224,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"そこで、本年、そういった再整備がどれぐらい実施されてきているのか分かれば、実施の件数と、その再整備というのは、どういった条件のもとで実施をされるのかを教えてください。","respondent":"長尾建築課長","answer":"再申請される方の割合というところですけれども、統計はとっていないのですが、年に１件あるかないかというぐらいの状況です。利用いただく条件につきましては、初めてお使いいただく方と同様の条件でご案内しているところです。","voiceIndex":226,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"その辺の判断はなかなか、こういう場合にときっちりとした規定は難しいと思うのですが、先ほども、これまでの議論もありましたけれども、予算執行ということでは、令和元年度は７割程度といったところもございましたし、しっかりとこの予算を使っていただくというような観点も含めて、ぜひ積極的に再整備ということについても取り組んでいただきたいと思いますけれども、ご見解をお伺いします。","respondent":"長尾建築課長","answer":"初めてご利用いただく方にも、再度ご利用いただく方にも、先ほどご案内したように丁寧に対応してまいりたいと考えております。","voiceIndex":228,"id":"exchange-101","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"ぜひよろしくお願いしたいと思います。次に、３１１ページの無電柱化推進事業ですけれども、令和３年度の予算として、詳細設計等業務委託と、試掘工事ということで計上されております。この２つの詳細設計と試掘工事の事業内容について、詳しく教えてください。","respondent":"溝口道路課長","answer":"そのうちの２路線、１つは戸越公園周辺の補助２６号線から戸越公園につながるところの路線、あともう１つは、競馬場通りと言われまして、オリンピック会場周辺の整備で無電柱化を進めておりますが、国道までの間がまだ電柱が残っている状況になりますので。","voiceIndex":230,"id":"exchange-102"},{"speaker":"塚本委員","kind":"提案","question":"工期を短くする、このことについては、設計とか支障物件移設、本体工事、引込み管等、こういったいろいろなところが関わる工事に関して、包括発注方式というようなことを提案していらっしゃるようですけれども、品川区として、低コスト、またスピードアップ、この無電柱化推進において、国の動き等を踏まえて、今どのような考えで進めていこうと考えていらっしゃるのか、お知らせください。","respondent":"溝口道路課長","answer":"そちらにつきましては、やはりいろいろと昨今、国また都において検討が進められているところです。区といたしましても、新たな工法、そういったものは、今後、無電柱化の詳細設計等を進めていく中で、取り入れるものは取り入れていきたいというふうに考えているところです。","voiceIndex":232,"id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、掘り返してみて、あら、こんなところにこんな管がということで工期が延びる。それを掘り返す前に、アスファルトの上からレーザーみたいなものを当てるのですか、レントゲンみたいな感じで、中にどのようなものがあるかが掘り返す前に分かる、管が入っているのが事前に分かるという、このような技術が紹介されていました。","respondent":"溝口道路課長","answer":"無電柱化につきましては、様々国、都を含めて、新技術といいますか、新たな工法ですとか、そういったものが検討されているところです。様々先進事例等も出てきているところです。","voiceIndex":234,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"無電柱化は、品川区内は本当にたくさんあって、無電柱化計画で取り組むという、その道の長さも大変な長さで、そのうちの本当に第一歩がこれから始まるわけですけれども、本当に工法とかスピードアップということを常に改善しながら、早く実現できるように取り組んでいっていただきたいというふうに要望いたしまして、質問を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３２５ページの戸越公園駅周辺まちづくり事業に関わって、戸越小学校を公園にする計画について、３１８ページの都市計画費に関わって、羽田新ルートについて伺います。戸越公園です。つまり、計画は残っているのか、なくなったのか、改めて伺います。","respondent":"中道まちづくり立体化担当課長","answer":"戸越公園のまちづくりについてですが、地域のほうでは様々なまちづくりの検討をしています。その中で文庫の森と戸越公園を一体化し、まちの魅力を高め、地域の活性化につなげていきたいといったことを聞いてあります。その中で戸越公園のところにはまちづくり協議会があります。","voiceIndex":238,"id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"協議会としても考えはない。次に、羽田新ルートです。要請書には、大惨事になりかねない可能性と、今般の事案を断じて看過することはできないと認識を示し、同様の事故を繰り返すことがないよう、再発防止などを要望しています。しかし、区は文書を出さないということで、品川区は今回の事故を区民に重大な被害をもたらす事故だと認識しているのかどうかを伺います。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただきましたアメリカの航空機の事案ですが、ルート直下にある品川区としても、非常にこの事案については重く受け止めているところです。","voiceIndex":240,"id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"私が聞いたのは、区民に重大な被害をもたらす可能性のあるこうした事故だと認識があるのかを伺いましたので、ご答弁ください。","respondent":"鈴木都市計画課長","answer":"ご答弁申し上げたとおり、重く受け止めておりますし、あってはならない事象だというふうに理解しています。","voiceIndex":242,"id":"exchange-108"},{"speaker":"のだて委員","kind":"質問","question":"重く受け止めているとは言いますが、区民に被害をもたらす事故だという認識が示されておりません。同じような落下物事故が品川上空でも起きると考えていないのか、改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当然ながら、この落下物事案、羽田、品川区上空に限らず、日本全国で落下物が起こってはいけないという認識は常に持っているところです。","voiceIndex":244,"id":"exchange-109"},{"speaker":"のだて委員","kind":"質問","question":"この品川でも同様な事故が起こる可能性があると、そうした認識があるのかと伺いました。しかし、重く受け止めているということしかお答えになりません。こうした同様の事故が起きた場合に、どのような被害になると区は考えているのかを伺います。","respondent":"鈴木都市計画課長","answer":"想定で何かを申し上げるということではございませんが、基本的には、落下物について、これはあってはいけないというのは再三ご答弁申し上げているとおり、落下物が起これば、それが市街地に落ちれば、場合によっては重大な被害につながるというところで。","voiceIndex":246,"id":"exchange-110"},{"speaker":"のだて委員","kind":"質問","question":"重大な被害をもたらすという認識をぜひ持っていただいて、これだけを見ても、この羽田新ルートは中止をすべきだと私は思います。国が、２０２０年６月に、羽田新経路の固定化回避に係る技術的方策検討会を設置しました。私も同じ思いです。そうなれば、品川の上を飛ぶことになります。国のこの検討会は、品川区の上を飛ぶことを固定化するものだと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今、委員のご紹介の中に、逆に固定化をするための検討会というお話もございましたが、区としての認識はそのようなことは思っていませんで、何らかの検討をいただいて、この今示されているルート案が、何らかの変更をしていただけるような方向で、今。","voiceIndex":250,"id":"exchange-111"},{"speaker":"のだて委員","kind":"質問","question":"国が今検討しているものは、この着陸方式、大きく分けて５つの方式、細かく分けると１２の方式ということで検討されておりますけれども、このどれもが着陸前には直進をしているというものになっています。直進をしたほうが安全と考えるならば、どのような検討をしてもこの品川区の上を飛ぶということになると思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には、国は、飛行方式の先進性や適用の可能性などを踏まえて検証し、今お示ししているルート、飛行方式についても、第３回の検討会のほうでは絞り込んでいく、メリット、デメリットも整理していくというように聞いていますので、検討会の内容について、区としては。","voiceIndex":252,"id":"exchange-112"},{"speaker":"のだて委員","kind":"質問","question":"区は、この検討会で品川の上を飛ばないことができると考えているのかを伺います。","respondent":"鈴木都市計画課長","answer":"現在の運行ルートを固定化していただかないようにお願いしているところですから、そういう期待を持って注視しています。","voiceIndex":254,"id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"この検討会で直進するということを検討しているわけですから、品川の上を飛ぶことはできないと中止を求めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":256,"id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、３０７ページの交通安全と、３３３ページの私道整備事業、３２２ページの都市開発費から、東五反田二丁目の計画について、３４５ページの避難所ならびに備蓄物資についてお伺いしたいと思います。事業者が警視庁との協議の上、計画したとのことですが、警視庁が地域の交通安全事情を理解されていないのであれば、区として改善を求めていただきたいと思いますが、いかがでしょうか。","respondent":"長尾建築課長、多並都市開発課長","answer":"私道へのカーブミラー等の設置についてですが、カーブミラーのような交通安全施設の設置につきましては、私道整備事業の中で助成の対象の施設となっておりますので、その私道の所有者の方等からご相談いただけましたら。ただ、委員から今ご指摘ありましたように、より周辺の地域の交通安全等も考えながら整備しなければいけないということで、それは伝えさせていただいているところでありますので、周辺の住民とも一緒に話し合いながら進めるということは。","voiceIndex":258,"id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから避難所のほうです。その意味では、生理用品でも同様に、５年更新であれば５分の１ずつ毎年という更新の仕方をしつつ、学校等における有効活用を考えていただければと思いますが、いかがでしょうか。それから、避難所についてです。御殿山小学校は、崖地に一部隣接しているとはいえ、建物も堅牢であり、避難経路を勘案すると、御殿山小学校を避難所として使うべきだと考えますが、いかがでしょうか。","respondent":"長尾建築課長、平原防災体制整備担当課長、中島防災課長","answer":"直接的にその合意形成の中に入っていってご協力できることというのは限られる部分であるのですけれども、よくお話を伺いながら。備蓄しております生理用品につきましては、先ほどご答弁させていただきましたとおり、現在は、備蓄期間５年。基本的には、この土砂災害警戒区域につきましては、東京都ともよく相談する必要がありますし、地域の方のご意見もよく理解できるところですので。","voiceIndex":261,"id":"exchange-116"},{"speaker":"あべ委員","kind":"質問","question":"行政の理屈も分からないわけではないですけれども、やっぱり安全と命を最優先に考えてご判断をいただければと思います。引き続きのご検討をよろしくお願いいたします。最後になります。橋梁ですが、目黒川の鈴懸歩道橋、これがライトアップのために通行止めになっておりますが、工期が非常に長いのと、工期が明示されておりません。改善をお願いいたしまして、私の質問を終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":265,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"災害復旧特別会計予算から、５６３ページ、今も出ていました避難所開設、運営費についてお聞きしたいと思います。大規模災害等の発生時には、家屋の倒壊や浸水による災害廃棄物は、区民生活の再建に非常に妨げになるものですので、この計画を作成していただいて、万が一の場合、有効性のあるものにしていただきたいと思いますが、この点につきまして、詳細についてご説明いただけますでしょうか。","respondent":"中島防災課長","answer":"これまで災害時の廃棄物につきましては、ごみ処理マニュアルあるいは瓦礫処理マニュアルなど、そういうマニュアルで対応することを考えていたところですが、やはり災害時に大量に発生する廃棄物を円滑に処理しまして、応急救助活動のみならず。","voiceIndex":267,"id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"仮置場というお話がございました。品川区の場合は、これは場所がないので、やはりこの辺、要望と同時に東京都との折衝、その辺も進めていっていただきたいと思いますので、これもちょっとお聞きしたいのと、それから、先日、地元で話をしていまして、この災害廃棄物の件だけではないのですけれども、地域の中で、最近、軽トラックとかトラックがあまりないという話が出ました。","respondent":"中島防災課長","answer":"委員ご指摘のとおり、やはり災害廃棄物を地域の方々が出しやすい場所とか、あと、それをまたどういうふうに集めていくかとかということで、やはり今回の計画の中では、場所の選定が大きなテーマとなっていると考えておりますので、そこについては。","voiceIndex":269,"id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"確認","question":"繰り返しになりますが、そういうことはないような形が一番望ましいのですけれども、万が一の場合に備えて、いろいろな計画、実効性のあるものをよろしくお願いしたいと思います。もう１点、災害時の物流関係について確認をさせてください。発災により避難所が開設された場合、避難所への物資の配送については、どのように体制がとられているのか、この点につきまして教えてください。","respondent":"平原防災体制整備担当課長","answer":"その後、時間の経過とともに、協力いただく民間事業者の体制が整いましたら、物資のプロです輸送事業者の皆様に物資の輸送を担っていただくということを考えているところです。","voiceIndex":271,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問","question":"分かりました。特に食料品関係の問題も気になっているのですけれども、５２ですか、避難所には、たしか３,０００食ぐらいの非常食を用意してあるのですが、新聞などを見てたら、「救援食事」という言葉も出ていたのですけれども、そういった食事を運搬する際の体制等も、もう既にある程度つくっていらっしゃるのかどうか、その点について教えてください。","respondent":"平原防災体制整備担当課長","answer":"ただし、東京都は、近隣のところ、品川区で言いますと、城南大橋第二備蓄倉庫というところが近隣になりますが、そちらから地域内輸送拠点までの輸送ということになりますので、そちらから各避難所、こちらは５２の避難所だけではなくて。","voiceIndex":273,"id":"exchange-121","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"確認","question":"はい、分かりました。区内ですと、民間事業者の場合の車庫代が高いので、結構区内に車を置いていないということも現実にあるそうなのです。殊に、万が一のときに環状７号線から中へ入るというのは、車が入ってこられないような状態になったとき、その輸送関係はちょっと心配も感じるのですが、ある程度、先に通行許可的なものは準備しておくことはできないのかどうか、その辺を１点確認です。","respondent":"平原防災体制整備担当課長","answer":"品川区地域防災計画の改定に併せまして、品川区のトラックのご協力の体制というところもお話し合いしていますので、そういったところで事前にこのトラックは間違いなく行けるということがありましたら、そういった対応をさせていただければと思ってあります。","voiceIndex":275,"id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"繰り返しになりますが、万が一がないような形がいいのですけれども、事前に連絡体制とか、災害対策本部との関係もあると思いますので、その辺、事前の準備をよろしくお願いしたいと思います。それから、受援体制もつくっていらっしゃると思うのですけれども、その辺も含めて、これからも検討を進めていっていただきたいと思います。お願いします。もう１点、公園です。","respondent":"稲田土木管理課長","answer":"委員ご指摘のところですけれども、都有地を区が道路として上部利用をしています。今までも道路敷の中の広場として開放していました。今後も、隣接して工事があるのですけれども、そこで工事車両が通ったりしますが、広場は残していきながらやっていきたいと思います。","voiceIndex":277,"id":"exchange-123"},{"speaker":"高橋（伸）委員","kind":"確認","question":"３０７ページ、規制・許可事務費、３１１ページ、街路灯等建替事業、３１１ページ、かむろ坂根上対策整備工事、３３５ページ、コンクリートブロック塀等安全化支援事業についてお伺いいたします。順番に行きます。これは確認なのですけれども教えてください。","respondent":"稲田土木管理課長","answer":"委員のおっしゃられたとおり、東急東横線に足場が倒れ込んだというところをきっかけにしまして、区は、区道に民間の足場設置とかを許可したりしている。","voiceIndex":280,"id":"exchange-124"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３１１ページ、街路灯等建替事業についてお聞きいたします。現在も旗の台地区でも取替え工事が行われています。そこで、令和２年３月現在で、これは事務事業概要なのですけれども、これまでの実績が８,７８２基、設置率が４６.２％、来年度が１,０９５基ということなのですけれども、今現在、どのぐらいの設置率があるのか、まず教えていただきたいと思います。","respondent":"溝口道路課長","answer":"今年度につきましては、同じように２月末現在ですが、約１,７００基ほどのＬＥＤ化を進めてきておりますので、さらに１万基に近いような形でのＬＥＤ化が進んできているところです。","voiceIndex":282,"id":"exchange-125"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"地域の声なのですけれども、取替えになって明るくなったという声を非常に多くいただいておりますので、これからも品川区の道路環境をよくしていただきたいと思います。続いて、次が３１１ページ、かむろ坂根上対策整備工事についてお伺いいたします。そのような中、全国初となる低コストの新工法を試験的に実施するということなのですけれども、もう少し詳しく教えていただきたいと思います。","respondent":"溝口道路課長","answer":"道路を深く掘らない関係がありますので工費も安くできる、そういったところでの新工法を検討して、来年度より実証実験をやっていきたいというふうに考えているものです。","voiceIndex":284,"id":"exchange-126"},{"speaker":"高橋（伸）委員","kind":"質問","question":"道路上の歩道もそうですけれども、例えば立会川の緑道とか、そういうところも、深さがないので、どうしても凹凸、根上りが出てくるというところで、それは公園課とも連携していかなければいけないと思うのです。今後の展開はどういうふうにされていくのか。よろしくお願いします。","respondent":"溝口道路課長","answer":"今回、初めて来年度に施工していきますので、今後、根上りの状況がどういう形になるのか、そういったものを短期、中期的に点検していく中で、この工法が有効だということであれば、まずは道路で採用していきたいと考えていますし。","voiceIndex":286,"id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。これは今、試験的に実施して、新しい工法でやっていきますといった中で、ここには「全国初」と書いてあるので、これが成功ですか、うまくいった場合は、報道関係に大きく、ぜひ広めていただきたいと思って、改めてそこだけよろしくお願いします。","respondent":"溝口道路課長","answer":"何件か自治体からも問い合わせが来ているところですので、今後もこういった工法、検証結果、そういったものも、適時、進捗状況に応じて議会等でも報告しながら進めていきたいというふうに考えているところです。","voiceIndex":288,"id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いします。続きまして、３３５ページ、コンクリートブロック塀等安全化支援事業についてお伺いいたします。そのような中、今、どれぐらい伸びているのかをお知らせいただきたいと思います。","respondent":"長尾建築課長","answer":"コンクリートブロック塀等安全化支援事業の実績についてですけれども、今年度、２月末時点ですけれども、助成実績としては４２件となっております。昨年度、令和元年度の助成実績としましては２２件ということでしたので、今年度は、約倍ぐらいの実績となっております。","voiceIndex":290,"id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはり土地の地形によっても、隣地境界のブロック塀が、やはり長辺を考えると、要するに、区の宅地の部分ですから、それは全然制度としては使えないと思うのですけれども、恐らくそういう声も届いていると思うのですが、制度をお願いしますとはできないと思うのですけれども、その辺はどういうふうにお考えになって、お問い合わせに対してどのようにお伝えしているのか、お知らせいただきたいと思います。","respondent":"長尾建築課長","answer":"残念ながら助成対象にはなっていないのですけれども、やはりその維持管理であるとか、不安に思われていることの内容をお伺いした上で、適宜チェックリストであるとか、相談先となる専門の事業者の方とかをご案内しながら、道路沿いの塀と併せて。","voiceIndex":292,"id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。それで、今回、拡充した点なのですけれども、設計費および工事管理費で、限度額が１５万円で出るという中で、どの程度見込んでいるのか。恐らくこれは事業者に対してのあれだと思うのですけれども、見解をお聞かせいただきたいと思います。お願いします。","respondent":"長尾建築課長","answer":"今年度拡充いたしましたものの中で、設計管理費等に上限１５万円ということで助成をスタートしております。こちらは来年度の予算の計上の中では、フェンスの新設などを２４件分見込んでおりますので、そちらと同じ件数分の申請をいただくところを想定して積んでおります。","voiceIndex":294,"id":"exchange-131","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。本当に高く評価していますので、今後ともこの耐震を兼ねたブロックに関しては、これからも幅広くやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-132","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"３１８ページの都市計画費に関わって、リニア中央新幹線について伺いたいと思います。ルート上で新たに３つの巨大な地下空洞も次々と確認されて、それらと外環道の大深度地下工事との因果関係を認める最終報告が出されました。現在の品川の進捗状況を簡単に教えてください。２つ目には、大深度は安全、地上には影響がないとの安全神話が崩れたと思いますが、区の見解をお聞かせください。","respondent":"中道まちづくり立体化担当課長","answer":"リニア中央新幹線の現在の状況ですが、令和元年１２月に、北品川の非常口の立坑が完成して、現在は横穴を掘るためのシールドマシンの組み立て、または地上部で発電施設の設置工事を実施中です。","voiceIndex":299,"id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、改めて、区として、誰の家の下を通るのか、地域で幅１４ｍの位置が分かるような明確な地図をＪＲ東海に求めていただきたい、区民が知れるようにしていただきたいと思いますが、いかがでしょうか。現在の進捗状況や対策について説明するとともに、沿線住民の意見を聞く場をぜひともＪＲ東海につくっていただくように求めていただきたいと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"区としましては、それらの安全性が一定程度確保できたときに、説明の場とか、情報の周知、様々だと思いますけれども、区民の方が安心していただけるような措置を求めていきたいと考えています。ＪＲ東海といたしましても、そういった考えでいきたいというふうに聞いてあります。","voiceIndex":301,"id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう事故が起こったわけですから、今までのように、安全だから上の人には説明しないのだと、そういうことはもう許されないと思うのです、そこのところをしっかりと求めていただきたいと思います。そこが分かるところを示していただきたいということで求めていただきたいということでお聞きしました。区として求めるべきではないかと思いますが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"地図のところに赤い丸とかで場所も明示しているような状況です。それを調べたところ、品川区の中では１９か所、または首都圏の区域、大深度法を適用しているのが３３.３kmあります。そこには２２８か所、ボーリングデータを収集していると。","voiceIndex":303,"id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これだけの事故が起こり、安全神話が崩れました。コロナ禍で需要予測も基本的な条件が激変しています。改めてリニア中央新幹線は中止を含めて抜本的な見直しをすべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":305,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"東日本大震災から１０年を過ぎました。継続的なご支援のほど、よろしくお願いしたいと思います。どういうふうに変わっていったのか。これから災害に強いという意味でのまちづくりをどう考えられているのかをお聞きしたいと思います。非常に東京都の影響が大きいかと思いますけれども、品川区として、これからの品川区の防災も含め、まちづくり全体の考え方がどうなっていくのか、まずお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"これは東京都はより広域的な視点で、こうした方針なり計画の改定を行っているところですので、区の独自のというお話もいただきましたが、これは当然、来年度以降、マスタープランを改定していくわけなのですが。","voiceIndex":307,"id":"exchange-137"},{"speaker":"西本委員","kind":"質問","question":"それで、３２５ページに市街地整備事業というのがあって、ここにいろいろと事業が書いてあります。品川区の土地のものについては、庁舎の建て替えについては検討委員会等々で話されている、これから始まるのが、にぎわい機能ということで、Ｂ地区のところ、それから防災センターのところでしょうか、その辺をどうするのかということで、この進め方についてお尋ねします。","respondent":"多並都市開発課長","answer":"要するに、狭い道路があったり、または公園がつくられたとか、そういうものを皆さんで一緒に、複数でどんどん広げて、それを協議会だったり、そういう検討をすることについて区が支援する、そういう部分がまず「まちづくり」の仕様です。","voiceIndex":309,"id":"exchange-138"},{"speaker":"西本委員","kind":"質問・要望","question":"この広町のＢ地区の件ですが、これからだというお話でした。継続審査という形になって、なぜ継続審査なのかと私には不明なのですけれども、やはりこの進め方も、にぎわい創出ですから、偏らないで、そして品川区全員の持ち物でありますから、そういう観点から、しっかりと住民の声を拾い上げていただきたいと思いますが、その件に関してお願いします。","respondent":"多並都市開発課長","answer":"委員のご指摘のとおり、庁内で連携しながら、もちろん区民の意見を聞きながら進めていく考えです。","voiceIndex":311,"id":"exchange-139"},{"speaker":"こんの委員","kind":"提案","question":"私からは、３１３ページ、大森駅歩道橋、３３９ページ、住宅確保要配慮者入居促進協力金等経費、３４５ページ、避難看板等現況調査委託、この３点をお伺いしたいと思います。順不同でお伺いいたします。この事業の創設の背景、そして事業の概要、また、事業の仕組み、さらに、相談した方が入居に至るまでのプロセス等について、お知らせいただきたいと思います。","respondent":"森住宅課長","answer":"そういった部分で、住宅課のほうで民間賃貸住宅を扱っておられる不動産団体との橋渡しができないかというふうに考えまして、今回の制度を検討したところです。","voiceIndex":314,"id":"exchange-140"},{"speaker":"こんの委員","kind":"質問","question":"入居に至るまでの、そこが大事だと思いますので、そこへの、先ほど協力金をということなのですが、オーケーしてくださって協力金のオーケーに至るまでの、どのような工夫と、どのように周知、ご協力を得るための取組み、こうしたこと、また、物件のストック、供給の目標などを設定しているのか、こうしたことの進め方についてお伺いしたいと思います。","respondent":"森住宅課長","answer":"目標につきましては、今、３０件ということで予算計上していますけれども、これから制度を具体的につくっていく中で、どのぐらいの件数が見込めるか、どのぐらいの住宅が確保できるかということは、しっかりと注視してまいりたいというふうに考えております。","voiceIndex":316,"id":"exchange-141"},{"speaker":"こんの委員","kind":"質問","question":"来年度は一応３０件の予算が計上されているということであります。そこで、例えば何件かストックされました。いくら情報をもらってお店に行っても、そこら辺のところがちゃんと交渉ができて契約まで結べるのか。こうしたことのサポートも必要かと思いますが、いわゆる入居に至るまでのサポートというのは、こうした細かいところも必要かと思いますけれども、どのようにお考えでしょうか。","respondent":"森住宅課長","answer":"その中で条件を聞き取るにあたって、それぞれの窓口の担当と、それぞれ勉強会をしながら、いろいろな細かいサポートがどういうふうにしていけるかということも実施しながら検討していきたいというふうに考えております。","voiceIndex":318,"id":"exchange-142"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうぞとなったとします。住宅課や相談を聞いてくださる高齢者福祉課や、子育て応援課が間に入ったとしても、直接不動産屋に行って話をするのは個人、ご本人なので、それがうまくそこでマッチングというか、スムーズに契約まで至らないというケースを想定すると、間に入ることによってどうメリットがあるのかというイメージがなかなかつきにくいのですが、その点をもう１回ご答弁いただきたいと思います。","respondent":"森住宅課長","answer":"具体的な相談者の方の個人情報は除いて、その他情報として、例えばナンバーで管理するだとか、そういったもので、その人がこういった条件を望んでいるということを不動産屋にも分かるようにしていきたいというふうに思いますし、その中で、そうは言っても、委員ご指摘のように。","voiceIndex":320,"id":"exchange-143"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですが、この事業は大変に大事な事業でもありますので、どうかご協力いただけるように、不動産屋のほうに周知して、そしてストックをして、入居者の促進に努めていただきたい。お願いいたします。避難看板等現況調査ですけれども、この現況調査、これはどのような目的で、また、委託となっておりますけれども、どういうような業者に、どのような委託をして調査をするのでしょうか。お願いします。","respondent":"平原防災体制整備担当課長","answer":"令和３年度には、看板の設置方針と、設置候補場所というようなところを考えてありますので、そういった委託事業者を今想定しています。","voiceIndex":322,"id":"exchange-144"},{"speaker":"こんの委員","kind":"質問","question":"ここが避難所ですと避難所の入り口に掲げるものと、その周辺から、あと何ｍで、どちらの方向にあるのかという、その誘導の矢印なども設置をする、こうしたことも考えられますし、また、夜間だとか、暗闇対策として、発光機能とか、それからソーラー電源機能、こうしたことも備えた看板を設置することも考えられますが、そうしたことの進め方をどのように考えていますでしょうか。","respondent":"平原防災体制整備担当課長","answer":"設置場所については、学校のすぐ近くなのか、あるいは誘導の方向性が出ているものかにつきましても、併せて検討してまいりたいというふうに考えてあります。","voiceIndex":324,"id":"exchange-145"},{"speaker":"本多委員","kind":"質問","question":"３１３ページの補助１６３号線整備について質問します。五反田、大崎、大井町を結ぶ区の重要な都市軸道路、大崎駅周辺の１期区間と、大井町駅前および２６号線から２０５号線までの２期区間は整備が完了しています。３期区間、約１,０２０ｍについて、進捗状況をお聞かせください。","respondent":"溝口道路課長","answer":"そのほかのところにつきましては、事業化に向けて検討を進めているというのが今の状況です。","voiceIndex":327,"id":"exchange-146"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、ＪＲ大崎支線の交差部なのですけれども、工程が計画より遅れていると伺ったのですが、その辺を教えていただきたいと思いますけれども、それで、作業時間が僅かということも聞いたのですが、その辺のところを詳細を教えてください。","respondent":"溝口道路課長","answer":"作業する際には、大規模な切り回し道路ですとか作業ヤード、そういったものの確保も必要になってくるというふうに予想されますので、そういったところを含めて、様々な工法、手法、また費用と工事期間、そういったところも様々ありますので、今、検討を進めているところです。","voiceIndex":329,"id":"exchange-147"},{"speaker":"本多委員","kind":"質問","question":"週３日で、１日にできるのが３時間ということで、かなりこれは予定というか計画より遅れてしまって、また、時間がかかる分だけお金もかかってしまうのではないかと心配いたしますが、そこの工事をやる際の近隣対策ですとか、そもそもその交差部の工作物の構造ですとか、あとは、子どもの壁画とか、その辺のところを詳しく教えてください。","respondent":"溝口道路課長","answer":"ただ、その影響はなるべく少なくするような形での構造物の工法、そういったものも今現在検討していますので、そういったものがある程度検討が進んだ段階で、近隣の方にはしっかりとご説明をしながら事業を進めていきたいというふうに考えているところです。","voiceIndex":331,"id":"exchange-148"},{"speaker":"本多委員","kind":"質問・要望","question":"これ、完了するまで渋滞が心配なのですが、渋滞対策をお聞かせいただきたいのと、この整備が完了したときに、そもそも整備に渋滞解消という目的もあると思うのですが、その工事のときの渋滞対策と、完了したときの渋滞解消について説明してください。","respondent":"溝口道路課長","answer":"工事のところですが、一定やはり期間がかかるものですので、できれば道路も切り回しながら、なるべく交通渋滞を引き起こさないように、そういったところの配慮も含めて、今、検討を進めているところです。","voiceIndex":333,"id":"exchange-149"},{"speaker":"本多委員","kind":"質問","question":"これは整備が完了したときに渋滞が解消されると思うのですけれども、今までも道路が整備されてきて実感で分かるのですが、道路行政としては、この渋滞解消という指数をどうやって計るのかを教えてください。","respondent":"溝口道路課長","answer":"現状で様々な形で交通量等も変わってきておりますので、事業を着手する際にはそういったものも１つの指標として考えていかなければいけないというふうに考えているところです。","voiceIndex":335,"id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"もろもろ対策を講じていただいて進めていただきたいと思います。それがその予定どおりいけるのか。その辺だけ教えてください。","respondent":"多並都市開発課長","answer":"今の委員のご指摘いただきました１６３号線につきましては、再開発事業と併せて事業を実施しています。今、トンネルを掘っているのですけれども、令和４年度に車道と歩道が通れるように開通させるということで、今、確認しているところです。","voiceIndex":337,"id":"exchange-151"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３２５ページの都市開発費から、大井町駅周辺地区再開発事業について伺いたいと思います。策定にあたるその素案の段階では住民説明会が行われましたけれども、本当に多くの住民の皆さんから、住民不在の再開発はやめてほしいという、本当に多くの声が会場でも出されておりましたが、こうした方針が策定されました。この広町地区をこうした周辺の開発の起爆剤とする理由を教えてください。","respondent":"多並都市開発課長","answer":"大井町駅周辺につきましては、今、委員にご案内いただきましたように、昨年１１月にまちづくり方針を策定しています。この中で広町地区の整備計画を示させていただいて、現在、その方針に従いながらまちづくりを検討して進めているところです。","voiceIndex":340,"id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この広町地区を牽引役、私は起爆剤だと思っていますけれども、その役割として進めていくと。しかし、広町地区は、区とＪＲと日建設計の３者で検討を進めていて、住民参加もない、情報公開もない中で進んでいて、区が勝手に機運を上げているという状況です。Ｄ案です。現庁舎は跡地になるわけです。広町地区のまちづくりとして、庁舎跡地はアリーナという考えは変わりないのか、伺いたいたいと思います。","respondent":"多並都市開発課長","answer":"区としましては、この方針に従って、これから新しく庁舎を建てるところも含めて、行政機能の再編の中で併せて検討していくということで進めようと考えているところです。","voiceIndex":342,"id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども言いましたけれども、にぎわい施設は、この地区は、区民の皆さんには問われていないので、勝手に決められているわけですよね。にぎわうことは否定しませんけれども、この区役所跡地は区有地なのです。ですけれども、にぎわい施設をつくっていくと。なぜ勝手に決めてしまうのかなと思うのですけれども、そこの考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"この考え方としては、人が集まり、にぎわうということがここのコンセプトとなっていますので、この基につくる方針につきましても、それに従ったにぎわいという形で書かせていただいて、区としては。","voiceIndex":344,"id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした計画を品川区が自分でつくっているのですよね。そうしたにぎわい施設もつくりましょう、にぎわっていきましょうというふうな計画であるということをどれだけの区民が知っているでしょうか。もっと声を聞いていただきたいと思います。まちづくりは住民合意が大前提です。理解を得られていない再開発は、ぜひやめていただきたいと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"まちづくり方針を策定する際も住民説明会をし、また、いろいろとご意見いただきまして、反映して素案から本方針ということで決めさせていただいているところもありますので、住民の皆様のご意見を踏まえながらつくっているところです。","voiceIndex":346,"id":"exchange-155"},{"speaker":"吉田委員","kind":"質問・要望","question":"今の石田ちひろ委員のご質問に関連して質問します。生活者ネットワークも、この広町再開発については、情報の公開を求めております。審査会の結論もそうなのですけれども、非公開で結論が出ている。私たちは、決して発言録を求めているわけではありません。その議論の経緯が分かるような区の書類をぜひ区民のためにつくって公開することが区の役割だと考えますが、その点についてお聞かせください。","respondent":"多並都市開発課長","answer":"そういうところでありますので、情報公開があった時点では、やはりまだ企業の内部の状況だったのですけれども、それが固まってきた段階で、お出しできる状態になってきたということですので、現在のそういう公開をさせていただいて、様々なご意見をいただきながら。","voiceIndex":349,"id":"exchange-156"},{"speaker":"吉田委員","kind":"質問・要望","question":"ということは、今、情報公開を求めれば、詳細な内容が書かれたものが出てくるというふうに考えてよろしいのでしょうか。私たちは、どういう意見があって、どういう議論を経て結論がこうなった、それを知りたいと思うのですけれども、今はそういう書類がつくられていると思ってよろしいのでしょうか。","respondent":"多並都市開発課長","answer":"要するに、情報公開につきましては、検討している経過についての情報公開につきましては、やはり申請いただいて、その内容も含めて、その時点で判断するものと考えています。","voiceIndex":351,"id":"exchange-157"},{"speaker":"吉田委員","kind":"質問","question":"過去の情報公開の話をしているのではなくて、今はそういうちゃんと議論の経緯が分かるような記録が用意されているのでしょうか。いろいろな企業の、個人情報というのでしょうか、企業の情報が書かれているものをそのまま出せないというなら、それは分かります。そして区民に示されるべきではないか。特に議員に対しては、資料提供で示されるべきだと考えますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"ただ、まとまった内容につきましてはご説明させていただいて、そこで固めないで住民の意見を聞きながら進めていく。議会にもご報告しながら、ご意見をいただきながら進めていくということをしますので、そういう形で進めていくものです。","voiceIndex":353,"id":"exchange-158"},{"speaker":"吉田委員","kind":"質問・要望","question":"きちんとした情報提供がなかなかされていないと思います。ぜひ情報公開を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-159"},{"speaker":"高橋（し）委員","kind":"質問","question":"目黒川・立会川護岸点検ですが、令和２年、３年で設置した防水板でありますけれども、その関係で点検されるのでしょうか。都市再生整備計画については、何度か質問させていただきました。人道橋についてお尋ねします。その点についてお伺いします。それからもう１つは、近くの公園、すぐそばの新浜川公園や、それから道を挟んだしながわ区民公園との連続性を含めた周辺整備も視野に入っているのでしょうか。","respondent":"松本河川下水道課長、鈴木都市計画課長","answer":"立会川の来年度実施する点検ですが、今年度実施した溢水防止板工事の際に、立会川の護岸に隣接する住民の方から、護岸の劣化の心配があるというようなお話があったことから、東京都と協議を行い。エリア内に、都市再生整備計画のほうについては、国に認めていただきながら、国の補助金活用には、人道橋以外にも２つほどの基幹事業の検討が必要になってきます。","voiceIndex":357,"id":"exchange-160"},{"speaker":"高橋（し）委員","kind":"確認","question":"立会川・勝島、八潮のまちづくりは、地域の方々の声を伺いながら、よろしくお願いします。これまでの成果をどう考えていらっしゃるでしょうかというのが１つです。ただ、住宅マスタープランは、「東京都住宅マスタープランとの整合を図る観点から概ね５年後に計画の進捗等を確認する」と現行のマスタープランに掲載されています。その改定を含めた進捗状況等の確認とはどういう内容でしょうか。お願いします。","respondent":"鈴木都市計画課長","answer":"ただ、そのときの東京都の住宅マスタープランの中身もしっかりと確認しながら、先ほど、進捗の確認というお話がございましたが、区の住宅施策のほうに反映するべきところはしっかりとするというところと、空き家ですとか居住支援、マンション。","voiceIndex":360,"id":"exchange-161"},{"speaker":"高橋（し）委員","kind":"質問","question":"時間の関係で、５地区それぞれで目標の達成を伺いたいのですが、ここでは大井地区の「区民の『心と生活の拠り所』としてさらに魅力と親しみが高まる生活拠点都市」という目標を掲げているのですが、その辺りの達成度はいかがでしょうか。そして、今回見直しが必要になった大きな理由をお尋ねします。３つ目に、現行のプランと乖離している状況、その辺りは今どういう状況になるのでしょうか。","respondent":"鈴木都市計画課長","answer":"あるいは、ウォーカブルといって、基本的には、歩きやすいから歩いてみたくなるという考え方も国のほうで示されてあります。そうしたいろいろな考え方を整理して検討を進めていきたいです。","voiceIndex":362,"id":"exchange-162"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今お話のありました社会情勢などの変化を十分に検討して、将来を見据えたまちづくり、先ほどの立会川・勝島、八潮も含め、まちづくりを進めていっていただくことを強く要望します。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-163"},{"speaker":"大倉委員","kind":"質問・要望","question":"伺っていた八潮北、不動前、両保管所の収容能力と保管率ですが、八潮北保管所の収容能力が４,５００台で、保管率２０％で、１,２００台近くだということと、収容能力が不動前で１,５００台で保管率５５％、８００台、合わせて２,０００台ぐらいだなというところで、収容能力が４,５００台の八潮北保管所でも、この２,０００台というのは受け入れられる台数だと思いますが、この認識で大丈夫でしょうか。","respondent":"川口交通安全担当課長、高梨公園課長","answer":"２つ目ですけれども、経緯的なものとしましては、当然、東急のこの立体交差事業の中で、当時はやはり放置自転車が非常に多かったということで、そこに対応するための放置自転車対策事業として、要は。どうしても状況等により、危険であったりということでできないところもありますが、基本的には、ご期待に沿えるような形でお話をさせていただいているところです。","voiceIndex":366,"id":"exchange-164"},{"speaker":"大倉委員","kind":"質問・要望","question":"よろしくお願いします。経済的に困窮している世代はもちろん、大学生等も新型コロナウイルス感染症対策の中で、アルバイト代等が減っているというのは、総務費のところでやって確認したら、総務課で大丈夫ということだったので、大学生等の話を聞いていただくというところでは、総務課とも連携しながらやっていただきたいと思っていますが、いかがでしょうか。","respondent":"高梨公園課長、平原防災体制整備担当課長","answer":"ボランティアの活性化につきましては、ボランティアの方々のお話を聞きながら前向きに検討していきたいと考えております。活用につきましては、庁内で連携して進めてまいりたいと思います。","voiceIndex":369,"id":"exchange-165"},{"speaker":"須貝委員","kind":"質問・要望","question":"だけど、何を言っているか分からない。そういう方がいました。これだけ多くの情報弱者の人がいらっしゃるので、命に関わる重要なアイテムですから、二次被害を出さないためにも、私は、区内に大増設して、できるだけ多くの区民が助かるように、そして有線も併せて設置して、何とかいろいろな意味で二次災害を防ぐようにやっていただきたいのですが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"こちら、令和３年度には、その回線数も増やさせていただきまして、フリーダイヤル化していこうというふうにも考えてありますので、そういったことを徹底的に周知させていただきまして。","voiceIndex":373,"id":"exchange-166"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、いざとなったときは、どうですか。ラジオのところへ行きますか。どうしたらいいのだろう。危険性が高い、リスクがあるというものですから、問題は、私、この間、話をしましたが、今、区内で幹線工事付近の、やっぱりそこ付近の地質変動調査を定期的に実施すべきではないかと思うのです。こういうことを使って、区民の安全を守るために定期的に調査をするべきだと思うのですが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"路上の変状につきましては、しっかりと測量を行いながらやっているところです。日々の管理につきましては、道路管理の一環として空洞調査等を行っているということは認識しております。","voiceIndex":375,"id":"exchange-167"},{"speaker":"須貝委員","kind":"質問・要望","question":"前もお話ししましたが、どこにも安全だという根拠がないのです。ですから、今後、定期的にやはり検査をして、続けていただきたいと思います。次に、３３７ページ、マンション管理支援事業についてお聞きいたします。分譲マンションは、１０年後に今の２倍から２.５倍になるようです。築４０年以上になる建物は、要は、中古マンションになると思うのですが、区内にどれだけあるのでしょうか。教えてください。","respondent":"森住宅課長","answer":"品川区内にある分譲マンションにつきましては、東京都のデータベースによりますと２,２６４棟あります。そのうち、これは東京都の管理制度で、昭和５８年以前の、正確に言うと、３７年以上経つものにつきましては、６１４棟というふうになってあります。","voiceIndex":377,"id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"やっぱり品川区は便利ですから、これがこれから１０年後に２倍以上にどんどん増えていくと、予想通りだと思います。何も修繕しないと、建物の老朽化は顕著に進み住めなくなるし、居住者もさらに減少すると思いますが、品川区として何か支援策はあるのでしょうか。教えてください。","respondent":"森住宅課長","answer":"届け出ていただく項目の中には、管理費や修繕積立金がありますか、見直しをされていますかということもございまして、その中で、もしそういうところに不備がある場合は、マンション管理士を派遣して、しっかりとサポートするということもしていますので。","voiceIndex":379,"id":"exchange-169"},{"speaker":"須貝委員","kind":"質問・要望","question":"だって、ずっと管理費を払って、共益費を払って、なぜ私たちだけが払わなければいけないのだと思ったら出ていってしまうではないですか。これだけ高齢化していて、そこら辺を考えていただきたいのですが、ということは、分譲マンションは、所有者である居住者が誰もいなくなり老朽化した場合は、建物だけが残ってしまうということになると思うのですが、その場合はどうするのですか。教えてください。","respondent":"森住宅課長","answer":"例えば、滋賀県のほうでは、分譲マンションの行政代執行ということも行われたというふうに聞いてあります。そこまでいかないように、区としても支援を続けていきたいというふうに考えております。","voiceIndex":381,"id":"exchange-170"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、今、品川区、どんどん建っている中で、では、品川区が最終的に、分譲ですから、住んでいる方はそこを逃げてしまえばいいのですから、そうすると、全部自治体で取り壊すということになるのではないですか。そういう心配を私は思うのですが、どうなのですか。そうしたら、最後、あとに残るのは、区が、各自治体が手を出さなければ、コンクリートブロックだけがずっと残り続けるのではないのですか。","respondent":"森住宅課長","answer":"委員おっしゃるとおり、区のほうで最終的には最後の手段として行政代執行というものがありますけれども、その費用は全て所有者のほうに請求するということになりますので、そういったところの手段はありながらも、そこに行かないように。","voiceIndex":383,"id":"exchange-171"},{"speaker":"須貝委員","kind":"質問","question":"いや、そのままマンションが残っていることなど、この品川区ではあり得るでしょう。勝手に壊せないではないですか。誰も処理できないではないですか。私は、きちんとこれを東京都と話し合って、どういうふうにこういうときはするのだとか、それから一人ひとりの権利者の、居住者、所有者の管理を徹底して追跡できるような仕組みをつくるべきだと思うのですが、いかがですか。","respondent":"森住宅課長","answer":"マンション管理士を派遣して、まずはお話のできる体制をつくるというところから進めていきたいと考えておりますので、そういった部分をして、マンション管理の促進に努めていきたいと考えております。","voiceIndex":385,"id":"exchange-172"},{"speaker":"中塚委員","kind":"質問","question":"３４３ページ、避難行動要支援者経費に関わって、福祉避難所運営マニュアルについて質問したいと思います。令和２年３月に、品川区災害時業務マニュアルが作成されました。具体的に伺いますが、二次避難所と福祉避難所の開設、運営について、品川区の職員が行うことになっていますが、避難者の食事、排せつ、移動の介助および介護は、二次避難所および福祉避難所にて、それぞれ誰が行うのかを伺います。","respondent":"中島防災課長","answer":"ただ、実際、その入居されている方の対応など優先すべきことがありますので、そのバランスをとりながら対応していくということになります。基本的には、二次避難所につきましては、区の職員が中心となって対応することになると考えております。","voiceIndex":388,"id":"exchange-173"},{"speaker":"中塚委員","kind":"質問","question":"食事などの介助が区の職員という計画は改善が必要だと思います。やはり二次および福祉避難所の運営体制の強化へ、地域の協力、ボランティアの受入れも含めて、体制強化を計画に加えるべきだと思いますが、いかがでしょうか。全ての区民避難所にて、教室の指定、レイアウト、必要な備蓄は整っているのかを伺います。","respondent":"中島防災課長","answer":"学校などの避難所における要支援者の方の必要な物資等ですが、基本的には、風水害対応でパーティション、ベッドなどを１,２００セット備蓄しておりますので、それらを優先活用するとともに、その他、不足する分につきましては、国。","voiceIndex":390,"id":"exchange-174"},{"speaker":"中塚委員","kind":"質問","question":"後半の要支援者のことですけれども、全ての区民避難所にて教室の指定は終わっているのか、レイアウトや必要な備蓄、１,２００セットのお話はありましたけれども、教室の指定とレイアウトは決まっているのかを伺います。やはりこれは直ちに決めていくべきだと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"したがいまして、大部分の避難所の中で要配慮者スペースは設けられております。ただ、細かいレイアウトなどは、今後、地域の方々と一緒に考えていく必要があるというふうに考えてあります。","voiceIndex":392,"id":"exchange-175"},{"speaker":"中塚委員","kind":"質問・要望","question":"全てではないということなのですが、区民避難所での教室の指定、レイアウトは、直ちに決定をして具体化していただきたいと思います。車椅子の方はどこで横になるのか。避難所環境について、学校で指定された教室、また二次避難所、福祉避難所も同じく最低限優先して、ベッド、間仕切り、そしてテントの備蓄と利用を求めますが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"そういったものを活用させていただきながら要配慮者に対応させていただきたいと思います。二次避難所、福祉避難所についての物資につきましても、福祉部との間で協議させていただいているところでございまして、令和３年度に所要の導入をさせていただければと考えています。","voiceIndex":394,"id":"exchange-176"},{"speaker":"中塚委員","kind":"質問・要望","question":"風水害用の１,２００セットを活用するということですけれども、１点だけ、ベッドは何人分あるのかを伺いたいと思います。避難者名簿について、先ほどのマニュアルには、様式６とありますけれども、全ての区民避難所の受付にて、対象になる方に記入を求め、移動の準備が必要だと思います。そして、この名簿を使うことを日常の訓練にも位置づけていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災体制整備担当課長、中島防災課長","answer":"ベッドにつきましては、簡易ベッドというものが、ただいま、現状では１００セットあります。併せまして、今ご審議いただいております令和３年度予算におきまして、２００台の追加購入を考えてあります。区といたしましても、そういう指針も踏まえまして、福祉避難所のあり方などを検討していきたいと考えております。","voiceIndex":396,"id":"exchange-177"},{"speaker":"中塚委員","kind":"質問・要望","question":"訓練を通じて課題を明らかにして充実をしていただきたいと思います。最後に要望だけしておきます。特に介護が必要な方、障害がある方には、全戸訪問をして対策を徹底していただきたい。こうした計画の策定に、高齢者、障害者の意見を反映させるため、当事者参加をぜひ位置づけていただいて計画の改善を進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":399,"id":"exchange-178"},{"speaker":"大沢委員","kind":"質問・要望","question":"３２５ページの武蔵小山駅周辺地区再開発事業、まちづくりと同時に伺いたいと考えています。その質問に入る前に、先ほど道路課長から、渋滞指数なる言葉、単語が出たのですけれども、目黒通りから平塚橋交差点のいわゆる補助２６号線、これについての渋滞指数が出ているのであれば、教えていただきたい。いわゆる渋滞状況というか道路状況についてです。","respondent":"溝口道路課長","answer":"申し訳ありません。","voiceIndex":401,"id":"exchange-179"},{"speaker":"大沢委員","kind":"質問","question":"すみません。東京都です。先ほど指数というような言葉を出されたので、よくご存じなのかなと思って質問させていただいたのです。これは駅の近くの開発だと思うのですけれども、課長、そこのところはどのようにお考えになられていて、まちづくりを進めていらっしゃるのか、小山に関して教えてください。","respondent":"多並都市開発課長","answer":"武蔵小山についてお答えをします。武蔵小山駅は、目蒲線が大正時代に開通しまして、昭和３０年代には、初代のアーケードができるなど、本当に昔から活気あふれる区を代表する商店街だということで区としては認識しています。","voiceIndex":403,"id":"exchange-180"},{"speaker":"大沢委員","kind":"質問","question":"正に二期工事に、二度目になりましょうか、６月にはもう新しくできるわけで、そこの中にはいろいろと防災上、空地をつくっていただいたこところがあります。開発の前にはたくさんの小さい路地がありました。私も小さいときはよく路地で遊びました。いわゆるロードの文化というよりストリートの文化が当時根づいていたわけでありまして、ここでロードの文化とストリートの文化、何が違うか教えてください。","respondent":"多並都市開発課長","answer":"ロードというと、いわゆる車が中心のような交通という点がありますけれども、もう１つのストリートのほうでいきますと、人が歩くというような、そういう違いなのかなと認識しています。","voiceIndex":405,"id":"exchange-181"},{"speaker":"大沢委員","kind":"質問","question":"今必要なのは、道路について、道路上の空間ですか、パブリックスペースとしての捉え方をもって考えることがこれから大事だと思います。いろいろと警察のほうから、公共のためでなければいけないというようなお話をかつて私、もらったことがありますけれども、そこのところも含みおきで、あそこの駅前ロータリーの活用ビジョンについて何かあったら教えてください。","respondent":"多並都市開発課長","answer":"そういう意味では、やはり非常に重要な施設でもありまして、また、駅を降りて最初の顔というところでもありますので、そこについては、ほかの自治体などの事例を見ても、やはりリニューアルするときには、結構力を入れてやるところもあるのは認識しています。","voiceIndex":407,"id":"exchange-182"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど申し上げたように、補助２６号線の渋滞指数が、仮にそんなに高くないのであれば、ばんたびとは言わない、日曜日の人のにぎわうほんの１時間でもいいのですけれども、銀座の歩行者道路のような、あるいは区から仕掛けていかないと、今、地域にはあまり体力がないので、区から、あるいは地元商店街と協力をしながら、あそこの駅前のロータリーに何か仕掛けていく意味合いはあると思うのですけれども。","respondent":"多並都市開発課長","answer":"なかなか道路上ですと、警察との協議をやったり、そういうことを言いますとあれですけれども、そういういろいろな民地の中も含めて開発はこれから進みますので、そういういろいろな場面で、より利用者の方が使えるような、また、にぎわうようなやり方がないかというのは。","voiceIndex":410,"id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"かつては目黒線の開通のところであそこを使わせていただいた。近年では、４月に、たけのこ祭りをやって、大きなにぎわいを見せている。ですから、そこのところを考えながら、今後あそこのロータリー、磨けば光るような石だと考えていますので、そこのところへ意識を置きながら、今後、武蔵小山のまちづくりを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":412,"id":"exchange-184"},{"speaker":"たけうち委員","kind":"提案","question":"３０９ページ、道路空洞調査修繕について伺います。東日本大震災から１０年ということで、この間も様々、熊本地震、また大阪府北部地震等、毎年のように何かしらの形で大きな災害が起き、私ども公明党も、その都度、様々な提案をさせていただきまして、津波対策ですとか、また防災ラジオ、非構造部材の耐震化、また最近では、避難所となる体育館の空調整備など、いろいろと取り組んでいただいております。","respondent":"溝口道路課長","answer":"今回やっていく上での課題ですけれども、やはりどうしても調査していく中で、すぐに悪いところ、また経過観察して継続して見ていかなければいけないところがありますので、引き続きこういったものの調査はしっかりと行っていく必要があるという、課題といいますか。","voiceIndex":414,"id":"exchange-185"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そこで、またこの新たな活用策として、先ほど我が会派の塚本委員も、これから電線の地中化をやるに当たって、事前に掘らなくても分かるようないろいろなものがあるという、そういう技術もありますけれども、例えばそういう地中化を進めていく上で、事前と事後にその周りのところを、例えば空洞調査をして、その結果として。","respondent":"溝口道路課長","answer":"そういった中、多少、本当に危険なところは出ておりませんが、やはり経過観察を必要とする、そういった箇所は出てきておりますので、そういったものを踏まえて、しっかりと今後も。","voiceIndex":416,"id":"exchange-186"},{"speaker":"たけうち委員","kind":"質問","question":"それでまた、先ほどもありましたけれども、実施主体は、責任主体は品川区ではありませんけれども、リニア中央新幹線、これがどこまで技術的にできるのかなと思うのですが、ただ、そうした考え方、これはＪＲ東海のほうにも、ぜひ、もう既に出しているということですが、そうしたものも活用できないのかなということは言っていただけないかなと思うのですけれども、いかがでしょうか。","respondent":"溝口道路課長","answer":"品川区におきましては、平成２５年から空洞調査を実施してきたという実績がありますので、そういったこともＪＲ東海のほうには紹介しながら、また、調査しているデータもありますので。","voiceIndex":418,"id":"exchange-187"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３１９ページ、まちづくりマスタープランの改定なのか、公園整備、それから水辺の利活用、全体的な感じでお伺いをしたいことがあります。それから１点は、先ほど３４５ページの避難所の話で、御殿山小学校の件で、御殿山小学校は安全だというお話をされていた。これはだから、ぜひそこは理解ができるような話をちゃんと町会の方と詰めていただきたいと思うのだけれども、そこだけ１点伺います。","respondent":"中島防災課長","answer":"避難場所につきましては、今回、地域の方々から様々意見をいただいているところですので、真摯に受け止めまして、よりよい避難方法について考えていきたいと思います。","voiceIndex":422,"id":"exchange-188"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで１つは、水辺、海を返してほしいなと思っています。これは品川区からも強く言ってほしいのです。ぜひここら辺の、これだけ今、渋滞している東京港、ここら辺のところを言っていただきたいというのが１つ。どうせならあそこは品川区に、指定管理でもいいし、もらえるならもらってもいいのだけれども、そこは品川区で活用できるようにしてほしいと思うのですが、ぜひそこら辺の話を聞かせてください。","respondent":"鈴木都市計画課長、佐藤企画調整課長、高梨公園課長","answer":"私から、まず、コンテナのお尋ね、ご要望といいますか、力強いご要望についてお答えしますが、やはり大井コンテナふ頭。私からは、２点目のご質問の清掃関係を含めた公共施設の再編だと捉えておりますが、品川区で策定しております公共施設等総合計画でも。区立公園を管理している立場から申しますと、例えば運動施設等が今かなり予約が多く入ってありますので。","voiceIndex":424,"id":"exchange-189"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。それはもう駄目だったのだけれども、そういうチャレンジをするということは、ぜひ私はやってほしいと思いますので、それだけはお願いをしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":428,"id":"exchange-190"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1136#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":133804,"voices":429}},{"id":"r03-20210312-3","meetingId":"r03-c-budget","date":"2021年3月12日","dateIso":"2021-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を194件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年度品川区一般会計予算","agenda":"令和３年度品川区一般会計予算","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、３７１ページ、給食運営費、そして３５３ページ、人権尊重教育推進経費についてお聞きします。初めに、給食運営費に関連しまして、和牛の給食が出されたことについてお伺いいたします。今日に至るまで、和牛の給食が提供された学校の数、また献立の中にはどのようなものが多かったのかを教えていただきたいと思います。","respondent":"篠田学務課長","answer":"こちらは品川区内の小・中・義務教育学校、全ての学校で実施されてあります。メニューなどは各学校ごとにかなりバラエティに富んでおりまして、牛丼ですとか、学校によってはステーキみたいな形で出されたところもあって、それぞれ子どもたちが大変喜んだと聞いているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"この取組みを通じまして、子どもたちの反応だとか教員の反応はどうであったか、教えていただけますでしょうか。","respondent":"篠田学務課長","answer":"牛肉は高いですから、なかなかメニューに入れられないということですので、子どもたちには本当に好評だったです。教員からもそういった形でなかなかメニューに出ない分、子どもたちの笑顔を見られてよかったというような声も聞いているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"教育の点から、この和牛を使った給食から、児童・生徒が感じ取りました気づきというのを形にしていく取組みも必要と考えます。例えばおいしかったその給食を思い出して、その絵を描いて、その横に生産者に向けたメッセージを記してもらうことで、保護者にも伝わりますし、またこれが生産者に届けば、生産者もきっと喜ぶと思います。そういうものも一つの食育ではないかと考えますが、いかがお考えでしょうか。","respondent":"矢部教育総合支援センター長","answer":"委員のご提案もとてもよい案だと考えております。日本の、また世界各地の材料を地図上に表したり、またはそこの料理を掲示したりして、様々な食育活動の中の一つ大きな好事例として、こちらで理解していきたいと思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"この事業自体は３月の公募を最後に一旦事業が終わるそうですが、今後も同じような事業が補正予算などで計上されました場合は、ぜひまた再び手を挙げていただきまして、ぜひ食育というものを取り入れて、子どもたちに教えてもらいたいと思いますが、お考えをお願いします。","respondent":"篠田学務課長","answer":"先ほども少し申し上げたのですけれども、給食で牛肉というのはコストの点からなかなか難しい状況がありますので、そういった形で何らかの補助的な事業がまた実施されるということであれば、私どもも前向きに考えてまいりたいと捉えているところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"小芝委員","kind":"確認","question":"ぜひ前向きに取組んでいただきますことをお願いいたしまして、次の質問に移ります。昨年の本会議で、横田めぐみさん拉致事件を題材にしたアニメ「めぐみ」の小・中学校での上映状況を確認しましたところ、上映済みが２１校、これから予定しているのが１４校と聞きましたが、今年度の実施状況はいかがでしたでしょうか。具体的にどの学年でこのアニメを視聴したのかを教えていただけますでしょうか。","respondent":"矢部教育総合支援センター長","answer":"拉致問題を取上げた授業についてです。主に市民科で指導をしております。調べたときには既に半数の学校が取組んでおりまして、学年は主に小学生では６年生、中学生では９年生の実施が多くなってあります。全校朝会で取上げた学校もあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"小芝委員","kind":"質問・要望","question":"このアニメ視聴後に、例えば児童・生徒にこの感想文といったものを課題として出させている学校があるかどうか。児童・生徒がこのアニメを見た後のそういった気づきを、現場の先生方はどのように吸収しているのか教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"子どもたちの反応ですが、聞き取りをしましたところ、恐らく低学年だと思いますけれども、めぐみさんが連れていかれるときに「お母さん、お母さん」と叫んでいたのはかわいそうだと思った。めぐみさんに帰ってきてほしいなどの感想を聞いております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"小芝委員","kind":"質問・要望","question":"拉致問題が全国的にニュースで広まってきたのは、１９９７年だったと思います。だとすれば、子どもたちにこの拉致事件の経緯、奪われた人権の話、またこれから自分たちが取組むべきことなどを正確に教えていくべきであると考え、教える先生には一定の知識が求められることになると思いますが、拉致問題について、先生自身はどのような事前学習をされているのでしょうか、教えてください。","respondent":"矢部教育総合支援センター長","answer":"他の授業と同じように、教員は全て事前に教材研究をいたしますので、そこでまず自分で研修をいたします。東京都は毎年全教員に人権教育プログラムを配布しています。そこに拉致問題が掲載されてありますので、いつでも研修の資料として活用できることとなっております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"小芝委員","kind":"質問・要望","question":"生徒が拉致問題について学んだ上で、自分なりの考えや意見を１,２００文字以内にまとめてもらう作文ですが、品川区のほうでこの作文コンクールの話というのは、人権教育の中で生徒に周知されているのかどうか、取組状況を教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"パンフレット、チラシ等が配布されることになっておりますので、学校には配布されていると思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"小芝委員","kind":"質問","question":"先ほど答弁で、小学６年生と中学３年生、９年生にこのアニメの視聴等、教育をしているという話を伺いまして、まさに中学生がこの作文コンクールの対象となりますので、学校教育の中でこのアニメの視聴とともに、この作文コンクールに生徒が応募していただければ、人権教育の成果にもつながると考えますが、お考えはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"委員も十分ご存じのように、人権教育には様々ある中での拉致問題です。当然全ての人権課題、男女ですとか高齢者とか障害者とか外国人とか様々ある中で、総合的に人権教育は推進してまいりたいと思います。","voiceIndex":20,"id":"exchange-009"},{"speaker":"小芝委員","kind":"提案","question":"一方で、これは私からの提案ですが、最近全国公開が始まりました、国内で初めて拉致事件を扱った実写版の映画、「めぐみへの誓い」という映画ですけれども、クラウドファンディングで製作費を賄った映画があります。都内でも２カ所でしか公開されていませんが、私も先月視聴いたしました。最後に、今後の教育に向けて積極的なお考えをお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ただいまの情報も含めて、様々な人権課題について誠心誠意、学校でも区でも一番の目標ですので、推進してまいりたいと考えております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"３５７ページ、ＩＣＴ活用推進経費、３６３ページ、電子図書館、３７３ページ、保健用備品購入、順不同で伺ってまいります。最初に、ＩＣＴ活用推進経費ですが、デジタル教科書の実証事業についてお伺いいたします。申請をすれば、これは必ず参加できるものかどうかというところを確認したいと思います。","respondent":"矢部教育総合支援センター長","answer":"デジタル教科書の申請のお尋ねです。委員ご指摘のとおり、教育委員会としても申請をしていますが、まだ結果ははっきりとしてございませんけれども、できるだけ全校に１教科だけでも、１学年だけでも入れるように、働きかけております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"まだ結果が出ていないということです。国から発信されまして、東京都の教育委員会を通じて、これが品川区の教育委員会に来ているものと思います。できればその際、東京都に何か条件というか要望をしていただいて、全部は駄目だったとしても、例えば一部、では５年生だけは全員お願いしたいとか、そのように格差がないように、ぜひ取組みをお願いしたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"どの学校にもというご質問かと思います。東京都のほうでは約半数という条件でございましたが、本区としては何とかということで、できるだけ多くを要望しております。漏れる学校がないように、本区としても力を入れて、全校に１教科、１学年でも入れるように努めてまいります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"順番を変えて、保健用備品購入についてお伺いをいたします。都議会の予算特別委員会で、公明党の女性議員であるまつば議員が、例えば学校のトイレに生理用品を置き、無料で使えるようにするなども考えられるが、知事の考えと思いを伺うということで質問をいたしました。という答弁がありました。そのような状況から、この生理の影響がないか、どう捉えているのかということをお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"ただ、２点目にも関わりますけれども、心のケアということでは、基本的には養護教諭、そして女性の教員に相談できる心のつながりはできていると認識しております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"新妻委員","kind":"意見","question":"今日はちょっと生理の貧困というところで取り上げてまいりますが、そこで学校の保健室に生理用品のストックがあると思います。これらの購入等は学校ごとにされているのか、または区の教育委員会でまとめて購入して学校に配布されているのか、不足したらまた教育委員会からお渡しするのか、そこら辺のストックの様子、状況をお知らせください。","respondent":"篠田学務課長","answer":"学校に常備しております生理用品につきましては、教育委員会のほうから学校に配当している予算で、必要に応じて学校のほうで用意してもらっており、不足すればその分を補充しているというような状況です。","voiceIndex":31,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"中にはなかなか言いにくいとか、たくさんもらいにくいとかいう生徒もいると思います。今回のこのアンケート調査で可視化されたということも踏まえて、学校のトイレにナプキンを置いておくということをぜひご検討いただきたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"区教育委員会として何かできることを、衛生上・管理上の課題を考えながら検討してまいりたいと思います。","voiceIndex":35,"id":"exchange-015"},{"speaker":"新妻委員","kind":"提案","question":"今日は教育費で、次から申し上げることは要望としますけれども、今回このようなアンケート調査が出て可視化がされてまいりました。これは要望とします。電子図書は、今回の予算特別委員会副委員長のつる副委員長が２０１２年の第２回定例会の一般質問で、電子図書館の導入を提案させていただいておりました。そして、どのような方をターゲットとして、利用されると想定されているのか伺います。","respondent":"横山品川図書館長","answer":"ターゲットといたしましては、やはり電子書籍に抵抗のない層からまずは使っていただくですが、実は使い方におきまして、書籍を拡大するであるとか、音声の読み上げだとか、機械に疎いような層の方に便利な機能がとてもありますので、これについてはまず使っていただいて。","voiceIndex":37,"id":"exchange-016"},{"speaker":"新妻委員","kind":"提案","question":"いろいろな方々が使えるチャンスだと考えています。機器が苦手な方もいらっしゃると思うのですが、図書館に来る方はいろいろな世代の方がいらっしゃいます。この電子図書館の導入を機に、ＩＣＴ機器に触れていくチャンスであると捉えていただいて、ぜひ図書館で、この電子図書のアピールも兼ねながら、この電子機器の使い方広場、使い方の教室などを行っていただきたいと提案いたしますが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"実は今、図書館でご利用いただく予約機につきましてもマニュアルを作って、折々で、研修ではないのですけれども、お知らせをする機会を設けているところですので、同じように丁寧な説明とともに、マニュアルやホームページでの解説を進めていきたいと思います。","voiceIndex":39,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。高齢者の支援策の中でも、スマホ、タブレットの教室を次年度開催するという予定になっております。図書館でも、このインターネット等のＩＣＴ機器等を利用できる人とできない人の間にもたらされるデジタル・ディバイドをなくしていく取組みを、ぜひ推進していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"質問に先立ちまして、品川区全体の教育関係の職員、たしか１,５００人ぐらいとお聞きしましたけれども、新型コロナウイルス感染者数がほぼ０名ということをお聞きいたしました。は生徒指導対策等経費から、子どもたちのマスク着用のあり方について質問いたします。私の娘もそうですけれども、子どもたちに苦しくないのかとお聞きしましたら、苦しいけれども学校のルールですからというお話でした。","respondent":"矢部教育総合支援センター長","answer":"先ほどお話がありました体育についてですとか、また前との距離が十分取れている場合は、マスクを外しても構わないということになっておりますので、そういう配慮で考えていたのですが、お子さんの中には。","voiceIndex":43,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問・要望","question":"熱中症の部分でした。正しいマスクのつけ方、外した子どもがいたときにもいじめられないような形で、また子どもたちの健康につながるよう要望して、次の質問に移ります。次に、学校ＩＣＴ活用経費についてお聞きいたします。一般質問でもお聞きしましたが、学校との相互連絡の構築、欠席届のオンライン化、学校配布物の紙とデータベースとの検討、もし進んでいることがありましたら教えてください。","respondent":"工藤指導課長","answer":"学校だよりなどにつきましても、もう既に一斉メールに添付して保護者に送付するということを行っている学校もありますので、引き続き検討し、運用を図っていきたいと考えています。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松澤委員","kind":"意見","question":"大変ですけれども、しっかりとしたシステムの構築をお願いいたします。これは私事なのですけれども、戸越小学校ではＺｏｏｍでの保護者会というのをやっていました。そういった際の窓口はたしか教育委員会になっていると思いますが、電話対応が大変なのではないかと思いますけれども、そこら辺で対応を取られていることは何かありますか。","respondent":"篠田学務課長","answer":"学校ですとか教員からの問い合わせにつきましては、ヘルプデスクを設置いたしまして、そちらのほうで専門的に機器の操作から、中に入っているアプリの運用等も含めて対応していますけれども、利用されている保護者等からの問合せについては、今、委員からご指摘のあったとおり。","voiceIndex":47,"id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"まだ１日二、三件程度ということでしたら、切迫に広げるとかそういうことはないかと考えています。そのタブレットですけれども、児童・生徒全員と、あと先生方と、またほかで先生以外にどなたがタブレットを持っているのかというのが分かれば教えてください。","respondent":"篠田学務課長","answer":"今、学校の中には様々な職種の方がいらしているのですけれども、そういった指導に関わる方にはある程度行き渡るような形でとは考えているのですが、台数にも限りがありますので、各学校には一定程度予備を渡しまして。","voiceIndex":49,"id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"学習用ということで、児童・生徒、先生以外は予備のものを使うという話ですけれども、私はスクールカウンセラーはこれを持っていたほうがいいのかなと感じています。いじめや学校の相談、トラブル、不登校などについて、児童・生徒はスクールカウンセラーに相談すると思います。それを踏まえて、オンラインカウンセリングに対するご見解をお願いします。","respondent":"矢部教育総合支援センター長","answer":"オンラインカウンセリングについてです。今後、チャイルドラインとシグナルカードをＱＲコードで読み込んで対応していきたいと考えています。","voiceIndex":51,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"３７１ページ、普通教室増設工事、３５３ページ、人権尊重教育推進経費などに関わって、コロナ禍の学校における子どもの支援、少人数学級、子どもの権利条約について伺います。約３割の方がそう答えていると。残念ながら学校はそういう場になっていないと。伺いますけれども、コロナ禍におけるこのような子どもたちの声を区教委はどう受けとめ、どう学校運営に活かしていくのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"お子さんは毎日会っている担任を中心に、顔色を見たり、今日の行動を見たり、言動を聞いたりして観察して対応しているということと、これまでも繰り返していますスクールカウンセラーで対応したりとか、アンケートを学期で一回取っているというようなことで対応して。","voiceIndex":54,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"担任は本当に大変だと思うのです。少人数学級について伺っていきたいのですけれども、まず共産党の代表質問に対する教育長の答弁についてなのですが、教育長も所属される全国都市教育長協議会は、昨年１０月末の中央教育審議会特別部会の場で、少人数編成の検討について、１学級３０人以下など少人数学級を明記する答申を出すように要望しています。しかし、品川区教委ではどうでしょうか。伺います。","respondent":"有馬庶務課長","answer":"委員お尋ねの全国都市教育長協議会の件ですが、今年度についてまとめがあったのは事実ですが、その中をよく読みますと、「今回はコロナ禍において一定意見をまとめることはできなかったが」という言葉が枕言葉でありまして、その中の一つとして。","voiceIndex":56,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"国が大事な中央教育審議会の特別部会の場に呼んだ全国都市教育長協議会の会長は、教育長として３０人学級を明記すべきだと要望したということですが、それはまとまらなかったと、それはあくまで参加した教育長個人の発言だということで、品川区の教育長はそういう立場ではないということを表明したということで、私は受けとめました。これは正直言ってちょっと冷たいですよ。改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"今回国のほうからも１月に閣議決定されまして、段階的に３５人学級を実現していくですので、私どももそちらの考え方にのっとり対応していきたいと考えているところです。","voiceIndex":58,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、区の教育委員会として、教育環境の整備が仕事、所管だと思うのですけれども、これは教育委員会としてどうかと聞いたのです。この教室の状況を見て何も感じないのでしょうか。伺いたいと思います。でも、せめて３５人学級は急いで全学年、中学校でも実現すべきだし、その実現に区も発言したり、あるいは努力、自ら汗を流すべきだと思うのですけれども、改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"３５人学級につきましては、再三申し上げましたとおり、国のほうがそれに向けて動き出しをしているですので、そちらのほうをきちんと踏まえながら対応してまいりたいと考えているところです。","voiceIndex":60,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"この間、少人数学級についての認識や区独自の対応ということで、今も聞きましたけれども、伺うと、区教委は先ほどのように法や都の基準に従って対応するのが基本ですと繰り返していますが、常にその顔と耳が国や都のほうを向いているのです。こういう少人数学級の導入、あるいはクラスの規模などについて、子ども自身に意見を求めたり声を聞いたことがあったのでしょうか、伺いたいと思います。","respondent":"篠田学務課長","answer":"学級編制につきましては、あくまで教育委員会の権限で各学校で実施していくということになりますから、子どもの意見を聞いて対応するべきものではないと認識しているものです。","voiceIndex":62,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"率直に言って驚きの答弁ですね。子どもの権利条約を全く理解していないということだと私は思いました。もう一度伺いますけれども、児童・生徒自身にこそ、クラスの人数はどうですか、教室が窮屈ではないですか、席が近いと感染が不安ではないですかなどと耳を傾けるべきではないですか。そもそも今の教育委員会の仕事、権限ですというのは、ちょっとその答弁は大丈夫なのですか。伺います。","respondent":"篠田学務課長","answer":"確かに子どもたちの意見は様々あると思いますし、一定程度反映できるものはあろうかとは思いますけれども、基本的な部分でクラスの人数を何人にするかといったものに関しては、あくまでも制度の枠組みの中で対応すべきものと考えているところです。","voiceIndex":64,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そう言いながらも私も自分自身に問うているのです。本当に子どもの声を聞いたのだろうかと。続いて子どもの権利条約についても伺っていくのですが、私は２０１９年の代表質問で、この子どもの権利条約の観点から品川区の競争教育を見直すべきと質問いたしました。品川の学校教育でそういう場面はあるのでしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"子どもの権利条約につきましては、社会科の教科書でもありますし、市民科のほうでも指導している場面があります。","voiceIndex":66,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、子どもの権利条約の条文や内容そのものを子どもたちが教わる場面が品川の学校教育であるのかということです。もう少し具体的にお伺いしたいと思います。お答えください。例えば子どもの捉え方であったり、子どもの最善の利益、あるいは意見表明権など、この子どもの権利条約そのものをしっかりと扱うことを改めて私も求めたいと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"様々な場面で憲法や人権を学ぶ機会に、その資料を提示することはままあると考えております。様々ないじめや人権問題について話すときに、その話題になるということは十分ありますが、そのものだけをずっと時間をかけてやるという時間は取っていないと認識しております。","voiceIndex":68,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"時間がないというか、私はこれは大事な内容というか、実は子どもたちだけではないのです。私は、子どもの権利条約から品川の教育を点検し、見直す必要があると思うし、やっていただきたいと改めて求めたいと思います。伺います。この勧告について、品川区教委は思い当たるところがないのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"市民科でありますとか英語教育でありますとか様々な全ての教科を通じて、特に市民科学習におきましては、人間性の形成の部分で大きく寄与していますので、品川区の一貫教育は引き続き進めていきたいと考えているところです。","voiceIndex":70,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"全然答えていないのですけれども、競争的な教育制度が子どもに否定的な影響を与えているというこの指摘、これは品川区には関係ないということですか。思い当たる節はないのでしょうか。日本の今までの教育を引っ張ってきたと自負しておられましたけれども、どうなのでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"委員ご指摘の競争的なというお話ですが、品川区で進めております一貫教育につきましては、児童・生徒一人ひとりの個に応じた教育を大事にしながら行っているものです。それぞれの児童・生徒が未来を生きる力をしっかりと育む、そのための教育をするものです。","voiceIndex":72,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"直接お答えにならないのですけれども、答えられないということなのでしょうか。やはり子どもの権利条約の観点から品川区の教育を洗い直していくと。それと子どもの参加です。これを制度、教育方針などを作っていく上で必ず位置づけて改善していくということを私は求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-034"},{"speaker":"筒井委員","kind":"提案","question":"私からは、３６３ページ、事業運営費の電子図書館、３６５ページ、書籍除菌機、３５２ページ、教育指導費に関連して、ＳＴＥＡＭライブラリーについてお伺いいたします。先ほど新妻委員からも、また過去に様々なほかの議員の方からも電子図書館導入の要望があったかと思います。","respondent":"横山品川図書館長","answer":"ナクソス・ミュージック・ライブラリーにつきましては、これは期間限定の使用権という形になりますので、同じく図書館で利用の手続きをしていただいて、２週間の間はデータベースをご利用いただけますので、その間においては電子書籍と同じように。","voiceIndex":76,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"私も早速使ってみたいと考えておりますけれども、当然やはり幅広い層に向けて提供されるものですから、今後この電子図書館のシステムを導入していきますという事実と、やはりある程度具体的な使い方、マニュアルというのも広く周知していかなくてはいけないと思っているのですけれども、今回のこの電子図書館導入についての周知はどのようにされていくのでしょうか。","respondent":"横山品川図書館長","answer":"やはり区の政策の周知の第一で、広報紙を利用します。それと同時にフェイスブック、ツイッター等で周知するとともに、チラシやポスターを利用しますとともに、館内でもＰＲをさせていただいて進めさせていただきたいと考えています。","voiceIndex":78,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。続いて、書籍除菌機についてお伺いいたしますけれども、ついに全館に配置されるということで、従来からの衛生面の配慮、そして何と言っても今回の新型コロナウイルス感染予防対策として、これも非常によい事業かなと考えております。全館に配置されることになりましたけれども、具体的にどのようなメーカーなのか、これが日本の企業のものなのかどうかも含めて教えてください。","respondent":"横山品川図書館長","answer":"書籍除菌機についてのお問い合わせです。今回５台購入することによって全館配置になりますが、機種につきましては、従来使っております４冊用のＬＩＶＡという機種と、２冊、３冊用のＣＯＣＯＣＨＩという機器を想定して配置を考えているところです。","voiceIndex":80,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"そのＣＯＣＯＣＨＩは幾らなのかとか、ＬＩＶＡは幾らなのかということはちょっと分からないということでしょうか。分かればお答えいただければと思います。何か日本製と比べて特筆すべき点というのはあるのでしょうか。","respondent":"横山品川図書館長","answer":"今回にあたっても見積もりは前例で置いていることから取らせていただいたところですので、選定にあたって特にこだわりがあるわけではないので、ほかの機種と比べられるようであれば導入したいと思いますが。","voiceIndex":82,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。続いて、ＳＴＥＡＭライブラリーについてお伺いいたします。教育現場でもデジタル化の波が押し寄せているということですけれども、これは作成が、先ほど言いましたとおり経済産業省で、文部科学省ではないですね。そうしたことから、このＳＴＥＡＭライブラリーについて、品川区の教育委員会へ連絡とか通知というのは事前にあったのでしょうか。","respondent":"工藤指導課長","answer":"ただ、これにつきましてはいわゆる「未来の教室」という事業で進めている一環であることは、私どもも承知していますので、そういった活用につきましては教材の一つにもなりますので、学校のほうで活用が図れる部分については活用できるものと認識しております。","voiceIndex":84,"id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"特に教育委員会に特定の通知はなかったということで、知っているという認識だと思うのですが、今活用できるものは活用していくということですけれども、では具体的にどのようにこの授業で使っていこうとか、私も見させていただいたのですが、結構様々、非常に具体的で分かりやすい教材なのですけれども、本当にＧＩＧＡスクール、１人１台タブレットの構想と非常に相性がよいものだと思うのですが。","respondent":"工藤指導課長","answer":"教材につきましては、教員が授業で議論の題材として使えるものであったり、児童・生徒が興味のある教材を選んだりできるものでございまして、教材の一つとして利用を図ることができると現在考えているところですので、活用につきましては学校。","voiceIndex":86,"id":"exchange-040"},{"speaker":"吉田委員","kind":"確認","question":"３６９ページ、第一日野小学校の第二校庭整備工事で人工芝のことについて伺います。３７３ページの保健運営費にあたると思います給食着の問題、性教育の問題、新型コロナウイルス感染症対策、順不同で行けるところまで伺います。最初に、第一日野小学校の第二校庭整備工事です。海洋に出てしまわないよう、排水溝の掃除などを気をつけて行うということも確認しております。見解を伺います。","respondent":"有馬庶務課長","answer":"今、品質改良も進んでおりますので、今後どうしていくかということはまた今後の課題と捉えている状況です。一方、ある学校では表層改修とか、土の改修をそのまま継続するという学校もありますので、併せながら検討していきたいと考えている次第です。","voiceIndex":89,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"おっしゃるとおり、近隣への配慮とかいろいろなメリットがあることは私たちも承知しております。同じ区の、しかも教育機関がこの問題についてやはり推進するというのは、ちょっとどうなのかなと思います。少しでも負荷を減らす方向で考えるとか、やはり別の表層、そのまま土のグラウンドにするという条件が許せばそちらの方向を検討すべきだと思いますが、改めて伺います。","respondent":"有馬庶務課長","answer":"ハイブリッドはどうなのかということですが、天然芝の養生期間で子どもが使えないという期間があるのかないのか、そういったことも出てくると思いますので、今後のそういった製品の改良の動向も注視してまいりたいと思います。","voiceIndex":91,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"次に行きます。保健運営費にあたると思いますが、新型コロナウイルス感染症対策への質問です。新型コロナウイルス感染症のための区立学校版感染症予防ガイドラインを確認いたしました。かなり詳細なガイドラインなのですが、その中から幾つか伺います。この（４）全体がそもそも教員の役割なのでしょうか。ちょっと先生の役割としたら負担が大き過ぎるのではないかと思いますが、見解を伺います。","respondent":"有馬庶務課長","answer":"こちらのガイドラインは全般的な、例えば消毒等に関して衛生管理をしていこうということでございまして、必ずしもこれを教員がやるというふうにしているものではありません。","voiceIndex":93,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"では誰がやるというのは、それぞれ学校の中でルールがきちんと決められていると判断してよろしいでしょうか。","respondent":"有馬庶務課長","answer":"そうです。例えば、最近中学生では自分の机は自分のもので拭こうというところもあれば、やはり低学年は担任の先生が児童の机を拭いているというような状況もありますので、一律にどこがどうと全て決まっているわけではございません。","voiceIndex":95,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれ学校で判断されて、きちんと混乱がないようにしていただきたいと思います。ただ、衛生費のときにも質問したのですけれども、水道の蛇口、レバーのことがちょっと気になります。石けんを泡立てて手を洗う際に、最後に蛇口、レバーもちゃんと石けんで洗って、手を水で流すときにそのレバーの石けんも一緒に流すよう指導するとベストなのではないかと思うのですけれども、その点について見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"１月１８日付で事務連絡を発出しまして、手洗い場における新型コロナウイルス感染症対策の徹底ということで保健所とも連携を取りながら、子どもには、蛇口を使い終わったら、蛇口の表面を水で洗い流してから次の人に譲る指導を徹底するということで、通知をしています。","voiceIndex":97,"id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"そうですね。ガイドラインの改訂にあたっては、内容そのものや表現も含めて、例えば区内で言えば保健センターのアドバイスなど、連携とか相談はやっているのでしょうか。今は保健センターが超多忙なので難しければ、東京都の教育委員会に配置されている学校保健技師を活用して、ガイドラインへのアドバイスとか、その後のルールの徹底などを協議してはいかがかと思いますが、見解を伺います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"２点目の密を防ぐための時間設定は、恐らく委員がおっしゃったとおりでございまして、校庭の広さもありますから、それに応じて交錯しないようにという工夫だと考えております。区内におきましても、各学校にはそれぞれ学校医もおりますし、教育委員会も仲立ちをしながら、様々な形で保健関係の指導等を行っていけると考えておりますので、なかなか学校保健技師を使ってというのは。","voiceIndex":99,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"それぞれ事情はあると思いますけれども、あちらも役割ですので、ぜひ活用を検討してみてください。それから、給食着です。この問題は感染症対策の質問であると同時に、香りの害についての質問です。これは学校ごとの判断なのかを伺います。理由は感染症対策でいいので、感染症対策として給食着の使い回しはしなくてよいと校長会などで事例として報告して、全体化してほしいのですけれども、いかがでしょうか。","respondent":"篠田学務課長","answer":"今回そういった形で感染症対策というような意味合いで、学校の判断で使い回しをしないで、それぞれ持ってきていいという判断があったということで、私どももそういった点については、各学校に対して柔軟に対応するように話していますので。","voiceIndex":102,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは指摘にとどめておきます。最後に、標準服の問題です。ある学校で選べる標準服が採用されたということなのですけれども、幾つかあるように聞いているのですが、スカートとパンツスタイルを選択できるということで評価したいのですけれども、これも学校単体の判断なのか、品川区としての方向性をこちらのほうに進めるということなのか、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"標準服につきましては、学校の判断です。","voiceIndex":104,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"これもなかなか制服になじめなくて、それからトランスジェンダーの問題などで悩んでいる生徒も多いかと思います。これについても学校単独の判断ということで、校長会で決めるということではないと思いますが、先ほどと同じように、こういう事例を事例報告として全体で共有化して、できたらそちらの方向に進めていっていただきたいと思いますが、改めてその点について見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"標準服のことですが、人権教育ではこの視点でも制服についてこちらで紹介していますし、そういうことを校長も全て研修を受けて理解しておりますので、委員のご心配は要らないかと思います。","voiceIndex":106,"id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"心配する必要はないということで、進む方向だと理解します。ぜひその方向に進んでいただくようお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"しかし、この基本方針をどこまで守っているのでしょうか。ずばり、この解決策というものはどこにあるのでしょうか。よろしければお聞かせください。教育委員会として、なくなることはないけれども大幅に減らしたいとお考えだと思います。やはり、いじめる側、そしていじめられる側ではなく、そのこと自体を傍観している児童・生徒がキーポイントになるのではないかと思っていますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"定義にありますとおり、本人がいじめと認識した場合、それはいじめと捉えるようになってありますので、本当はよかれと思って働きかけたことも、相手にとってはそれが嫌だったということがままあります。","voiceIndex":110,"id":"exchange-051"},{"speaker":"木村委員","kind":"質問・要望","question":"このいじめというものに対してはなかなか判断も難しいと思いますし、教職員の方々も、これは大変なことであろうと思いますけれども、頑張っていただきたいと思います。自分には関係のないこと、または触れたくないこと、関わりたくないと逃げ腰にならず、生徒たちが一致団結していじめる側と対峙する。教えてください。","respondent":"矢部教育総合支援センター長","answer":"話し合いの中で好事例は当然共有できますし、自分たちもやってきたという責任感や自負の弁が聞けて、大変有効だと考えております。","voiceIndex":112,"id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"本当は学校全体が一つになってこのことに対して取組んでいく。次に、３５７ページの下のほうにありますけれども、特色ある教育活動経費の中のしながわドリームジョブからの質問であります。この事業は将来の自分を見つける、やりたいことやなりたい自分を見つける事業だと思いますが、それでよろしいのでしょうか。","respondent":"工藤指導課長","answer":"本事業につきましてはご案内いただきましたとおり、児童・生徒が様々な分野の職業に就いている方のお話を聞くことで様々な職業について興味を持ち、自分の将来について考え、自分の夢を実現させるための具体的な方法を学ぶことをねらいとして行っているものです。","voiceIndex":114,"id":"exchange-053"},{"speaker":"木村委員","kind":"質問","question":"私は、要は、夢を持たせることが一番大事なことであろうと思っていますし、また夢とともに成長することも大事だと思っています。周りの大人たちが子どもの成長期にいかにして夢を持たせる環境づくりをできるかどうかが、大変大事なことだと思いますけれども、その点はいかがでしょうか。","respondent":"工藤指導課長","answer":"児童の中には、やはり身近な方から仕事についての様々な経験などを聞く中で、やはり自分の将来、どのような職業に就くのかということに興味を持ち、それが夢につながるものと考えております。","voiceIndex":116,"id":"exchange-054"},{"speaker":"木村委員","kind":"質問・要望","question":"近い将来、日本を背負っていただく子どもたちの夢がかなうための事業でありますから、頑張っていただきたいと思います。本区では小学校１年生から英語の授業を行っているとお聞きしました。我々の頃は中学校からの授業でしたが、本区の生徒は平成１６年頃から行っているとお聞きしました。なぜ１年生からになったのか、このことに対してご説明ください。","respondent":"工藤指導課長","answer":"品川区の英語教育についてのお尋ねです。品川区におきましては、平成１７年に告示をいたしました品川区小中一貫教育要領の段階で、１年生から９年間の系統的な英語教育を定めて、９年間で英語力、あるいはコミュニケーション能力を育むということで取組んでいるものです。","voiceIndex":118,"id":"exchange-055"},{"speaker":"木村委員","kind":"質問","question":"他区では小学校３年生から英語授業が行われているとお聞きしました。３年生からの授業でも驚きでありましたけれども、本区では１年生と聞いてなおびっくりいたしました。１年生からとすることで、何に一番変化があったかということをお感じになりますか。例えば成績の面においても、何か他区との比較、そういうことに対してもまたお答えください。","respondent":"工藤指導課長","answer":"国や都が行っております英語学習の状況調査におきましては、９年生の段階でいわゆる英検３級程度の技能を習得しているという割合につきまして、国の目標が５０％というものですけれども、本年度の速報値ですが、本区の９年生は８０％を超えているという状況です。","voiceIndex":120,"id":"exchange-056"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に何事にも一生懸命頑張る姿をまた見せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-057"},{"speaker":"松本委員","kind":"質問","question":"今の英検はすごいですね。私のほうは英検ではないですけれども、３５７ページのプログラミング学習、３６９ページ、学校維持管理費に関連して学校内の教師によるわいせつ事件防止対策について、３５３ページ、教職員人材育成経費に関連して、学校での家庭内児童虐待の早期発見について伺います。こちらについて、開催に至った経緯、内容、児童の感想もお聞かせいただければと思います。","respondent":"矢部教育総合支援センター長","answer":"ただ、実際のプログラミング学習は、小学校では５年生と６年生のそれぞれ理科、算数でやるのですけれども、どのような内容を位置づけていくかとか、本当のプログラミング学習の到達点はどこなのかということはこれから研究していくことだと思いますけれども。","voiceIndex":124,"id":"exchange-058"},{"speaker":"松本委員","kind":"質問・要望","question":"とりあえずそれはさておいて、むしろ子どもたちが興味を持っているゲームをどう教育につなげていくのかというところが重要ではないかと思っています。その点から、今回のこの特別授業というのは貴重な体験で、児童にとってすごくいいことではなかったのかなと私も思うのですけれども、ぜひ引き続きの検証、分析をしていただいて、実施校を増やしていただければと思いますが、区のご所見を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ一方で、スクラッチとかプレゼン画面とかというのも学校のほうで挑戦していますので、それも比較的子どもたちにとってはゲーム性があって楽しいものになってあります。様々な保護者や企業などと連携して、そういった活動を少しずつ広げていけたらと考えています。","voiceIndex":126,"id":"exchange-059"},{"speaker":"松本委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。次に、学校維持管理費に関連して、学校内の教師によるわいせつ事件防止対策について伺います。昨年、全国学校ハラスメント被害者連絡会は文部科学省に対して、公立学校のトイレと更衣室以外の場所への防犯カメラの設置を要望しました。現状、区立小学校・中学校の校内に、防犯カメラがどのくらい設置されているのか、設置場所など、現状がお分かりになればお願いいたします。","respondent":"有馬庶務課長","answer":"防犯カメラの設置数ですけれども、学校においては、小学校で２１７台、義務教育学校で９６台、中学校で４８台、合計３６１台ということで、各学校、小学校は４、５台を中心に、学校によって数が上下していると。義務教育学校は１０台から２０台ぐらいあるところもあります。","voiceIndex":128,"id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"それは、多分外から来る犯罪者というか、どちらかというと外部向けということで理解してよろしいでしょうか。","respondent":"有馬庶務課長","answer":"申し訳ございません。設置場所については玄関ですとか通用門ですとか、そういった外部からの侵入のところを見るというような形で設置しています。","voiceIndex":130,"id":"exchange-061"},{"speaker":"松本委員","kind":"質問・要望","question":"さらに一部の学校では、これはすごいのですよ。いじめや問題行動が多発するトイレや更衣室というところまで、監視対象にしている学校もあるとのことです。これは要望も上がっているところですので、学校の防犯カメラ設置について検討していただきたいと思いますが、いかがでしょうか。","respondent":"有馬庶務課長","answer":"現状、トイレの中を見るですとか、どこか適当な教室内を監視するとか、そういったところには多分設置していないと思います。","voiceIndex":132,"id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"体のあざとかは確かにすぐ報告が行くと思うのですけれども、ネグレクト関係というのがやはりなかなか判断が難しいようで、そこでお伺いしたいのですけれども、身体的虐待以外の例えばネグレクトの兆候、例えば忘れ物が多いとか、そういったところはどのぐらい学校の教員の間で指導研修が行われているのか、お願いいたします。","respondent":"矢部教育総合支援センター長","answer":"虐待のお尋ねです。この３月にまた校内で研修を行いますので、改めてチェックリストの活用も促します。","voiceIndex":134,"id":"exchange-063"},{"speaker":"湯澤委員","kind":"質問","question":"私からは３６５ページ、学校ＩＣＴ活用経費、それから３５７ページ、プログラミング学習について質問します。区でご用意いただきましたＧＩＧＡスクール端末を教材として活用した授業が本格スタートいたします。保護者からは、動画による端末やアプリの説明を区の教育委員会のホームページにて行ってほしいという意見もありましたが、今後行う予定があるかも併せてお知らせください。","respondent":"工藤指導課長","answer":"その見方につきましては、基本的にタブレットの中からそれを見られるような形で考えておりますので、またそれができましたら、そこで見られるということも併せてお知らせしていきたいと考えています。","voiceIndex":137,"id":"exchange-064"},{"speaker":"湯澤委員","kind":"意見","question":"保護者にも丁寧な説明がされているということで、安心いたしました。誰に対して、どのような指導をする目的となっているのか。これまでボランティアの方たちが教員と協力してオンライン朝学活などを行ってきた事例がありますけれども、児童・生徒に対して、地元企業やＰＴＡ、子ども支援団体などがＧＩＧＡスクール端末を利用して連携を図っていくことについてはどうお考えになっているかをお知らせください。","respondent":"篠田学務課長","answer":"ＩＣＴ支援員に関するお尋ねです。ＩＣＴ支援員は、ＩＣＴに関しての研修活動等に特化した専門の会社から品川区の対応者を決めた上で、派遣をしてもらっているということで、委託事業となっています。","voiceIndex":139,"id":"exchange-065"},{"speaker":"湯澤委員","kind":"意見","question":"教員や児童・生徒だけでなく、保護者に向けた支援策などについても、成果が期待できるものに対しては柔軟に支援していただくことをご検討いただければと思います。自宅学習において、児童・生徒、保護者が準備しなければいけないもの、また注意が必要なものがあれば、併せてお知らせください。","respondent":"工藤指導課長","answer":"いわゆる使い過ぎなどは一定程度制限できるようにしておりますが、学校でのルールに加えて、家庭でもルールについてお話し合いをしていただくなど、働きかけをしています。そういったものを通しながら、よりよい運用、また活用を図っていければと考えています。","voiceIndex":141,"id":"exchange-066"},{"speaker":"湯澤委員","kind":"質問","question":"タブレットの活用についても幾つか質問します。区内の複数校でボランティアにより始まった給食メニューや学校スケジュールといったものが、保護者の間で好評のようなのですけれども、ニーズが多いようであれば、品川区が主導して学校のオープンデータ化を進めるべきと考えますが、いかがでしょうか。学習目的であれば、貸与されたタブレットはどこでも誰とでも利用が可能なのか、以上４点をお願いいたします。","respondent":"工藤指導課長","answer":"やはりそういったところで運用を検討していきながら、できるところから進めていくことが重要であると考えていますので、そのようにしていきたいと考えています。","voiceIndex":143,"id":"exchange-067"},{"speaker":"湯澤委員","kind":"確認","question":"ただ、スマートフォンやタブレットといったもので確認をしたいという方も少なくないと思いますので、両方そろえるのは大変かもしれませんが、今後ペーパーレスの観点からも、データ化を中心にそれぞれのニーズに合った対応をお願いしたいと思います。タブレットの利用についてを続けます。今後、リアルとオンラインの同時開催なども視野に入れていくことを検討すべきかと思いますが、いかがでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"ですので、そういった利用につきましては保護者の意見、また学校のほうでも活用について検討してまいりたいと考えています。ただ、もう既に小学校のほうは算数、理科で使うことになってありますので、今ある端末ですとか、教師が表示している画面において進めていくことと認識しております。","voiceIndex":145,"id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問・要望","question":"学校でのタブレットの利用に際し、どのような形でモラルとルールの教育をしていくのでしょうか。先ほどもご答弁があったとは思いますけれども、児童・生徒を孤立させないために、抱いている悩み事を誰にでも相談できるよう、チャイルドラインのようにいつでも必ず気持ちを受けとめてくれるような命を守るアプリを導入するべきとも思いますが、ご見解をお知らせください。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"ＳＮＳのルール等ですけれども、やはり今回タブレットが配布されたということで、ＩＣＴリテラシーも含めて、そういったものを効果的に活用しながら、より質の高い指導が、また教育ができるものと考えています。相談機能につきましては、繰り返しですけれども、アイシグナル、あとチャイルドラインというところのＱＲコードを読み込んで、子どもが直接そこにアクセスできるような形を考えております。","voiceIndex":148,"id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問","question":"私からは３６７ページ、学校環境整備事業、３６３ページ、電子図書館、３６５ページ、学校ＩＣＴ活用経費、時間があれば、３７１ページ、給食運営費を伺います。学校環境整備事業で、前々から何度かお伺いしている台場小学校の避難通路の件です。ご存じのとおり、台場小学校は品川浦のそばにありまして、非常に標高が低い場所にあります。この点、現在の進捗状況を教えてください。","respondent":"小林学校施設担当課長","answer":"私の聞いているところでは、現在お隣の都営住宅の入居者の２分の１の同意を取るというお話を聞いております。同意が取れ次第、覚書書を取り交わすそうです。締結後、区としましては、速やかに令和３年度内には工事を進めたいと考えております。","voiceIndex":153,"id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"どうぞよろしくお願いします。きのうで東日本大震災からちょうど１０年でありました。続きまして、電子図書館です。午前中も質疑がございました。２点お伺いします。この図書館流通センター、ＴＲＣですね。もう一つ、ＧＩＧＡスクールで配布されたタブレット、ここからの電子図書館の視聴というのは可能なのでしょうか。可能にしていただきたいという趣旨での質問ですが、よろしくお願いします。","respondent":"横山品川図書館長","answer":"２３区の状況から見ますと、今６区が導入している状況ですが、全てＴＲＣのＬｉｂｒａｒｉＥになっておりまして、来年度、品川区も含めて６区がまた導入予定ですが、おそらくは大勢を占めるものと思われます。","voiceIndex":155,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問","question":"よくわかりました。学校ＩＣＴ活用経費でＧＩＧＡスクール構想、タブレット端末が幾つか出ていますけれども、まずお伺いします。ＧＩＧＡスクール構想のＧＩＧＡというのは何のことでしょうか、教えてください。","respondent":"篠田学務課長","answer":"「Global and Innovation Gateway for All」です。","voiceIndex":157,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"意地悪な質問をして申しわけありません。品川区においてのＧＩＧＡスクール構想、先ほど午前中に、湯澤委員からどうやって保護者の方に周知をするのですかという使い方の周知の話はありました。品川区が目指すＧＩＧＡスクール、グローバルですから、世界的、地球規模のものと、こういう意味ですよね。そういうことを保護者にお示ししていただいているのかどうかも含めて教えてください。","respondent":"工藤指導課長","answer":"こういった内容の保護者への周知につきましては、これまでも広報等で行っている部分ではありますが、今申し上げたことをより保護者の方にもご理解いただくよう検討してまいりたいと考えています。","voiceIndex":159,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区は品川区らしいＧＩＧＡスクールをぜひ進めていただきたいと思います。ちょっと細かいところを伺います。タブレットです。私には今対象の子どもがいないので、対象のお子さんがいらっしゃる方はご存じなのでしょうけれども、以前、家庭用Ｗｉ－Ｆｉというのは脆弱性とかセキュリティの問題があるのでＬＴＥを導入するのだというようなご見解がたしかあったと思うのですが、伺いたいと思います。","respondent":"篠田学務課長","answer":"そうなりますと、自宅に持ち帰ってもつながらないのでは意味がございませんので、そういった場合に対応できるようにということと、また先ほど申し上げたとおり１カ月当たりの使用量という制限もあることから。","voiceIndex":161,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、そこの研究についてはぜひ絶え間なく行って、どういうものをやっていくのか、魂はどこに入れるのかという研究をよろしくお願いしたいと思います。今週の３月９日、プラスチック資源循環促進法案が閣議決定されました。ご存じのように平成３０年１２月には学校給食の牛乳にプラスチックストローを使用しないことを求める請願を全会一致で採択して、品川区にお届けしました。","respondent":"篠田学務課長","answer":"ストローの使用本数です。今品川区内の区立学校に通われているお子さんが２万２,０００人弱いらっしゃいまして、給食が年間で大体２００日弱実施されます。","voiceIndex":163,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"請願にも書いてあるのですけれども、２万２,０００人掛ける１９５日で年間大体４２９万本ということになっています。世の中がようやく今こういうふうになってきたというところで、やはりガラパゴスになってはいけないと思います。そこは学校教育の場で、率先して実践をしていただきたいということをお願いして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は３５７ページ、３目教育指導費、がん教育推進授業からがん教育について。３５５ページ、生徒指導対策等経費から新型コロナウイルス検査陽性の小・中学生の対応について、および３５７ページ、特色ある教育活動経費からメディアリテラシー教育について順次質問してまいります。がん教育についてお尋ねします。がん教育の目的についてご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"簡潔に２点申し上げます。１点目はがんについて正しく理解することができるようにすること、２点目は健康と命の大切さについて主体的に考えることができるようにすることです。","voiceIndex":167,"id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"教育委員会のご見解をお聞きしたいと思います。２０１９年の決算特別委員会の総括質疑でもＨＰＶワクチン接種と子宮がん検診の重要性を授業で取り上げることを要望しましたが、当時の教育次長のご答弁は９年生の保健体育の授業で感染症と予防について生徒は学んでいますというお答えでした。現在感染症とがんについてどのような授業が行われているのでしょうか、ご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"いずれもＨＰＶワクチンについて直接的には取扱っておりませんが、品川区では今年度から全区立中学校と義務教育学校後期課程において医師を講師としたがん教育を実施しており、その中で子宮頸がんやワクチンについて触れる機会がございました。","voiceIndex":169,"id":"exchange-078"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひＨＰＶワクチンについて、９年生のがん予防の学習の中で取り上げることを強く要望いたします。衛生費の款別審査でも触れましたが、昨年１２月にＨＰＶワクチンが男性にも適用が拡大されたことに関連して質問いたします。この男子に対するＨＰＶワクチンの情報提供もがん教育、性教育の重要な一環ではないかと考えますが、教育委員会はどのようにお考えでしょうか。","respondent":"矢部教育総合支援センター長","answer":"先ほどの答弁にも関わりますけれども、医師を講師といたしました授業については、男女一緒に共習で授業を実施しておりますので、子宮頸がんやワクチンについても男女ともに触れる機会はございました。","voiceIndex":171,"id":"exchange-079"},{"speaker":"鈴木（博）委員","kind":"質問","question":"新型コロナウイルス検査陽性の小・中学生の対応についてお伺いいたします。品川区の小・中学生の現在の新型コロナウイルス感染症の感染状況とそれぞれの新型コロナウイルス検査陽性者、または親が検査陽性のため濃厚接触者として自宅待機になった生徒への対応はどのように行われているのでしょうか。ご説明をお願いいたします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"それから緊急事態宣言が出た後の２月は７人という形で抑えられまして、現時点では２９校で８２名の感染者が確認されているところです。学校に登校できない間のお子さんですが、４月、５月にもあったとおり教材を家庭に配付することもございましたし、タブレットも配付されましたので、それを活用して学習の内容を提示したり、課題を見たりということで対応しています。","voiceIndex":173,"id":"exchange-080"},{"speaker":"鈴木（博）委員","kind":"意見","question":"「２０２０年○月×日の１６時３０分ごろ、かなりショックな事実を聞いた。逆に、なぜ政府がコロナウイルスに対して絶対にかかってはいけないというイメージを作り出して国民に広げているのかわからない。僕は今の世の中をコロナにかかった人や医療機関、それらの家族や友人、誰もが差別、偏見にさらされず、助け合っていけるようにするべきだと思う。区のご見解についてご説明を願います。","respondent":"矢部教育総合支援センター長","answer":"これは保護者も見られることになっております。自らの体験を語らせるという例がございましたが、児童・生徒の発達段階や保護者の意向等、実施に向けて配慮しなければならないことがあるとは考えており、今後もさまざまな方法を検討しまして、偏見・差別防止を進めてまいります。","voiceIndex":176,"id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在子どもの自殺が大幅に増えています。２０２０年４月から１１月の期間では３２９人と、２０１９年の同時期より７３人、３割近く多くなっています。多くの子どもたちは確実に追い詰められています。ワイドショーのあおり報道に影響されて右往左往する大人たちがたくさんおりますが、品川区はメディア対策をどのようにお考えなのでしょうか、一言ご見解をお願いします。","respondent":"矢部教育総合支援センター長","answer":"膨大な情報の中から必要な情報を取捨選択するということは大変大事なことでございまして、市民科を中心にＳＮＳを中心に指導していますが、他教科とも関連させまして、総合的に指導してまいりたいと考えております。","voiceIndex":178,"id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３５３ページ、教職員研修、３５７ページ、市民科・各教科充実経費、特色ある教育活動経費についてお伺いいたします。１点目に、教職員研修についてお伺いいたします。そこで、養護教諭の先生方などにユースクリニックを見学いただく機会を設けていただきたいと要望いたしますが、教育委員会のご見解をお伺いいたします。２点目に、市民科・各教科充実経費についてお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"養護教諭は、基本的に学校に１人しかおりませんので、研修に出かけるのはものすごく学校としては不安がありますので、回数、内容について十分吟味して検討してまいりたいと考えております。続きまして、人権教育です。全教育活動で行いますが、主に市民科を中心に進めております。","voiceIndex":181,"id":"exchange-083"},{"speaker":"横山委員","kind":"質問・要望","question":"東日本大震災後の被災地で活動した民間カウンセラーの話では、男性の相談のしづらさについて、プライドが高い、弱く見られたくないと考えているなどの理由で、心のケア、相談窓口に対しての抵抗が見られ、男性の場合、悩みやぐちを話したり、共感を得るよりも、子どもたちにあなたの経験を教えてあげてほしいといったようなグループセッションなど、褒められたり。","respondent":"矢部教育総合支援センター長","answer":"市民科におきましては、生命尊重について全学年で学習し、自殺予防については５年生以上でストレスや悩みの解消法、自分を大切にするなどの学習を通して言語化もその中に入りますが、系統的に指導しています。","voiceIndex":183,"id":"exchange-084"},{"speaker":"横山委員","kind":"質問","question":"相談場所の周知と、またそうした悩みの言語化というところにぜひ力を入れてお願いしたいというふうに思います。３点目に、特色ある教育活動経費についてお伺いいたします。グローバル給食の文字が予算書からなくなっておりますが、この経緯とグローバル給食の成果、また国際理解を深めていく今後の展開についてお聞かせください。","respondent":"篠田学務課長、工藤指導課長","answer":"来年度も検討をしたのですが、やはりこの状況はなかなかすぐには改善しないだろうということで、グローバル給食から給食を抜いてしまうと、この事業自体が成立しないということがありますので。今後におきましても、学校２０２０レガシーの取組みとして各学校の特色ある教育活動としても継続していきたいと考えています。","voiceIndex":185,"id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"レガシーとしてぜひグローバル給食を未来に引き継いでいただきたいと要望いたしますが、コロナの状況というのもあるかと思うのですけれども、その部分、教育委員会のお考えをお伺いいたします。時差の少ない友好都市のニュージーランド、オークランド市やアジア地域とのオンラインでの国際交流というのもご検討いただきたいと思いますが、教育委員会のお考えをお聞かせください。","respondent":"篠田学務課長、工藤指導課長","answer":"今委員からもお話がございましたとおり、新型コロナウイルス感染症の状況がどうなるかわからないということがあるので、なかなかそれが見通せないとどうなるか、はっきりとしたお話をしづらいところではあるのですけれども。イギリスにある学校との交流などを行っている学校も実際にありますので、そういった取組みを周知しながら、そういった部分の取組みも充実を図っていきたいというふうに考えてあります。","voiceIndex":188,"id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"８年生のオンラインによるフィリピンの方とのレッスンというのも承知しておりまして、そうした区内で行っているさまざまな活動をさらに広げていただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-087"},{"speaker":"おくの委員","kind":"質問・要望","question":"私は３５５ページ、学力定着度調査に関わって、いわゆる学力テストの中止を求めて質問いたします。昨年はコロナ禍の中、国と東京都は学力テストを中止しました。都に関しては今年以降もたしかやらないことを決めています。国や東京都が学力テストを中止したことで何か困ったことになったと、そういう声は上がったのでしょうか。この点、いかがでしょう。","respondent":"工藤指導課長","answer":"他の地区におきましては、さまざま学力調査を行っている自治体もありますけれども、聞き及んでいるところによりますと、国および都が行わなくなったことで新たに検討した地区もあるというふうに情報をいただいているところですが、繰り返しですけれども、本区においては。","voiceIndex":193,"id":"exchange-088"},{"speaker":"おくの委員","kind":"質問","question":"いろいろと言われましたけれども、特に困ったという声は上がらなかったということで理解いたしました。他方、今も言われましたように、品川区はそういう中、中止しないで実施されたわけです。品川区が実施されたのは、特に学力テストをやってもらわないと困るというような声が区民の方から上がったということなのでしょうか。この点いかがでしょう。","respondent":"工藤指導課長","answer":"学びの保障の充実というのは非常に大事なところですので、今年度学校が再開された後、児童・生徒の過度な負担にならないよう配慮しつつ実施をしたというものです。","voiceIndex":195,"id":"exchange-089"},{"speaker":"おくの委員","kind":"質問","question":"２月２４日の文教委員会に提出された事務事業評価シートを見させてもらいました。要するにテストの正答率の人数分布を上から４分の１ずつ、Ａ、Ｂ、Ｃ、Ｄと層に分けて、区全体でも、各学校でも分けて、各学校が把握し、比較することができるようになったというふうに文教委員会で説明されていました。こういう四分位分析をすることになったのは、そういう目的なのでしょうか、伺います。","respondent":"工藤指導課長","answer":"学力定着度調査におきまして、今年度四分位分析を用いながら、Ａ層、Ｂ層、Ｃ層、Ｄ層と２５％ずつの刻みの中で各学校が状況分析をしながら授業改善に活かしたところです。","voiceIndex":197,"id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"しかし、結果的に、客観的に序列がわかるわけです。これが現実だと思います。四分位分析はそれを簡単にして強化するわけです。学力テストはそういう結果を生み出すものだと、あるいは四分位分析はそれを強化するものだというふうにお認めにならないのですか。そういうものを生み出すということは大きな弊害を生み出しているのだというふうに認識なさらないのですか。伺います。","respondent":"工藤指導課長","answer":"学力定着度調査についてのお尋ねですが、私どもはやはり学校教育、また小中一貫教育を進めている中で確かな学力を身につけさせるというのが大事な目的です。知識、技能および思考力、判断力、表現力等、今学びを考える上ではさまざまな観点があります。","voiceIndex":199,"id":"exchange-091"},{"speaker":"おくの委員","kind":"質問・要望","question":"ところが、わかるというのは、例えば算数についても、理科についても、さまざまな心理、法則、物事の仕組みを発見していくわけですから、子どもにとっては喜びだと、そういうわけです。それで、序列と競争を生み出している、結果として生み出している、今そういう教育になっている、この大きな弊害を結果として生み出している学力テストはやめるべきだと思うのですけれども、いかがでしょうか、伺います。","respondent":"工藤指導課長","answer":"本区の学力定着度調査につきましては、前年度の学習内容、これは一問一答の知識だけではなく、算数においても、社会においても、見方、考え方も含めて定着を図っているものですので、引き続き実施をしていく考えです。","voiceIndex":201,"id":"exchange-092"},{"speaker":"芹澤委員","kind":"提案","question":"学校ＩＣＴ活用経費から伺います。私の希望としては、これからデジタルに関する課ができるというふうに伺っていますから、例えばそういったところが全てを取りまとめて、タブレットにはこういったものを入れたらいいのではないかというのを教育委員会に提案してもいいのかなと思っているのですが、現状どのようなお考えで外部のアプリを入れるというような予定なのでしょうか。","respondent":"篠田学務課長","answer":"ただ、今委員からお話がございましたとおり、さまざまな形で有益なアプリが存在することは十分承知していますので、入れ方については今区でまとめてというようなご提案もございましたけれども、そういったやり方ももしかしたらあるのかもしれませんし。","voiceIndex":204,"id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問","question":"明確に手続きの基準がわかったというのは大変よかったなと思っています。所管内の話、教育に関わるものに関して引き続き伺っていきますが、午前中も命を守るというようなお話があって、私からもいじめの相談窓口というのを以前問い合わさせていただいたことがあります。先ほどのご答弁の中で、ＱＲコードを読み取っていただいて活用していただければと。ご見解をお聞かせください。","respondent":"篠田学務課長","answer":"デスクトップにそういったショートカットを置くといったことに関しましては、技術的にそれほど難しくないものですが、内部的にこれから受付の窓口等の対応状況等もありますので、そういった点を踏まえながらできる手だては順次取ってまいりたいというふうに考えているところです。","voiceIndex":206,"id":"exchange-094"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ぜひ前向きにご検討いただければと思います。次の項目の給食運営費について伺います。午前中、小芝委員からも和牛の給食をしたらどうかというようなお話がありました。ちょっとそれに関連して給食のことをお伺いしていきますが、ＳＤＧｓとか、環境の話も出ていますけれども、今世界的に代替肉、大豆ミートが有名なものですけれども、代替肉というのが世界的に取り上げられています。","respondent":"矢部教育総合支援センター長","answer":"市民科においては、各学年で環境問題を扱いまして、８、９年生では生活の課題や国際社会への貢献などの内容もありますので、植物由来の肉と畜産による牛肉のＣＯ２の排出量の比較など、環境問題や食糧確保の上でも意味のある題材だと考えておりますので。","voiceIndex":208,"id":"exchange-095"},{"speaker":"芹澤委員","kind":"意見","question":"今は本当においしくなっていて、好き嫌いももちろん分かれるとは思いますが、それも議論になって、これでは食べられないよ、食べられるよという議論になって、これでまた食文化の多様性という議論もできるのかなと思っていますので、ぜひ大豆ミート、代替肉を使った給食というのを前向きにご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":210,"id":"exchange-096"},{"speaker":"せお委員","kind":"質問","question":"初めに、学校ＩＣＴ活用経費です。突然入院となってしまったお子さんなど、コロナ陽性時もそうですけれども、そういったお子さんと学校とをつなぐ準備は既に整っていますでしょうか。さらに、特別支援学校に籍を置くお子さんは、東京都がタブレットを準備するという認識でよろしいでしょうか。そこに区はどのように関与するのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"３点目、学校になかなか通えないお子さん、特別支援学校に在籍され、副籍ではきっと小・中学校にいらっしゃるのでしょうけれども、その関わりはどうかですが、これは都立の考えも十分伺わなければいけませんので、保護者やお子さん。","voiceIndex":212,"id":"exchange-097"},{"speaker":"せお委員","kind":"提案","question":"１年前の一般質問でオンライン授業もＯｒｉＨｉｍｅの活用もご提案しましたけれども、障害のある方へのこのようなツールの活用が当たり前になりつつあります。今ご答弁にもありましたが、特に区に行ってほしいのは副籍の学校との交流だと思います。次は、医療的ケア関連経費です。来年度、看護師２名配置の予算が初めてつきました。以前から要望していたので大変喜ばしいです。","respondent":"矢部教育総合支援センター長","answer":"３点のご質問をいただきました。１点目ですが、現状、既に就学前にお子さんとご家庭と学校とで連絡を取ってありますが、お入りになる予定の方は２名です。","voiceIndex":214,"id":"exchange-098"},{"speaker":"せお委員","kind":"質問・要望","question":"教職員に関してですが、研修を修了して認定されれば、医療行為のうち５項目の実施ができる認定特定行為業務従事者を積極的に取得していただきたいと要望します。このことは以前にも質問させていただいたのですが、状況も変わってきていますので、いま一度見解をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"お預かりしているお子さんの障害の程度にもよりますけれども、通常の学級でも例えば耳がちょっと聞こえにくいとか、視力が低いというお子さんにはかなり注力して、担任のほうも配慮して席を前にするとか、近くでお話ししたりとか、時折マイクをつけて。","voiceIndex":216,"id":"exchange-099"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、地域の学校ではもっと時間がかかるのは理解できるのですが、何より本人の未来のためにご家族、保護者から離れる時間というのを増やしていただきたいと思います。来年度以降、区において医ケア児を受け入れるとなると、どの程度ご家族、保護者に付添いいただく方針でしょうか。今お話しした現在よりも早期の段階で就学相談を行うということについても見解をお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"早めの就学相談ですが、６月からスタートしていますので、これまでの個別の教育支援計画等をいただきながら、早々に、前年度にお願いしたいと考えております。毎年３００件以上の就学相談を受けてありますので、体制のこともご配慮いただけるとありがたいです。","voiceIndex":218,"id":"exchange-100"},{"speaker":"せお委員","kind":"質問・要望","question":"最後に、特別支援教育費全般で、特別支援学級、特別支援学校と通常学級との交流についてお聞きします。本来であれば、同じ学校の一員であるので、みんな一緒にいることが当たり前になってほしいです。そして、今お伝えした好事例を区教委が積極的に情報収集し、区教委が情報発信をして全学校に取り入れていただきたいと思いますが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ、実態としてはどうしても特別支援学級でお伝えしたい連絡が朝にある場合は難しいということとか、ご本人の気持ちの整理がつかない場合なども聞いておりますので、毎日はちょっと難しいというのが現状だと聞いています。","voiceIndex":220,"id":"exchange-101"},{"speaker":"せお委員","kind":"質問・要望","question":"大切なのは意識とか気持ちとかで、特別支援学級などでふだんは分けられているのですけれども、通常のクラスに名前があれば、保護者はみんなと同じように考えてくれているのだと、それだけでも全然うれしく思います。そのような保護者の気持ちも考えて取組んでいただくよう要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-102"},{"speaker":"くにば委員","kind":"質問・要望","question":"そのような世論、潮流を受け、令和２年１０月２０日、文部科学省が各都道府県教育委員会宛てに出した通知において、学校、保護者間における連絡手段のデジタル化に向けた取組みを進めるよう押印の省略や学校、保護者間における連絡手段のデジタル化を進めることは、迅速な情報共有を実現するとともに、学校、保護者、双方の負担軽減にも大きく寄与するものであるため。","respondent":"工藤指導課長","answer":"ですので、全学校でさまざま運用を検討しながら、また導入について保護者の意見などを伺いながら、できるところから進めていきたい、運用していきたいと考えています。","voiceIndex":224,"id":"exchange-103"},{"speaker":"くにば委員","kind":"質問","question":"できれば、今お伺いしたスケジュールについてもう少し詳しくお聞かせください。","respondent":"工藤指導課長","answer":"学年ごとに試験的に始めながらということで随時始めていきたいと考えていますので、時期としては来年度４月以降に導入をしていき、今は明確な時期を申し上げられる段階ではございませんけれども、できるだけ運用のほうを図り、全学校で取組んでいきたいと考えています。","voiceIndex":226,"id":"exchange-104"},{"speaker":"くにば委員","kind":"質問","question":"大変期待しております。保護者に配付するプリントのデジタル化、こちらについてもお伺いします。学校から各家庭に配付するさまざまなプリント類について、紙とデジタルデータ、それぞれ利便性がありますけれども、基本的にはオールデジタルでデータ化を推進するべきと私は考えます。区教委の方針や実現可能な時期などを教えてください。","respondent":"工藤指導課長","answer":"保護者からは写真やイラストなどが貼り付けられている場合にカラーで見られるというところで大変好評を得ているところもありますので、そういった取組みについて各学校でも周知を図りつつ、そういったできるところから進めていきたいと考えています。","voiceIndex":228,"id":"exchange-105"},{"speaker":"くにば委員","kind":"意見","question":"やはりデジタル化の取組みが進むと、今聞いたようなわくわくするような事例も保護者の方々が実際に体験しているということで、非常に楽しみです。この点の取組みやお考えについてお聞かせください。","respondent":"工藤指導課長","answer":"校長会とも連動しながら、そういった意見を集約し、回答については随時各学校にお返しするというところで、時間を置かずに、そういった問い合わせについてもさまざま対応できるようにしています。","voiceIndex":230,"id":"exchange-106"},{"speaker":"くにば委員","kind":"質問・要望","question":"デジタル化ならではのスピーディーな情報共有、とてもすばらしい取組みができそうだと考えます。等しく全ての区内の学校において早急にデジタル化、オンライン化が進められるよう教育委員会から力を入れて各学校に取組みを求めることを強く要望します。全学校での学校、保護者間の連絡のデジタル化の取組みに向けて、目標と意気込みをお聞かせください。","respondent":"工藤指導課長","answer":"タブレット等の配備に合わせながら、さまざま電子化できるもので効率化を図れるもの等がありますので、それらにつきまして、できるものについては全学校で取組むという姿勢で学校のほうに指導しながら、またさまざまご意見もいただきながら。","voiceIndex":232,"id":"exchange-107"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、図書館運営費のティーンズ世代サービスについてお伺いします。こちらの事業については、令和２年度に新規事業として導入され、令和３年度も引き続き約６２０万円の予算を計上しています。は令和２年度の事業内容と令和３年度に向けた取組みをお聞かせください。","respondent":"横山品川図書館長","answer":"令和２年度につきましては、ティーンズ向けの資料を専用にそろえるという形で担当者を設定して担当者会を開き、選定基準を決めながら購入してまいりました。令和元年度と比べまして、倍増の資料の購入量がございまして、１,６００冊ほど増加しているような状況です。","voiceIndex":234,"id":"exchange-108"},{"speaker":"くにば委員","kind":"意見","question":"子どもの読書習慣の向上には、家庭での同居ご家族の読書習慣向上も重要なキーだと考えます。子どもたちに本を読んでもらうためには直接的な広報や事業だけでなく、親世代の読書習慣の向上についての施策も子ども世代の読書習慣定着にとっては重要だと考えますけれども、お考えや取組みをお聞かせください。","respondent":"横山品川図書館長","answer":"子どもに向けての計画ではありますが、家族みんなで読書をすることでコミュニケーションを高め、家族全員で読書に親しむというような取組みでございまして、子どもに本を勧めながら親も読む、また子どもから親に紹介してもらう。","voiceIndex":236,"id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"この令和３年度のクラブ・部活動等経費、あるいは校外授業費等の経費で、令和２年度にできなかったさまざまな事業やこういったものをフォローするような、そういった事業というのかな、そういうものを何か考えられているのかをお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"これは学校には記録のＤＶＤが配付されておりまして、大変好評だです。そのほか、６年生、９年生を中心に思い出作りということで、全期間、教育委員会を挙げて応援しているというところで、さまざまな企画をしてお出かけしたり、校外学習をやっているです。","voiceIndex":240,"id":"exchange-110"},{"speaker":"塚本委員","kind":"質問・要望","question":"一定の努力というか、取組みをされているというふうに思いますけれども、本当にかけがえのない１年間をこういったコロナ禍の中で思うに任せず過ごしてこられた児童・生徒のみなさんに対して、何とかこれをフォローするようないろいろな施策、これをぜひ区教育委員会として検討していっていただきたい、このように強く要望させていただきたいと思いますので、よろしくお願いいたします。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"今わかり得る範囲でお答えします。ただ、その特例の観点は教育課程が特例とされてありますので、例えば時間が１,０１５時間必要な教育課程を、それを減じて９００時間で可能にする、あるいは９８０時間で可能にする、その特例の部分においては、学習指導要領のねらい。","voiceIndex":242,"id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"この間、東京都とこの不登校特例校の設置等について、都が推進しているということだそうですけれども、品川区のほうでどういったやりとりがあったのか、なかったのか、東京都と区とのこれまでの経緯ということについてお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"家庭と学校の連携事業や不登校の加配教員の配置などによって効果が現れていると捉えておりますので、現在は東京都のほうに申請をしない、また考えていないです。","voiceIndex":245,"id":"exchange-112"},{"speaker":"塚本委員","kind":"質問","question":"今答弁いただきましたけれども、いわゆる適応指導教室という形で元の学校に戻していこうという道と、不登校が長引いて今回の不登校特例校というような形で新たな環境の中で卒業を目指していこうと、こういった二つの道、こういったものを設定するというか、不登校対応として生徒の状況に応じて作っていこうというふうになっていった。","respondent":"矢部教育総合支援センター長","answer":"こちらの不登校特例校は、繰り返してしまいますが、在籍校に戻れないという場合、他区市等は地域の学校に通わなければいけないという縛りが結構あるのですが、本区は学校選択ができることもあり、子どもたちに比較的選択の幅があるということがありまして。","voiceIndex":247,"id":"exchange-113"},{"speaker":"塚本委員","kind":"質問・要望","question":"学校ＩＣＴ活用経費で、これまでも多数の委員の方から取り上げられていましたけれども、私はまず第一に、昨年の決算特別委員会の総括質疑で質疑をさせていただいて、そのときに一人ひとりに個別最適化された学習を行うためには、授業の組立てなど教員の大きな意識改革が必要と考えますが、区の認識を伺いますというふうに質問させていただいて。","respondent":"工藤指導課長","answer":"委員からご指摘いただきました効果的な授業の展開モデル、また実践例をまとめた授業改善の指針となる教員向けの資料につきましては、既に作成しまして、令和２年１１月に配付したところです。","voiceIndex":249,"id":"exchange-114"},{"speaker":"塚本委員","kind":"質問・要望","question":"タブレット導入に関しまして、これまで議論があったかどうか、ちょっと私は記憶にないのですけれども、今学校には介助員とか学習支援員とかという方がつかれて、補助をされて、教育を受けている場合があると思いますけれども、こういった方々が今度タブレットを配付されて、各生徒がタブレットを使うに当たって、介助員とか学習支援員の方が何かしら戸惑うようなこと。","respondent":"工藤指導課長","answer":"非常に大切に扱っていると伺っておりますので、またそういった課題が見えてきたときには、やはり先ほどの学習支援員等、また教員とチームを組みながら、きちんと丁寧に指導していきたいと考えています。","voiceIndex":251,"id":"exchange-115"},{"speaker":"塚本委員","kind":"質問・要望","question":"すみません、時間がない。そうなので頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私は１項教育総務費から３５５ページの帰国児童・生徒等支援費、３５７ページ、学校と家庭の連携推進事業等、今お話の出た３５９ページ、マイスクール運営費関係からお聞きしたいと思います。先ほど不登校の実態として今品川区は出現率が低いというお話があったのですけれども、どのぐらいの人数が不登校で、マイスクールに通っているお子さんは何人ぐらいいらっしゃるのか、その辺から教えてください。","respondent":"矢部教育総合支援センター長","answer":"出現率は若干ですけれども、小学校も中学校も東京都より少し低いという程度です。後ほど、数字が出ましたらすぐにご報告します。すみません。","voiceIndex":255,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"確認","question":"低いという状況で理解はしますけれども、先ほど品川区ではいじめがないというお話だったのですが、傾向的なものもわかれば教えてもらいたいなと思います。それから、学校へ復帰できている児童や生徒はどのぐらいの割合なのか、当然学校で頑張っているので復帰していると思うのですけれども、その辺の確認をしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"不登校のお子さんでよくある傾向は、１回出てくるのですけれども、また休んでしまって、断続的なこともありますので、ちょっと復帰率を単純にはお伝えできないのですが、戻ってくるお子さんもいます。","voiceIndex":257,"id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私が見たところで、八潮は自発的な学習やその他の活動の場、五反田、浜川は個別学習を中心とした活動を行うというような特色を活かしてやっていらっしゃると思うのですが、今これをどこまで充実するのがいいのか、ちょっとその辺は判断がつかないのですけれども、やはりやっている間は生徒たちにとって効果的なものを進めていくために。","respondent":"矢部教育総合支援センター長","answer":"八潮のほうも今まで毎日はなかなかお子さんが来られないので、曜日を分けてできるだけいろいろなお子さんが来られるようにというふうに考えております。","voiceIndex":259,"id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。やっている限り充実してやっていただきたいなと思います。それから、このマイスクール、三つから選ぶ中で、これは自分で選ぶのですか。学校側でここがいいのではないですかと勧めているのか、ちょっと状況がわからなかったのと、今年の中学校卒業生の皆さんは、その後どういうふうにうまく進んだのか、その進学についてわかれば、その辺も教えてください。","respondent":"矢部教育総合支援センター長","answer":"八潮のほうは、地理的なところはあるのですけれども、小学生と活動のほうを中心にというお子さん、居場所としていらっしゃる方が多いという、そこにちょっと特色があります。進路です。おかげさまで中学生は全員進路が決まりました。","voiceIndex":261,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"意見","question":"進路が決まったということで非常によかったと思います。それから、先ほども出ていたのですけれども、学校と家庭の連携推進事業、これはやはり不登校という関係が出てくると思うのですが、教育委員会の事項別説明資料を見ていくと中身が出ていなかったのですよね。それはたしか東京都の事業ということからかと思うのですが、なぜそれが出ていなかったのか。","respondent":"矢部教育総合支援センター長","answer":"学校と家庭の連携推進事業は、東京都からも補助を受けているです。中身については、支援員とスーパーバイザーが入るという費用です。","voiceIndex":263,"id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問","question":"５校と事項別説明資料には出ているのですが、この５校というのは５人という意味なのか、それともその学校の中でまた何人かいるのか、その辺を教えてください。","respondent":"矢部教育総合支援センター長","answer":"その人たちは１人の場合もあれば、２人の場合もあります。もう一つ、先ほどちょっとお伝えしましたけれども、スーパーバイザー、専門の臨床心理士やお医者さんが見えて、年間２回教員に向けて適切な指導をしてくれるということでお金がかかっております。５校で実施しています。","voiceIndex":265,"id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一点のほうです。時間がなくなってしまったので帰国子女関係の教育ということでお聞きしようと思ったのですが、例えば中学生の交流という部分です。ニュージーランドのポートランド、リンフィールド・カレッジと交流して、基本的に教育委員会ではないかもしれないですけれども、今年度は行うことができなかった状況です。来年度に向けて、どう考えていらっしゃるのか、まず考え方だけ教えてください。","respondent":"工藤指導課長","answer":"今委員からご指摘いただきました国際友好協会が実施している青少年語学研修派遣事業におきましては、各中学校長の推薦枠をいただいておりまして、それを各校１名ずつで１５名を派遣しているものです。","voiceIndex":267,"id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今年度できなかったお子さん、新年度もちょっと状況がわからないのですが、ぜひ積極的に手を挙げたお子さんに対して何かかわいそうな状況もあるので別の方法がないかなというのも考えているのですけれども、例えば、これも国際友好協会のほうに絡んでしまうのですが、ジュネーブとの交流もあるので、今度そういうときにそういうお子さんが手を挙げたときには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-124"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは３５３ページ、教職員研修から自殺予防教育の一環としてのＳＯＳの受け止め方研修について、それから３６５ページ、学校ＩＣＴ活用経費、３７３ページ、保健運営費から生理用品について、時間があれば３６９ページ、校庭整備で人工芝についてもお伺いしたいと思います。教師と保護者がフラットな関係でＩＣＴ活用を模索するプラットフォームも視野に入れてはいかがかと思いますが、いかがでしょうか。","respondent":"工藤指導課長","answer":"来年度におきましても、上半期、下半期に分けて、必要なステップを学校に示しておりますので、各学校で活用を推進するように進めたいというふうに考えてあります。","voiceIndex":271,"id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"そういった意味からするとやはりまず保健室に置き、そして相談に結びつけるきっかけとしてはいかがでしょうかということ。それから、教職員研修についてもお伺いします。品川区でもいろいろと教員研修をされているとは思いますけれども、ＳＯＳの受け止め方研修、これを積極的に展開されてはどうかと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"先ほども答弁させていただきましたが、現状は各学校の保健室に予備が３０ほどあるというふうに聞いてあります。保健室にもらいに来る児童・生徒はほんのわずかということで養護教諭から聞いてあります。ほとんどのお子さんが家庭で用意しているだろうということでございました。","voiceIndex":273,"id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"それは、そこでもらえることを知らないというのが一つ。本来、生理は恥ずべきことではありません。しかし長年恥ずかしいこと、知られたくないこと、話題にしにくいものという誤った認識が広がっているために、それにまつわる悩みが可視化されてこなかったのではないでしょうか。これについて改めてお考えをお伺いしたいと思います。それから、校庭整備についてもお伺いします。それぞれご答弁をお願いします。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"恥ずかしいというのはよく納得できるところですので、さまざま配慮しながら子どもたちが嫌な思いをしないように対応していきたいと考えております。そういったところで子どもと一緒にこういったこともあるというようなことを学ぶチャンスがあるかと思いますので、今後検討していきたいと考えております。","voiceIndex":275,"id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"人工芝のほう、どうぞよろしくお願いいたします。そのことをしっかりと受け止めていただいて、どういうアプローチであれば、子どもたちに命や体を大切にするという気持ちを育むことができるのかということをゼロベースから組み立てていただければと考えています。最後は要望にして終わりますが、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３５２ページ、教育指導費に関連して禁煙、禁酒、薬物乱用防止教育について、それから３６１ページの特別支援教育費、医療的ケア関連経費と特別支援教育の推進計画をぜひ作っていただきたいという思いで質問をしたいと思います。禁煙、禁酒、薬物乱用防止教育についてです。品川区の飲酒、薬物依存防止の教育の取組みについてもお聞かせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"体に悪いということで、禁煙とか禁酒ということではなく、その害について指導をしているということです。薬物については、薬物乱用はいけないということで、そこでも同じ指導をしています。","voiceIndex":280,"id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成１７年にも改訂はされております。喫煙が習慣化されてから禁煙をという指導は大変困難を伴います。私はこのコマーシャルの規制に対しても、教育の現場からぜひ意見を上げていただきたいと思いますが、いかがでしょうか。それから、禁煙、禁酒、薬物乱用防止教育というのはたった１回きりではなく、回数、内容ともに継続してやっていくということが大事だと思うのですが、その点についても伺います。","respondent":"矢部教育総合支援センター長","answer":"コマーシャルについては、先ほどお話がございましたが、さまざまな意図を持って流される広告ですので、それを生徒自身が、私たちもそうですけれども、自身で考えを持って判断していくということにつながるのかと考えております。","voiceIndex":282,"id":"exchange-130"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"小学校で結局１時間だけですよね。中学校でも１時間だけ、私はもうちょっと系統的な形で、それがどれほど被害につながっていくのかということについて、ぜひもっと子どもたちに通じるような形で、これを本当にここで食い止めるということが大きな効果になっていくと思いますので、その点の拡充を求めたいと思います。依存症についてもです。次に、医療的ケア児についてお伺いしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"小学校が主だと認識しています。〔同日後刻に「小学校が３人、中学校が３人」と答弁訂正あり〕 ２点目の自宅で療養しているお子さんについては、ほぼ都立の特別支援学校と認識しておりますので、いらっしゃらないと把握しております。","voiceIndex":284,"id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これまでのように人工呼吸器をつけて、もしも通常学級に通いたいという場合は、これまでと同様、親が付き添って通うしかないと、今回そういう医療的ケア児への対応なのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"医療的ケア児の対応については、来年度予算をご議決いただけるということになれば来年度からということで考えておりますので、就学相談で決まらないことはお伝えできないようなところでございました。","voiceIndex":286,"id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"看護師２名の配置ということですけれども、これは学校看護師ということで確保されることになるのでしょうか。それとも、どこかに委託をされるのか、もし委託をするならどこなのかということについてもお聞かせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"現在人口呼吸器をつけていらっしゃる方は対象外になってあります。ですので、まだ本当にこれから始めるところですので、今後就学相談全てにおいて対応してまいりますけれども、現状医療的ケアをお勧めするときは、人工呼吸器をつけていらっしゃるお子さまは対象外にしています。","voiceIndex":288,"id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多くの区でこの計画を作っていまして、この計画の中で、特別支援教育の現状とか、それから推進、施策についてどんな取組みをしてきて、どんな成果があって、これからの課題がどんなものなのかというようなことが明確になって、次への計画に活かしていくというようなことで、私は前進のために欠かせないものではないかと思うのですが、区としてもぜひこの計画。","respondent":"矢部教育総合支援センター長","answer":"これまでも計画的に進めさせていただいていますが、特に義務教育学校の特別支援学級は前・後期ともに全て設置されたということで、一つこれが節目だったと考えています。ご存じのように人口の増加もありますので、今後も見通しを持って計画的に進めてまいりたいと存じます。","voiceIndex":290,"id":"exchange-134"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３５７ページ、特色ある教育活動経費、ＩＣＴ活用推進経費、３７１ページ、学校給食放射性物質検査費、３７５ページ、学校改築推進経費の中の源氏前小学校について質問します。最初に、ＩＣＴ活用推進経費です。これまでもほかの委員からさまざまな質問がございました。その研修の精度についてお伺いしたいと思います。","respondent":"工藤指導課長","answer":"研修につきましては、私どもは管理職向けに行いつつ、教員向けについては、各校に１名おりますＩＣＴ推進教員向けに行って、そのＩＣＴ推進教員が各学校で伝達するということをまずは進めてあります。","voiceIndex":294,"id":"exchange-135"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、午前中にも質問があったかと思うのですけれども、自宅でもタブレットを使用して、学校によってはＺｏｏｍ会議、Ｚｏｏｍでの保護者会とかをやられていると思うのです。そういった中の対応というのはどうされているのかをお伺いしたいと思います。","respondent":"工藤指導課長","answer":"私どもの方で先ほど申し上げたような教員向けの初めてガイド、初めてカリキュラムというのをさまざまお配りしておりますが、あわせて各学校からご家庭向けにもそういったものを同様に配布していただいているというふうに考えてあります。","voiceIndex":296,"id":"exchange-136"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして３７１ページ、学校給食放射性物質検査費についてお伺いいたします。今は不検出がずっと出ている中、今後も区として来年度はやる方向でいると思うのですけれども、やはり都内で連携してそういう東京都の教育委員会からの方向性、指示というのがあるのかどうか確かめていただきたいのと、ぜひとも検査自体を再来年度にはやめていただきたいというのが私の要望です。","respondent":"篠田学務課長","answer":"目黒区のお話をいただきましたけれども、私どもは専門の検査機関に出して検査をしてもらっているという状況です。再来年度以降につきましては、状況を見ながら判断してまいりたいというふうに考えているところです。","voiceIndex":298,"id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"確認","question":"はい、わかりました。そうすると、まだ再来年度というのはわからないということでよろしいのでしょうか。確認です。","respondent":"篠田学務課長","answer":"したがいまして、来年度どういった形になるか、その結果を踏まえまして、そういった実績も踏まえつつ検討していきたいと考えているところです。","voiceIndex":300,"id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。ぜひ検討していただきたいと思います。最後に、３７５ページ、源氏前小学校の改築のことで、来年度に敷地測量委託がついていまして、今年度は改築の計画検討というのがございました。具体的にどういった内容だったのかお知らせいただきたいと思います。","respondent":"小林学校施設担当課長","answer":"令和元年度に改築等の検討をしたところですが、これにつきましては、まず改築にするのか、増築にするのか、そちらのほうを比較検討したところです。","voiceIndex":302,"id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。やはり学校改築をするに当たっては、さまざまな問題があると思います。源氏前小学校も第４地区の防災訓練があったりとか、小学生のマラソン大会があったりする本当に拠点となっている小学校ですので、ぜひ改築の際はそういうことを踏まえて検討していただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-140"},{"speaker":"田中委員","kind":"質問","question":"給食の放射能測定について関連質問します。残念なことに、いまだに風評被害があるとの報道がありました。風評被害の解消は科学的根拠、データを示すことでしか拭えません。は検査方法を今の時期、状況に合わせて検出しやすい食材の単品検査に転換することで、子どもの健康を守るという区の姿勢を示すことにつながると考えますが、区教委の見解を伺います。","respondent":"篠田学務課長","answer":"それで、これまでずっと実績を積み重ねてきているということがありますので、来年度も同じ方法で実施することを想定しているものです。","voiceIndex":306,"id":"exchange-141"},{"speaker":"田中委員","kind":"質問・要望","question":"今年の２月１３日の地震による影響から格納容器の水位が低下しています。１１月３０日の文教委員会では、あたかも国自身が検査をして安全を確認しているかのような発言がありました。しかし、実際には自治体が検査をしており、しかも国が検査を求めている自治体は１７自治体のみです。これからも安全を確認するためにも検査の継続と単品検査への転換を求めますが、いかがでしょうか。","respondent":"篠田学務課長","answer":"今後の継続につきましては、今後これまでの実績等を踏まえながら、基本的に今まで出てきていないということを考えますと、また、あくまでも国内で流通している食材に関しては基本的に安全性が担保されているという前提で給食も運営しているですので。","voiceIndex":308,"id":"exchange-142"},{"speaker":"田中委員","kind":"質問・要望","question":"安全を確認するために検査を継続していただきたいです。単品検査も出やすい食材というのはわかっているので、ぜひそういった食材の検査に切り替えていただきたいと強く要望します。継続してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"物凄く厳しくやっています。もう福島県の人たちを、品川区は苦しめないでほしい。それから、３６９ページの教室等照明ＬＥＤ化工事費、これは何％くらいまで処理できていますかということを確認させてください。それから、３５９ページの保幼小連携推進経費ということで、これは、私立保育園と幼稚園との連携はどう考えられていますかということをお聞きします。この学校選択の現在の目的は何でしょうか。","respondent":"篠田学務課長、有馬庶務課長、工藤指導課長、小林学校施設担当課長","answer":"ですので、来年度の実施状況にもよりますけれども、結論ありきではございませんが、来年度ももし出てこないということになれば。学校用地の借地料です。現在残っている小学校４校ですが、山中小学校、延山小学校、宮前小学校、源氏前小学校です。それは、区内の公立・私立の幼稚園、保育園、全小学校、義務教育学校に配布しているものですので、公立・私立に関係なく。学校のＬＥＤ化の状況ですが、進捗率は約７０％です。","voiceIndex":315,"id":"exchange-144"},{"speaker":"西本委員","kind":"質問・要望","question":"ＬＥＤ化は７０％行われているということですので、１００％になるようによろしくお願いいたします。それが、同じ量で５００円だそうです。だけど、結局５００円でも売れなくて、家畜の餌になったそうです。検出していないわけですから、これから冷静に考えて対処していただけると信じておりますので、よろしくお願いいたします。学校選択制です。では、保護者の方々はどうなのだということです。","respondent":"篠田学務課長","answer":"なかなか入れない状況があるというのは、まさにそのとおりではあるのですけれども、ただ、そうはいっても、やはりそれぞれの親御さんが、自分の子どもに一番適した学校はどこかということを選べるというのを制度として担保されていることが、まずは重要だろうと考えていますので。","voiceIndex":320,"id":"exchange-145"},{"speaker":"西本委員","kind":"意見","question":"学校選択制については、地域での教育ということも含めて、やはり見直しをすべきときが来るかと思いますので、お考えいいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":322,"id":"exchange-146"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３６１ページ、特別支援教育費、３６５ページ、書籍除菌機、同じページで会計年度任用職員給与費、この３点を伺いたいと思います。特別支援教育費の中で、医療的ケアが必要な肢体不自由児のお子さんの学びの保障ということについて、お聞きしたいと思います。障害種別によって就学先が違うというのは、認識しております。","respondent":"矢部教育総合支援センター長","answer":"さらに医療に関わっている場合、また療育に関わっている場合もありますので、幼稚園、保育園等を含めて関係機関と連携を取りながら、適切な学校をご紹介するということになります。もちろん保護者とも十分に相談を繰り返してまいります。","voiceIndex":324,"id":"exchange-147"},{"speaker":"こんの委員","kind":"質問","question":"就学相談に対応してくださるということです。ぜひこうした実態を知っていただき、品川区においても、登下校への支援をお願いしたいというご相談でした。区は、こうした医療的ケアが必要な肢体不自由児のお子さんにおける登下校の実態について、どのように捉えますでしょうか。こうしたご相談を直接受けたときには、どのような対応が考えられますでしょうか、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"事前に就学相談をお受けいただいたときに、委員ご指摘のような場合は、学校はもとより関係機関とも連携しまして、都立学校の送迎について、その時期ですとか条件についてご紹介するところはセンターができることかと認識しております。","voiceIndex":326,"id":"exchange-148"},{"speaker":"こんの委員","kind":"提案","question":"この事業が実施されて、保護者の付添い期間が短縮化されれば、個人差があるとは思いますけれども、１年を待たず、スクールバスに乗車できる可能性も出てくるわけです。例えば先ほど申しました港区などを参考に、スクールバスによる送迎事業の創設、あるいはタクシー利用に対する補助の創設など、障害者福祉課とも連携して検討することを提案したいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ご事情は十分分かりましたけれども、都立学校ですので、今、進捗が都でもあるですので、そちらにお願いすることになって、現状を変えることはできません。","voiceIndex":328,"id":"exchange-149"},{"speaker":"こんの委員","kind":"提案","question":"しかし、区にお住まいの品川区のお子さんです。この医療的ケア児の学びの保障として、登下校における支援策を要望したいと思いますが、もう一度ご答弁をお願いいたします。次の質問も続けてまいります。次は書籍除菌機です。これまで何度か、区立図書館全館に配備をと提案し、要望してきました。今回、新規事業となっているわけですが、来年度の配備計画、スケジュール感も併せてお聞かせください。","respondent":"横山品川図書館長、矢部教育総合支援センター長","answer":"来年度５館に導入することによりまして、区立図書館全てに配備する予定になってあります。具体的には、源氏前、ゆたか、二葉、南大井、八潮に配備させていただいて、小さな館につきましては小型の機器を配備する予定です。先ほどの医療的ケアのお子さんの送迎についてですが、基本的には、都立学校ですので都立の方針を注視してまいりますが、区としてできることがあるのか、ないのかというところも含めまして、障害者福祉課とも連携して研究してまいります。","voiceIndex":330,"id":"exchange-150"},{"speaker":"こんの委員","kind":"質問・要望","question":"これは要望で終わります。次に参ります。このスクール・サポート・スタッフの配置は、各区立学校の全校で展開していると認識しておりますが、現状として全学校に展開できているのか、また、１校について何人ぐらい配置されているのか、配置された学校の職員の方から、配置されてどうだったのかという声などがありましたらお聞かせください。","respondent":"工藤指導課長","answer":"区内の現状では、全校合わせて７５名のスタッフに働いていただいておりますので、１名ないしは２名とお考えいただければと考えています。ただ、週４日５時間の勤務ができる範囲内で、それを２名で行う場合もありますので、合わせまして７５名とご理解いただければと存じます。","voiceIndex":333,"id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"３６７ページのルネサンス推進事業と、先ほど質疑が出ていましたグローバル給食について、重ならないように質問したいと思います。初めに、ルネサンス推進事業の特別教材購入１,９９９万９,０００円、サントレの現状、それと暗唱発表会などの現状をお聞かせください。令和３年度予算の内容、規模も教えてください。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"サントレの予算につきましては、実際に今、サントレが予算化されているのが４校ございまして、この１,９９９万９,０００円のうち４６５万８,０００円がサントレの教材費になってあります。サントレの現状ですが、コロナ禍ですけれども、各学校は工夫して取組んでおります。暗唱発表会は、浅間台小学校におきまして、普段は大きな声を出していますが、控えて実施し、また映像を配信して各教室で見られるなど、工夫しています。","voiceIndex":337,"id":"exchange-152"},{"speaker":"本多委員","kind":"質問","question":"４校全てで実施されているのですかね。よかったなと思いました。それで、工夫して進めているということですが、クラスとか学年とかで今までやっていたものの、その単位というのはどうなのか。それと、三木小学校のＹｏｕＴｕｂｅですが、ＹｏｕＴｕｂｅに撮って配信するのに、その撮り方というのはどういう規模で撮っているのか、その辺を教えてください。","respondent":"矢部教育総合支援センター長","answer":"私どもの捉え方では、低学年、中学年というふうに捉えてありますが、何分、学年を超えてとか、できればクラスを超えて集まることを控えるということでガイドラインの中にも示してありますので、各学校、現状は多分、クラスでやられていることが多いと認識しています。","voiceIndex":340,"id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"本当に工夫して実施されていて、よかったなと思いました。みんなスマートフォンですとか短縮で済ませてしまっているので、私自身もすごく分かるのですが、ドーパミンが一番活発なときなので、児童・生徒について、そういう暗唱とかをされているのが４校ということなので、これはまさに今、必要なのかなと思っているのですが、その点について教えてください。","respondent":"工藤指導課長","answer":"学習でタブレットを活用する際は、タブレットだけで行うのではなく、タブレットを効果的に活用する上で、また児童・生徒が主体的に学習に取組めるよう、特に自分の考えをまとめ、自分の言葉で説明し発表する、いわゆる暗唱も含めてです。","voiceIndex":342,"id":"exchange-154"},{"speaker":"本多委員","kind":"質問","question":"言葉を口に出すというのは、目で見るだけと全然違うのだなと、今、何か教えていただいた感じです。次の質問ですが、グローバル給食については、先ほどの質疑で令和３年度は予算計上されていない、実施困難ということで、見送りはよく分かります。それで、そのグローバルな視点について学ぶ機会がなくなってしまうのかどうなのかと思いまして、その点を教えてください。これは、一例を挙げます。","respondent":"工藤指導課長","answer":"この３月に入りまして感染状況が落ち着いているところですので、一部実地ということで、来ていただくことを予定している学校もあります。","voiceIndex":344,"id":"exchange-155"},{"speaker":"本多委員","kind":"質問","question":"それで、食からグローバルを学ぶというところですけれども、バレンタインデーというのは、世界では男性から女性にチョコレートをプレゼントするものですし、例えばワインは男性からつぐもので、女性からつがれるのは違うよとか、品川の子どもたちがいずれ世界に羽ばたくときに、グローバルに、実用的なという意味で、バレンタインデーは世界では男性が渡すものだよとか、テーブルマナーとか。","respondent":"矢部教育総合支援センター長","answer":"委員ご例示のバレンタインデーを含め、発展的に他国の生活について自らの考えを持つことができるような指導を、継続してまいりたいと考えております。","voiceIndex":346,"id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"順番は学校改築推進経費からで、これまでは敷地測量、基本設計、実施設計、工事という流れでしたが、令和２年度予算の測量実施校は城南第二小学校、鈴ヶ森小学校、令和３年度予算では基本設計が城南第二小学校だけで、鈴ヶ森小学校がなくなっていますが、そのあたりの経緯はどうでしょうか。区立幼稚園でいじめ、あるいはそれに近い事例があったかどうか、そういったことは報告がありましたでしょうか。","respondent":"有馬庶務課長、工藤指導課長","answer":"品川区内は就学人口が増えておりますが、特に品川地区、大井地区が増えているということで、このような計上をさせていただきましたが、城南第二小学校の先の見通しがより厳しいということで、結果としては。そういった意味では、クロス分析を予定していましたけれども、次年度、予定どおりに行われた場合は、それらの分析をしていこうと考えているところです。","voiceIndex":349,"id":"exchange-157"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その点はいかがでしょうか。休職についてですが、お休みになっている先生の代わりの講師の確保は、非常に大変と伺っています。ところで、特別支援教室の教員の休職については、手当が行われているのでしょうか。それからもう一つ、区固有教員の休職の場合の時間講師確保、あるいは産休代替教員の確保、病休代替教員の確保の仕組みは、都と一緒になっているのでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"加えまして、特別支援学級、また特別支援教室もありますけれども、そういったところも講師で対応しています。いじめの条例等ですが、これは就学前の方も、公立の幼稚園ではないお子様もいらっしゃいますので、こちらで研究していきたいと考えています。","voiceIndex":352,"id":"exchange-158"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区固有教員については、東京都の名簿を使うことができず、区独自で探していかなければいけないという点が厳しいので、都教委から来ているリストを使えるように、ぜひ都に働きかけていただきたいのですが、その点はいかがでしょうか。","respondent":"工藤指導課長","answer":"ご指摘いただきましたように、特別支援教室で休職等が出た場合は、やはりそれまでにいる教員の中で、分担校を増やすなどして対応しています。","voiceIndex":355,"id":"exchange-159"},{"speaker":"大倉委員","kind":"提案","question":"３７５ページ、第四日野小学校改築、３５１ページ、クラブ・部活動指導員経費、３６５ページ、学校ＩＣＴ活用経費を伺います。現在の部活動指導員で結構なのですが、どのような経緯でなっている方が多いのでしょうか、教えてください。いじめ相談では非常にいいご提案があったと思っているのですが、デスクトップ等で相談を簡単にできるようにしていただくというのも、非常にいいかなと思っています。","respondent":"小林学校施設担当課長、工藤指導課長、矢部教育総合支援センター長","answer":"我々も樹木医に移植ができないかという診断をお願いしたところ、移植についてはかなり難しいという答えが出たので。私どもで、タブレットの配布を今開始していますが、やはり学習で活用するというのを前提として、配布しています。現在、タブレットの相談窓口については２つほどご紹介させていただいたとおりですが、今後もいい相談窓口があれば、検討してまいりたいと考えております。","voiceIndex":359,"id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"例えば授業面とか学習面もそうですし、生活面というところでも取っていけば、例えば学習面であれば、一定の効果が、学習がうまくいっていないところがあれば改善できますし、生活面で遅刻が多い子がいれば、対応をその都度やっていくのでしょうけれども、できるようになっていくという部分で、それが連動していけば、例えば今まで成績のよかった子が、遅刻が増えて成績が悪くなったというところでは。","respondent":"工藤指導課長","answer":"委員ご指摘のログの部分でありますが、効果検証につきましては、令和３年度にそういった効果検証を行う委員会を立ち上げて、ログも含めて効果の検証を行う予定です。","voiceIndex":363,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は３５２ページ、教育指導費についてお聞きしたいと思います。できる、できない、個性を伸ばすというのは分かりますが、やはり基本的に教育委員会では子どもの学習指導というのをまず第一に、私は考えていただきたいと思います。教育委員会が一人ひとり、この学校にはどの程度の学力の子が何人いるのか、そういうことをしっかりと把握するべきだと思うのですが、ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういった意味では、ご指摘いただきましたように、各学校が、その各学校に在籍する児童・生徒の学力の状況等を把握しながら、授業改善に活かしていく、そういった状況を私どもも同時に把握しています。","voiceIndex":366,"id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"今、課長は同時に把握しているということですが、以前は各学校にお任せしていると。個々人の、例えばこのぐらいの学力のレベルの子はこの学校に何人ぐらいいるとか、そういうことを各学校で管理されていた。では、今は、教育委員会もしっかりと把握しているということでよろしいですか。","respondent":"工藤指導課長","answer":"今年度から導入いたしました四分位分析というものも、それが把握できるものです。各学校の四分位分析データも、今年度はコロナ禍で一斉の実施がなかったものですから、その集計等の公表は見送ってありますけれども、各校の状況は把握をしています。","voiceIndex":368,"id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"相当何層にも分かれていると思うのです。今、学力定着度調査は、教室を２つに分けて、３つに分けている場合もあるかもしれないですが、でも現実論、点数を０点から１００点、この子たちが取ったと。例えば２クラスで別々に習熟度別のクラスをつくっても、それは、なかなか指導というのは難しいではないですか。そういうのはどういうふうに底上げしようとしてやっているのですか。教えてください。","respondent":"工藤指導課長","answer":"習熟度別指導等のお尋ねだと思います。確かに算数、数学におきましては、例えば少人数指導、習熟度別の指導を行ってあります。授業以外の場面でも、補充学習が必要な場合は、各学校で補習、また品川地域未来塾で確実に定着を図るような取組みも行ってあります。","voiceIndex":370,"id":"exchange-164"},{"speaker":"須貝委員","kind":"意見","question":"区のアンケート調査によりますと、学校の勉強がよく分からない子や、学校より進んだ内容や難しい内容を学習塾で学んでいる子が、それぞれ全体の３割ぐらいいるようです。そういうデータが出ています。ニーズも、これだけのニーズがあるわけですよね。そのように大きなものになっていると思うのですが、その辺についてご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういった様々な取組みもありますけれど、私どもは、やはり学校教育の中でしっかりと力をつけていきたい。そのために、教職員含めて、努めているところです。","voiceIndex":372,"id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"そのニーズがこれだけあるというのは事実ではないですか。だって本来は学校できちんと、今、課長が、我々はやっていますと、この子たちの学力を定着させるために頑張っていますと言うなら、学習塾なんかに行かないのではないですか。それがこれだけ、６割、７割の子が学習塾に行かざるを得ないということは、やはりそこに何か問題があるのではないでしょうか。","respondent":"工藤指導課長","answer":"繰り返しではありますが、私どもは、やはり学校教育の中で育むべき力、また、そこでこそ学べるものをしっかりと教育していく、この品川区で一貫教育を進めていくです。","voiceIndex":374,"id":"exchange-166"},{"speaker":"須貝委員","kind":"質問","question":"次回、業者テストのテスト結果表を持参してください。そのときに進路指導をします」という返事をいただいたそうです。もう一度お聞きします。これはそういうふうにやっているのですが、今申し上げましたけれども、例えば私立に対しては、その保護者の方がおっしゃっていたように、今の学校では進路指導ができないということですか、教えてください。","respondent":"工藤指導課長","answer":"一部、予定にない高等学校が上がった場合であっても、その時にある手元の資料で十分な説明をし、一人ひとりの生徒の進学につきましては、真摯に向き合って対応しています。","voiceIndex":376,"id":"exchange-167"},{"speaker":"須貝委員","kind":"質問","question":"そこは少し気になるので再度お聞きしますが、私立に行く子もいるわけですよね。今、何か資料をもってご説明するというお話でした。それはどこから持ってくるのですか。何も資料がなくて、やれるのですか。それとも、やれると言うなら、どこにその資料があるのですか。何が根拠で、あなたはこの学校に合格できる可能性が高いと言えるのですか。もう一度お答えください。","respondent":"工藤指導課長","answer":"私立のそういった入試等の資料につきましては、高等学校から提示していただいている入試要項等、また入試相談等を私立の高校と中学校、義務教育学校の教員が行いますので、そういった資料を基にしながらお話をしています。","voiceIndex":378,"id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"それに対して、「いや、君には向いていないよ」、それはないのではないですか。そこに行くために努力しろという指導なら分かります。そうではないのではないですか。親御さんも一緒に来て、できればここへ向かいたいのだと、受験をしたいのだという気持ち、それを受け止めるのが学校の対応ではないですか。それが何もなかったら、何もできないではないですか。もう一度ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういった進路変更をする場合がありますけれども、変更した場合であっても、それが本当にその生徒に有益なのかどうかも含めての助言を与えつつ、やはりその生徒が納得し、また保護者も納得する進路が選べるよう、三者面談等を行っているです。","voiceIndex":380,"id":"exchange-169"},{"speaker":"須貝委員","kind":"質問","question":"ということは、その学校の担任の先生が、私は私立のことはよく分かりませんという発言をしたというのは、間違いであった、聞き間違いであったということでしょうか。でも、それには、データがなければ、そこに行きなさいと指導できないですよね。それが今、おっしゃっていることは違うから、そんなことがまかり通るのでしょうか。データが先ではないですか。もう一度教えてください。","respondent":"工藤指導課長","answer":"三者面談の例を挙げておられますけれども、その前後の経緯等を私は現在把握できておりませんので、どういった経緯でその教員がそうした発言をしたのか、また、区立学校でいえばどの学校なのかを把握してございませんので、それが間違いかどうかというのは、私のほうで今。","voiceIndex":382,"id":"exchange-170"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりそこに対しては、私はもっと真剣に取組んでほしいし、こういうわけでこうなのだよ、だから君はここは無理なのだよという指導を、根拠のある指導をしていただきたいと思います。ということは、これから１００年後どうなるのか。やはり子どもたちは人が育てる、教員が育てるのではないですか。それで、何とか品川区に教員の人事権を持ってこられないでしょうか。その辺についてご見解をお聞かせください。","respondent":"工藤指導課長","answer":"私どもは品川区に配置になった教員につきまして、配置当初から研修を行い、育成しています。委員ご指摘のように、制度上３年で異動する教員もいれば、通常、原則として言われている６年の年限を超えて残りたいという教員も、もちろんおります。","voiceIndex":384,"id":"exchange-171"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ、やはり品川区に骨を埋めるつもりで子どもの教育をしてもらう。それが私は大事なことだと思います。ぜひ人事権を取っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":386,"id":"exchange-172"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これはぜひ、こうした「国際セクシュアリティ教育ガイダンス」にもあるように、子どもたちの現実や発達要求に応えられていない、そして、国連・子どもの権利委員会からも勧告を受けているといった状況を、そういう認識に立っていただいて、遅れた性教育をぜひ前進させていただきたいと思うのですけれども、そうでなければ子どもを守ることはできないと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ここに変更はございません。","voiceIndex":388,"id":"exchange-173"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今も紹介しましたけれど、区の答弁、ただ現状において日本で一番大事なのは、暴力の加害や被害、傍観者にならないことが一番基本だと、前回の質問で答えていただいているのですけれども、こうしたことを守っていくためにも、加害者にも被害者にも傍観者にもならない、そのためには早期からの性教育、この遅れた状況。","respondent":"矢部教育総合支援センター長","answer":"状況はこちらのほうでよく理解して、国の方針に基づき、注視して、進めてまいります。","voiceIndex":390,"id":"exchange-174"},{"speaker":"石田（ち）委員","kind":"質問","question":"理解はされているということですけれども、国が言っているから国の言うように進めるということです。自分の体、相手の体、自分の性、相手の性、こうしたことを学び、大切にする。あれをしては駄目だ、これもしては駄目だとネガティブに教えるのではなくて、何がよくて、なぜ駄目なのか、子どもの心と体の変化に合わせて教えることが大切です。区は、性教育は人権との立場でしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"人権にとても関わるところですので、人権教育の１つと考えております。","voiceIndex":392,"id":"exchange-175"},{"speaker":"石田（ち）委員","kind":"質問","question":"しかし、今の学習指導要領では、中学生で性交渉は教えていません。受精や妊娠は取扱うけれども、その経過は扱わないものとしている。性に関係する専門家や産婦人科医は、１５歳から１６歳で妊娠率がぐんと上がり始めると。だからこそ、その手前で性交渉について教えるべきと言っています。私もそう思います。なぜ中学校で性交渉について教えないのか、伺います。おかしいと思わないのか、伺います。","respondent":"矢部教育総合支援センター長","answer":"なぜかというお問い合わせですが、以前もお話しさせていただきましたが、中学校の学習指導要領に、妊娠や出産が可能となるような成熟が始まるという観点から、受精、妊娠までを取扱うものとし、妊娠の経過は取扱わないものとするという示しがありますので、これに準じたものです。","voiceIndex":394,"id":"exchange-176"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"多くの専門家や、また産婦人科医の皆さん、あと人権を守る弁護士の皆さんからも、中学校で性交渉を教えない、受精とか妊娠については教えるのに、その経過を全く教えないというのはなぜなのでしょうか。この歯止め規定があるために、子どもたちが苦しむ状況をつくっているのではないでしょうか。歯止め規定をなくすように国に求めていただきたいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"外国の事情ですとか成果というのは、私どもも存じております。ただ、日本、世界に関わらず、一人ひとりのお子様や保護者についても考え方は違いますし、国の文化や歴史的な背景もありますので、現状、日本国につきましてはこの学習指導要領に準じて指導しています。","voiceIndex":396,"id":"exchange-177"},{"speaker":"石田（ち）委員","kind":"質問","question":"国によって文化も違います。しかし、今、子どもたちは多様性の中に生きているわけです。私たちや、また私たちの親世代とは、全然違う状況に置かれています。そして、私たち自身も、今も子どもたちが受けられていないのと同じように、きちんとした正確な性教育を受けてきたとは言えません。本当にこの性交渉が淫らな行為、不純だと言っているのと同じではないでしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"今、私どもの情報で、国の有識者会議でも、この包括的性教育についての会議が進んでいるということですので、あくまでも日本中がよりどころとしている学習指導要領の方針を我々は踏まえて、指導をしていきたいと考えています。","voiceIndex":398,"id":"exchange-178"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ現場から声を上げてほしいのです。国がそうだからうちもそうだではなくて、やはりこの遅れた状況を、ぜひ現場から告発してほしいと思うのです。そういったことを淫らだとか不純だとか、そういうふうに捉えてしまう、マイナスに、ネガティブに捉えてしまうことこそ、克服していくべきだと。マイナスのイメージしかない。ぜひトイレに生理用品を置いていただきたいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"生理用品の件につきましては、答弁が重複しますが、区でできることを検討していきたいです。","voiceIndex":400,"id":"exchange-179"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そんなの当然だろうという声もありまして、私も本当に驚きましたが、こうした状況を、正確に、ポジティブに教えていくこの包括的性教育を進めていただきたいですし、本当にジェンダーを基本に、そして人権であるということを基本に、改めて考え直していただきたい。そして、包括的性教育の立場に立って、品川区の今の立場の改善を求めたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"委員からお話がありましたが、ジェンダー以外にも、人権とか暴力・安全、人間関係等がこのユネスコの包括的性教育にもありますので、いろいろなところで、１つの事実を取って進めるということではなくて、全体的に、教科であれば横断的に進めていくことが重要だと考えています。","voiceIndex":402,"id":"exchange-180"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この包括的性教育は５歳から行われるのです。５歳から、正しく、ポジティブに、正確に、科学的に教えられることで、子どもたちは自分のことも相手のことも大事だと、命なのだと認識することができます。ですので、日本でも早い段階から、包括的性教育の立場で実施していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":404,"id":"exchange-181"},{"speaker":"大沢委員","kind":"質問","question":"３５１ページの就学事務費、そして３５３ページ、先生方、職員の件、それと３５５ページ、入試について、３点伺います。順不同になるかもしれませんが、ご容赦ください。最初に就学事務費ですけれども、後地小学校の件です。小山小学校もあります。そこら辺のところを、お分かりになる範囲で結構ですので教えてください。","respondent":"篠田学務課長","answer":"後地小学校の状況です。後地小学校につきましては、１０月１日現在の住民基本台帳登録数が８７名であったところ、申請等につきましては７１名の方が入学の申請をしてきたという状況です。","voiceIndex":406,"id":"exchange-182"},{"speaker":"大沢委員","kind":"質問・要望","question":"８７名、後地小学校へ行けるということですけれども、あの距離からかなり近い人ですと、あの周辺は交通の量が非常に多く、過日、後地の交差点でも事故が起こったところで、そこら辺、通学路についての検討はもうされていると思いますけれども、通学路についての検討状況を教えていただきたい。","respondent":"有馬庶務課長","answer":"まだ学校に直接確認はしてございませんけれども、学区が変わるということで、通学区域の見直しは、当然学校のほうで行っていると考えているところです。","voiceIndex":408,"id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"これでこの質問は終わります。次に、３５５ページ、入試ですけれども、前回の決算特別委員会で、中学校、あるいは高校、塾と、出題範囲がばらばらで、このコロナ禍で統一されていない旨の情報を私は保護者の方からいただきまして、その旨の質問をさせていただきましたけれども、その後、今回もう入試も終わりましたが、それを振り返ってみてどのような状況であったのかを教えてください。","respondent":"工藤指導課長","answer":"私立につきましては、その学校の判断で入試の出題範囲等が勘案されたところですが、本区の９年生の学習状況は、どんな範囲に設定されたとしても、従来どおりの入試と変わらず、できるだけの計画で、指導計画上進行したことが把握できておりますので、そういった意味では。","voiceIndex":410,"id":"exchange-184"},{"speaker":"大沢委員","kind":"質問・要望","question":"そのところにおいて大きな混乱がなかったというのは、何よりだと思います。では、今度は職員のほうですけれども、人が集まると必ずトラブルというものがあるわけで、職員の方のトラブルの処理の仕方については、現場の最高責任者である校長先生が責任を持って対処されるのか、あるいは、身分が東京都でありますから東京都のほうに行かれるのか、そこのところを教えていただきたい。","respondent":"工藤指導課長","answer":"ただ、それらのところで、いわゆる服務管理は私どもが行っている、また学校長が行っておりますけれども、例えば全体の服務的な処分等になりますと、東京都教育委員会で行うことになりますので、そういった流れがあろうかと存じております。","voiceIndex":412,"id":"exchange-185"},{"speaker":"大沢委員","kind":"質問","question":"そこで第三者が入った場合、例えば訴訟沙汰が起きた場合はどのように対処されているのか、教えてください。","respondent":"工藤指導課長","answer":"仮に訴訟があった場合の対応ですが、その訴状も、例えば個人が訴えられる場合、また自治体が訴えられる場合、それぞれあろうかと思いますけれども、教育委員会におります訟務員にも相談しながら、対応しています。","voiceIndex":414,"id":"exchange-186"},{"speaker":"大沢委員","kind":"質問","question":"要は情報を出す場合に、４つか５つぐらいの要件があったと思います。個人に関わるものとか様々あると思うのですが、そこの情報の出し方について、どのような方法、どのような形で情報を出されているのか教えてください。","respondent":"工藤指導課長","answer":"そういったものについては一定程度、東京都がプレス発表を行っておりますが、そういったものに関して区教育委員会としてプレスをするということは、処分事例についてはないです。","voiceIndex":416,"id":"exchange-187"},{"speaker":"大沢委員","kind":"質問","question":"東京都のほうですけれども、やはり知り得た情報を出す判断、出さない判断、有益な情報、それと、また区にとって不利益な情報、情報の出し方にもいろいろとあるわけですけれども、そこら辺の判断基準はどのようにお考えですか。","respondent":"工藤指導課長","answer":"マスコミ対応等を私どもが行う場合は、例えば個人情報に関わることで出すべきではないというところは一定程度保ちつつ、また、どういったことで問い合わせがあるか、学校の取組みでありますとか、私どもから積極的に広報すべき内容等であれば。","voiceIndex":418,"id":"exchange-188"},{"speaker":"大沢委員","kind":"質問・要望","question":"別の委員会でも少しこれを質問させていただきましたけれども、情報管理については自助しかあり得ないわけですので、そこのところ、公の助けもありますけれども、情報管理については自助のみということですので、様々な情報リテラシー等々を皆さんで検討していただきながら、先生方、現場に不利益がないような情報の提出をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":420,"id":"exchange-189"},{"speaker":"たけうち委員","kind":"質問","question":"初めに、生徒指導対策費で防災教育です。それから、先に学校ホームページですが、昨年の予算特別委員会で、いわゆるコロナの情報提供について、各学校のホームページに載せているもの、載せていないもの、ばらばらではないでしょうかということを少し指摘させていただいて、昨年かな、ホームページが全部統一されたような感じで、きれいになっていまして、必要事項が項目としては統一されていると。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"避難訓練が月に１回ありますけれども、そのときに必ず校長の講話がありますので、例えば今般の３.１１の話などは、「３.１１を忘れない」という東京都から出ている資料を使って説明しています。私からは、学校のホームページについてお答えいたします。","voiceIndex":422,"id":"exchange-190"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからＬＧＢＴに限らず、今はそういういろいろな、差別なのか、人権なのか、本当に敏感になってきて、ある意味でそれがクローズアップされることは大事なことだとは思うのですが、一方で、悪気はなくて、１つの例で言うと、今そういうのがあるのか分かりませんが、体育の用具を女子児童が運んでいるときに、先生が、男の子がいたら、「おまえ、男なんだから運んであげろよ」と言うことが。","respondent":"矢部教育総合支援センター長","answer":"そのとおり、人権教育に気をつけてまいりたいと思いますし、教員の苦労も分かっているつもりですので、校長会等でそういった配慮も気をつけていくようにと、併せてお話ししていきたいと思います。","voiceIndex":425,"id":"exchange-191"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、３５０ページ、学務費になると思うのですが、１つは、６年生、９年生で思い出づくりを計画していただきました。学校やＰＴＡ、子どもたちからも、思い出づくりに非常に感謝をしているという言葉を幾つか伺いました。緊急事態宣言が延長されましたけれども、当初３６校だったと思いますが、何校で実施できたのかを伺います。学校の教員の長期休暇も増加していると伺っています。","respondent":"有馬庶務課長、工藤指導課長","answer":"残念ながら１月に緊急事態宣言が発出され、その間、何校か中止というところがありましたけれども、現状では、これから行く学校も４校程度あり、それらを含めて２９校が実施という状況になっております。子どもがストレスをためたりしているですが、やはり大事なことは、学校という同じ学び舎で子ども同士が学ぶ、またそこに教員がいる、そこではマスク越しであっても言葉を交わす、笑顔を交わすことができる。","voiceIndex":428,"id":"exchange-192"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２９校、本当にやれてよかったと考えています。少しつらさが入ってもいいのかなと考えていますけれども、こういうことをぜひ増やしてほしいと考えています。それについてもお聞かせください。これは、今、予定しなくてはいけないのかもしれないけれども、ぎりぎりまで待って検討してほしいと思ったりもしているのですが、この３点をぜひ教えていただきたいと思います。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"お弁当を作らなくてよかったというのも聞いておりますので、様々な保護者や地域との間で、十分協議をして進めてもらいたいと考えております。引率した先生からも、本当に連れて行ってよかったという意見をたくさんいただいておりますので、本当にできたことはよかったと考えております。","voiceIndex":431,"id":"exchange-193"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、多様化する時代で、なおかつコロナ禍だということであります。子どもたちや保護者に対応していくということは大変なことと、もちろん考えておりますけれども、品川区としても、教育委員会、校長、また教員が一体となって、品川区に住んでいてよかったと思われる教育が実行できると、私は信じております。最後にその決意だけを伺って終わりにします。","respondent":"工藤指導課長","answer":"ただ、私どもは、やはり地に足をつけて目の前の子どもたちのためにしっかりと頑張る、その教職員等を指導しつつ、また地域の方とともにコミュニティ・スクールを進めつつ、子どもたちを育んでいきたいと考えております。","voiceIndex":434,"id":"exchange-194"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1138#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":131069,"voices":436}}]);
